VALUES
  ('cpiuris2025::181dd75365d67eeda3138229388417e5', 'doutrina', 'cp_iuris', 'Direito Empresarial — Constituição de Sociedades Anônimas', '## Constituição de Sociedades Anônimas

A constituição de uma sociedade anônima é feita em três níveis: requisitos preliminares, modalidades de constituição e providências complementares. Os requisitos preliminares incluem a subscrição do capital social por pelo menos duas pessoas, pagamento de 10% (dez por cento) do preço de emissão das ações subscritas em dinheiro e depósito no Banco do Brasil.

### Conceitos
- **Valor Econômico**: O valor econômico é o valor que os experts dizem que vale uma ação, representando o valor racionalmente pago por uma ação.
- **Preço de Emissão**: O preço de emissão é o preço que o indivíduo deverá pagar pela ação que subscreveu.
- **Ágio**: A diferença entre o preço de emissão e o valor nominal da ação, compõendo a reserva de capital da sociedade anônima.

### Referências legais
- Art. 12 do Código Civil

### Dicas de prova
- Reconheça os requisitos preliminares para a constituição de uma sociedade anônima.
- Entenda o conceito de valor econômico e seu relação com o preço de emissão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Direito Empresarial", "legal_refs": ["Art. 12 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:28:07.491145+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=108", "doc_key": "181dd75365d67eeda3138229388417e5"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '33abd3f73c27af182a2cdbc51ff4dd4cd0c1fcbf00a15e438ffe435b8889647f'),
  ('cpiuris2025::de63f9f74db34759202c3568693677d6', 'doutrina', 'cp_iuris', 'Direito Empresarial — Constituição de Sociedades Anônimas', '## Constituição de Sociedades Anônimas

A constituição de uma sociedade anônima envolve a subscrição do capital social, convocação de assembleia de fundação e aprovação da constituição após formalidades legais.

### Conceitos
- **Capital Social**: Investimento oferecido ao público para financiar a empresa
- **Subscrição Pública**: Procedimento pelo qual o capital social é oferecido ao público
- **Assembleia de Fundação**: Reunião dos fundadores para deliberar sobre a constituição da sociedade
- **Sociedade Anônima**: Forma jurídica de empresa que tem capital social distribuído entre os sócios

### Referências legais
- Art. 143 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre subscrição pública e privada
- Conheça as formalidades legais necessárias para a constituição de uma sociedade anônima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T03:28:41.675128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=108", "doc_key": "de63f9f74db34759202c3568693677d6"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '89804871a3b68a501dacd7d27b0df67916c73d59cfa863c7b38c4f4e0204735c'),
  ('cpiuris2025::d105697d5ccbfa0669628a7c1e39ef17', 'doutrina', 'cp_iuris', 'Direito Empresarial — Constituição e Valores Mobiliários das Sociedades Anônimas', '## Constituição e Valores Mobiliários das Sociedades Anônimas

Descreve as formas de constituição de sociedades anônimas, necessidade de registro e publicação dos atos constitutivos, valores mobiliários além da ação, como debêntures, partes beneficiárias e bônus de subscrição.

### Conceitos
- **Constituição Simultânea**: Constituição da companhia por meio de subscrição particular, sem necessidade de recursos externos
- **Incorporação de Bens Imóveis**: Dispensa a escritura pública quando se trata de incorporação de bens imóveis como integralização do capital social
- **Denominação da Companhia**: Expressão ''em organização'' é aditada à denominação da companhia enquanto não estiver concluído o processo de constituição
- **Registro e Publicação dos Atos Constitutivos**: Necessidade de registro e publicação dos atos constitutivos da companhia, comprovando a sua existência
- **Valores Mobiliários**: São representados por ações, debêntures, partes beneficiárias, bônus de subscrição e notas comerciais

### Referências legais
- Art. 153 da Lei nº 11.101/2005

### Dicas de prova
- Diferenciar entre constituição simultânea e pública
- Entender a importância do registro e publicação dos atos constitutivos
- Conhecer os diferentes tipos de valores mobiliários emitidos por uma S.A.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.109", "page_number": 109, "discipline": "Direito Empresarial", "legal_refs": ["Art. 153 da Lei nº 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:29:24.699135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=109", "doc_key": "d105697d5ccbfa0669628a7c1e39ef17"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ee005d222824dc5e097c53b4adc976695be691ea13a5a2872a0efb56819f4c0f'),
  ('cpiuris2025::16de20e4981c0da8de89d8cf4c016bb8', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tipos de Ações na Sociedade Anônima', '## Tipos de Ações na Sociedade Anônima

Existem duas classificações das ações na Sociedade Anônima: por direitos e obrigações conferidos e pela forma de transferência. As ações podem ser ordinárias, preferenciais ou de fruição, com direitos e obrigações específicos.

### Conceitos
- **Ação Ordinária**: confere direitos normais aos titulares
- **Voto Plural**: permite a adoção do voto plural, com até 10 votos por ação ordinária
- **Ação Preferencial**: sem direito a voto ou com voto restrito
- **Ação de Fruição**: não especificada em lei

### Referências legais
- Art. 109, da Lei n.º 6.404/76
- Art. 110-A, da Lei n.º 6.404/76

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre ação ordinária e preferencial
- Conheça o voto plural e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Direito Empresarial", "legal_refs": ["Art. 109, da Lei n.º 6.404/76", "Art. 110-A, da Lei n.º 6.404/76"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T03:29:58.310897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=110", "doc_key": "16de20e4981c0da8de89d8cf4c016bb8"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '97c49ebf94eae196e605a6fd8826ffc397eeb7679fac3c0fb79bdf4043f11906'),
  ('cpiuris2025::1f94e3d3846f794b11f9c0dddcb2b3d7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Voto Plural em Companhias Anônimas', '## Voto Plural em Companhias Anônimas

O voto plural é um direito concedido a certas ações de classe, permitindo que os titulares dessas ações votem mais de uma vez. O estatuto social pode exigir quórum maior para deliberações e as companhias abertas devem seguir regras específicas.

### Conceitos
- **Voto Plural**: Direito concedido a certas ações de classe
- **Ações de Classe**: Ações com voto plural
- **Estatuto Social**: Documento que define as regras da companhia

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre voto plural e voto normal
- Conheça as regras para a aprovação de prorrogação do voto plural', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:30:35.949653+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=110", "doc_key": "1f94e3d3846f794b11f9c0dddcb2b3d7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2a8be9d203cc67579464caa2a9751d369279ce4f63086a44040a841bde2a79df'),
  ('cpiuris2025::f8bf0c348f76c3a2585ed3ae92580b1b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Voto Plural em Companhias Abertas', '## Voto Plural em Companhias Abertas

O voto plural é permitido em companhias abertas que adotam a forma jurídica, sendo vedado em companhias abertas que não o adotam. O voto plural pode ser exercido por ações com voto plural ou por valores mobiliários conversíveis em ações.

### Conceitos
- **Voto Plural**: direito de voto conferido a ações com voto plural
- **Companhia Aberta**: entidade jurídica que adota a forma jurídica e tem ações negociadas em mercados organizados
- **Ações com Voto Plural**: ações que conferem direito de voto plural

### Referências legais
- Art. 12 da Lei X da Sociedade Anônima

### Dicas de prova
- Entenda a diferença entre companhias abertas que adotam voto plural e companhias abertas que não o adotam.
- Conheça as hipóteses em que o voto plural pode ser vedado, como a remuneração dos administradores ou a celebração de transações com partes relacionadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Direito Empresarial", "legal_refs": ["Art. 12 da Lei X da Sociedade Anônima"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:31:10.398006+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=111", "doc_key": "f8bf0c348f76c3a2585ed3ae92580b1b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '16bce8860026e9b3d5bd60701eba410532293bc029469636822c35e05e8ed3e8'),
  ('cpiuris2025::02398868524cdd64921cbb4d17e9cbba', 'doutrina', 'cp_iuris', 'Direito Empresarial — Voto Plural e Direitos do Acionista', '## Voto Plural e Direitos do Acionista

As empresas públicas e sociedades de economia mista não estão sujeitas às disposições sobre voto plural, e o direito de voto não é um direito essencial do acionista.

### Conceitos
- **Voto Plural**: direito de voto múltiplo
- **Empresas Públicas**: empresas controladas pelo poder público
- **Sociedades de Economia Mista**: sociedades que têm elementos públicos e privados
- **Direitos do Acionista**: direitos conferidos aos acionistas
- **Ações Ordinárias**: ações comuns de companhia aberta
- **Ação Preferencial**: ação que confere uma preferência ou vantagem ao titular

### Referências legais
- Art. 109 da Lei...
- Súmula N da STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre voto plural e direitos do acionista.
- Conheça as exceções para o voto plural, como empresas públicas e sociedades de economia mista.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Direito Empresarial", "legal_refs": ["Art. 109 da Lei...", "Súmula N da STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T03:31:39.023629+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=111", "doc_key": "02398868524cdd64921cbb4d17e9cbba"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '588c531838150ef685767330fbedf3acbea14ba2bf1728643547390288765131'),
  ('cpiuris2025::0d64db7cd1a7d6c9e90c428d4e286a4f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tipos de Sociedades', '## Tipos de Sociedades

Descreve os tipos de preferências ou vantagens das ações preferenciais, incluindo prioridade na distribuição de dividendo e direito de eleger membros da administração.

### Conceitos
- **Ação Preferencial**: ação com direitos especiais
- **Vantagem Política**: direito de eleger membros da administração
- **Golden Share**: ação preferencial de propriedade exclusiva do ente desestatizante
- **Ação de Fruição**: ação emitida para substituir ação amortizada

### Referências legais
- Art. 17 da Lei X
- Art. 18 da Lei X
- Art. 111 da Lei X
- Art. 44 da Lei X

### Dicas de prova
- Entenda a diferença entre vantagem política e golden share.
- Conheça o conceito de ação de fruição e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Direito Empresarial", "legal_refs": ["Art. 17 da Lei X", "Art. 18 da Lei X", "Art. 111 da Lei X", "Art. 44 da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:32:19.567030+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=112", "doc_key": "0d64db7cd1a7d6c9e90c428d4e286a4f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '9709a683f2f78eeff16dacab6eec47f0536f03e800c5908a398949db73cc58cf'),
  ('cpiuris2025::36e53a02a42805c97de1c1a662a7d92e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Forma de Constituição do Capital e Transferência de Ações', '## Forma de Constituição do Capital e Transferência de Ações

Explica que o capital pode ser constituído integralmente por ações ordinárias, mas não por preferenciais. Além disso, destaca as formas de transferência de ações: nominativas (transferida mediante termo em livro próprio) e escriturais (mantidas em conta de depósito).

### Conceitos
- **Ação Nominativa**: ação que só se transfere mediante termo em livro próprio
- **Ação Escritural**: ação mantida em conta de depósito
- **Capital de Companhia**: totalidade do valor das ações emitidas

### Referências legais
- Art. 20 § 1º da Lei...
- ...

### Dicas de prova
- Diferenciar entre ação nominativa e escritural
- Entender o significado de ''termo em livro próprio'' para transferência de ações nominativas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Direito Empresarial", "legal_refs": ["Art. 20 § 1º da Lei...", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:32:41.967612+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=112", "doc_key": "36e53a02a42805c97de1c1a662a7d92e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e73405cad8e3a9e44e267ab1922cd2e8f3a1deb118590cad5481bdb0ebc09d51'),
  ('cpiuris2025::268ca0d88df7ba90d41cdb8795fdfa54', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tipos de Societários e Valores Mobiliários', '## Tipos de Societários e Valores Mobiliários

Descreve os tipos de societários (ações, partes beneficiárias) e valores mobiliários emitidos por uma S.A. Além das ações, que conferem condição de sócio, existem outros valores mobiliários como debêntures e bônus de subscrição.

### Conceitos
- **Ação**: título que confere condição de sócio na S.A.
- **Parte Beneficiária**: título negociável sem valor nominal, conferindo direito de crédito eventual
- **Debênture**: valor mobiliário que não confere condição de sócio
- **Bônus de Subscrição**: valor mobiliário que não confere condição de sócio

### Referências legais
- Art. 34 da LSA
- Art. 35 § 1º da LSA
- Art. 46 da LSA
- Lei n.º 6.385/1976

### Dicas de prova
- Diferenciar entre ações e partes beneficiárias
- Entender o conceito de valor mobiliário em S.A.
- Conhecer as limitações da emissão de partes beneficiárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Direito Empresarial", "legal_refs": ["Art. 34 da LSA", "Art. 35 § 1º da LSA", "Art. 46 da LSA", "Lei n.º 6.385/1976"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:33:15.757748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=113", "doc_key": "268ca0d88df7ba90d41cdb8795fdfa54"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '4c9f16f2e1c6effd2d631c1831f9f20663ef411f045d4885d1fce4d71a4025ec'),
  ('cpiuris2025::1532fbb8a6bc972e68b742950735ab6f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Debêntures e direitos de crédito', '## Debêntures e direitos de crédito

Debêntures são títulos representativos de um contrato de mútuo, conferindo direito de crédito à companhia. São emitidos para se endividar e garantem o pagamento de um valor aos adquirentes.

### Conceitos
- **Debênture**: Título representativo de um contrato de mútuo, conferindo direito de crédito à companhia
- **Direito de crédito certo**: Direito de crédito que não é eventual, mas sim garantido
- **Direito de crédito eventual**: Direito de crédito que pode ou não ser exercido

### Referências legais
- Art. 52 da LSA

### Dicas de prova
- Entenda a diferença entre direito de crédito certo e eventual
- Conheça as condições da escritura de emissão das debêntures', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direito Empresarial", "legal_refs": ["Art. 52 da LSA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:33:50.466789+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=113", "doc_key": "1532fbb8a6bc972e68b742950735ab6f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ecc6f540de5fe3819ed0e1457475ca1966930e09882ac02806d36d8ee6d1841a'),
  ('cpiuris2025::a91591e804b0b8e284ca141b1eb3a757', 'doutrina', 'cp_iuris', 'Direito Empresarial — Debêntures e Bônus de Subscrição', '## Debêntures e Bônus de Subscrição

As debêntures representam um contrato de empréstimo entre a sociedade e os investidores, com cláusulas sobre pagamento, juros e garantia. Os bônus de subscrição conferem direito de subscrever ações do capital social.

### Conceitos
- **Debênture**: Título executivo extrajudicial que representa um contrato de empréstimo entre a sociedade e os investidores
- **Bônus de Subscrição**: Título negociável que confere direito de subscrever ações do capital social
- **Garantia Real**: Tipo de garantia real para debêntures
- **Garantia Flutuante**: Tipo de garantia flutuante para debêntures
- **Debênture Quirografária**: Tipo de debênture que não tem garantia
- **Debênture Subordinada**: Tipo de debênture que ficará abaixo dos créditos quirografários em um eventual concurso de credores
- **Título Executivo Extrajudicial**: Caracterização da debênture como título executivo extrajudicial

### Referências legais
- Art. 75 da LSA
- Art. 168 do Estatuto

### Dicas de prova
- Entenda a diferença entre garantia real e flutuante para debêntures
- Conheça as condições de emissão e exercício dos bônus de subscrição
- Avalie a competência da assembleia-geral e do Conselho de Administração em relação à emissão de bônus de subscrição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direito Empresarial", "legal_refs": ["Art. 75 da LSA", "Art. 168 do Estatuto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:34:35.474720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=114", "doc_key": "a91591e804b0b8e284ca141b1eb3a757"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '083e7a042fbf839be3cb140e1840fe2f29daa40d06c2969f576ede1b6da826e2'),
  ('cpiuris2025::c38e2c000929af39e38027fed959597f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Títulos de Crédito Não Conversíveis', '## Títulos de Crédito Não Conversíveis

Art. 2º, VI da Lei n.º 6.385/76: títulos de crédito não conversíveis em ações, regulamentados pela Lei n.º 14.195/21.

### Conceitos
- **Título de Crédito Não Conversível**: Título que representa uma promessa de pagamento em dinheiro
- **Título de Livre Negociação**: Pode ser negociado livremente no mercado
- **Nota Comercial**: Título executivo extrajudicial, que pode ser executado independentemente de protesto

### Referências legais
- Art. 2º, VI da Lei n.º 6.385/76
- Lei n.º 14.195/21

### Dicas de prova
- Distinção entre títulos de crédito não conversíveis e outros títulos
- Importância da nota comercial como título executivo extrajudicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direito Empresarial", "legal_refs": ["Art. 2º, VI da Lei n.º 6.385/76", "Lei n.º 14.195/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:34:58.376291+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=114", "doc_key": "c38e2c000929af39e38027fed959597f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '41668fdaebd9080231d04203530c4fe7a478145e6f1afd60fa897fc688abeb53'),
  ('cpiuris2025::08b6f3cb2dd925e547212959a19b4875', 'doutrina', 'cp_iuris', 'Direito Empresarial — Órgãos Societários e Assembleia-Geral', '## Órgãos Societários e Assembleia-Geral

A assembleia-geral é o órgão máximo da Sociedade Anônima, congregando todos os acionistas. Embora os acionistas que não possuem direito de voto possam participar da assembleia-geral e exercer o direito de voz, eles não podem votar nas matérias submetidas à análise de assembleia.

### Conceitos
- **Assembleia-Geral**: Órgão máximo da Sociedade Anônima
- **Competência Privativa**: Área de competência exclusiva da Assembleia-Geral
- **Direito de Voto**: Direito dos acionistas a participar e votar na assembleia-geral

### Referências legais
- Art. 121 da Lei n.º 6.404/76

### Dicas de prova
- Distinção entre competência privativa e competência ampla da assembleia-geral
- Importância do estatuto na definição de órgãos societários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Direito Empresarial", "legal_refs": ["Art. 121 da Lei n.º 6.404/76"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:35:39.501229+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=115", "doc_key": "08b6f3cb2dd925e547212959a19b4875"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '486a0216f4a9604d349a38cb62e0fe43688b8a4f1a661779c8299613035b5bec'),
  ('cpiuris2025::867d541ff852f5d2bc48012e1d3abdbb', 'doutrina', 'cp_iuris', 'Direito Empresarial — Ativismo societário do investidor brasileiro', '## Ativismo societário do investidor brasileiro

O parágrafo único do artigo 121 foi acrescentado para aumentar o envolvimento dos investidores brasileiros na vida da sociedade, contrastando com a tradição nos EUA.

### Conceitos
- **Ativismo societário**: Participação ativa de investidores em questões sociais
- **Investidor brasileiro**: Pessoa física ou jurídica que compra e vende ações no mercado
- **Lei n.º 14.195/2021**: Lei que regulamenta o ativismo societário

### Referências legais
- Art. 121 do Código de Comércio
- Lei n.º 14.195/2021

### Dicas de prova
- Entenda a diferença entre o ativismo societário e a participação tradicional dos investidores nos EUA
- Conheça a Lei n.º 14.195/2021 e seu impacto no mercado de capitais brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.115 (2)", "page_number": 115, "discipline": "Direito Empresarial", "legal_refs": ["Art. 121 do Código de Comércio", "Lei n.º 14.195/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:36:03.716812+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=115", "doc_key": "867d541ff852f5d2bc48012e1d3abdbb"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3838ed35d6c5092b4c830a826d99371c5d70d256bd067f3de92a2f91e4cd3490'),
  ('cpiuris2025::85cdaf440cc1003c50537b4772020583', 'doutrina', 'cp_iuris', 'Direito Empresarial — Assembleia Geral de Sociedades Anônimas', '## Assembleia Geral de Sociedades Anônimas

A assembleia geral é a reunião dos acionistas para deliberar sobre matérias específicas, como distribuição de lucro líquido e eleição de administradores. Existem assembleias ordinárias e extraordinárias, com regras específicas para cada tipo.

### Conceitos
- **Assembleia Geral**: Reunião dos acionistas para deliberar sobre matérias específicas
- **Assembleia Geral Ordinária**: Reunião ordinária da assembleia geral, com objetivos específicos (art. 132)
- **Assembleia Geral Extraordinária**: Reunião extraordinária da assembleia geral, para matérias não previstas na lei
- **Administração de Sociedades Anônimas**: Responsabilidade dos administradores pela gestão da empresa

### Referências legais
- Art. 131
- Art. 132
- Art. 122

### Dicas de prova
- Entenda a diferença entre Assembleia Geral Ordinária e Extraordinária
- Conheça as regras específicas para cada tipo de assembleia
- Lembre-se da importância do laudo de avaliação em sociedades anônimas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.116 (1)", "page_number": 116, "discipline": "Direito Empresarial", "legal_refs": ["Art. 131", "Art. 132", "Art. 122"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:36:37.838821+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=116", "doc_key": "85cdaf440cc1003c50537b4772020583"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8aea5308c5fc675d6ff4d1db1ca0386020ac2b7b5f88514b2f2b2849cc7b4f22'),
  ('cpiuris2025::434a151b2551e1e580ec7900116e80b1', 'doutrina', 'cp_iuris', 'Direito Empresarial — Quórum de instalação e deliberação em assembleia-geral', '## Quórum de instalação e deliberação em assembleia-geral

Resumo do quórum de instalação e deliberação em assembleia-geral, incluindo regras para reforma do estatuto social e assembleias extraordinárias.

### Conceitos
- **Quórum de instalação**: A quantidade mínima de ações presentes na assembleia-geral necessária para sua instalação
- **Quórum de deliberação**: A quantidade mínima de ações presentes na assembleia-geral necessária para tomar decisões
- **Assembleia-geral extraordinária**: Assembleia-geral convocada com o objetivo específico de reformar o estatuto social
- **Reforma do estatuto social**: Mudança no estatuto social da empresa, que requer quórum de 2/3 do capital votante

### Referências legais
- Art. 129, § 1º, inciso I do Código de Comércio
- Súmula 242 do Instituto dos Advogados do Brasil

### Dicas de prova
- Entenda a diferença entre quórum de instalação e deliberação
- Conheça as hipóteses de assembleia-geral extraordinária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.116 (2)", "page_number": 116, "discipline": "Direito Empresarial", "legal_refs": ["Art. 129, § 1º, inciso I do Código de Comércio", "Súmula 242 do Instituto dos Advogados do Brasil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:37:17.616147+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=116", "doc_key": "434a151b2551e1e580ec7900116e80b1"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '60fbdc6d35ffa3faad60aac860a0a0414b8edc5d51f8f7b71e2e22746b63e6e0'),
  ('cpiuris2025::763b059d6531074820f5b8ad39e68d9b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Conselho de Administração', '## Conselho de Administração

O conselho de administração é um órgão colegiado deliberativo que fixa as diretrizes negociais e tem caráter obrigatório em certas sociedades, sendo responsável por representar a sociedade legalmente.

### Conceitos
- **Conselho de Administração**: Órgão colegiado deliberativo que fixa as diretrizes negociais e representa a sociedade legalmente
- **Diretoria**: Órgão executivo da administração da sociedade, formado por diretores
- **Administração da Sociedade Anônima**: Responsabilidade de representar a sociedade legalmente
- **Estatuto**: Documento que estabelece as regras e normas para a administração da sociedade

### Referências legais
- Art. 138 da LSA
- Art. 139 da LSA
- Art. 145 da LSA
- Art. 146 da LSA

### Dicas de prova
- Entenda a distinção entre Conselho de Administração e Diretoria
- Conheça as atribuições e poderes do Conselho de Administração
- Identifique as sociedades que obrigatoriamente têm um Conselho de Administração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.117 (1)", "page_number": 117, "discipline": "Direito Empresarial", "legal_refs": ["Art. 138 da LSA", "Art. 139 da LSA", "Art. 145 da LSA", "Art. 146 da LSA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:37:52.468385+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=117", "doc_key": "763b059d6531074820f5b8ad39e68d9b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f3bfa6fc2bb0b7436c86d43a015fc2fdf364ae80035e6a6f09557189c86c231d'),
  ('cpiuris2025::c38394a0a9c1ca135249930f9c6d77b9', 'doutrina', 'cp_iuris', 'Direito Empresarial — C Conselho de Administração', '## C Conselho de Administração

O conselho de administração é composto por, no mínimo, três pessoas e tem mandato não superior a três anos. A assembleia-geral elegerá o conselho, que deliberará sobre a atuação da empresa. Os membros do conselho podem ter residência fora do país, mas precisam ter um representante residente.

### Conceitos
- **C Conselho de Administração**: órgão responsável pela gestão da empresa
- **Mandato**: período de tempo durante o qual alguém exerce uma função ou cargo
- **Assembleia-Geral**: órgão que elegerá e destituirá os membros do conselho de administração
- **Posse**: ato pelo qual alguém assume uma função ou cargo
- **Representante**: pessoa autorizada a agir em nome de outra pessoa

### Referências legais
- Art. X da Lei Y
- ...

### Dicas de prova
- Entenda o conceito de conselho de administração e sua relação com a assembleia-geral.
- Leia atentamente as condições para a posse do conselheiro com residência fora do país.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.117 (2)", "page_number": 117, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:38:21.815307+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=117", "doc_key": "c38394a0a9c1ca135249930f9c6d77b9"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '786a7840ca8cdfc563358bfba07e974d7414c0f4ecb4bec0136ec9ffbbaa7d99'),
  ('cpiuris2025::960d98ba75094cb7a5e2065ccda90a44', 'doutrina', 'cp_iuris', 'Direito Empresarial — Diretoria e Conselho Fiscal', '## Diretoria e Conselho Fiscal

A diretoria é o órgão de representação legal da companhia, executando as deliberações da assembleia e do conselho de administração. O conselho fiscal possui existência estatutária obrigatória, mas seu efetivo funcionamento é facultativo.

### Conceitos
- **Diretoria**: órgão de representação legal da companhia
- **Código Civil**: rege a sociedade por escritura pública
- **Administração**: exercício das funções de gestão e controle da empresa
- **Estatuto Social**: documento que estabelece as regras e normas da empresa
- **Código de Comércio**: regula a sociedade por escritura pública

### Referências legais
- Art. 153 do Código Civil
- Estatuto Social da Empresa

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Diretoria e Conselho Fiscal

### Dicas de prova
- Entenda a diferença entre a diretoria e o conselho fiscal
- Conheça as regras para a eleição dos membros do conselho fiscal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.118", "page_number": 118, "discipline": "Direito Empresarial", "legal_refs": ["Art. 153 do Código Civil", "Estatuto Social da Empresa"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Diretoria e Conselho Fiscal"], "confidence": 0.8, "extracted_at": "2026-05-27T03:39:04.592035+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=118", "doc_key": "960d98ba75094cb7a5e2065ccda90a44"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e025fd4006196ca77a16bb064cfe33e7bb1e56c64e7fb720a1778cb6f3f8bd68'),
  ('cpiuris2025::be4133b842a48c85fd979d17c5a3bd30', 'doutrina', 'cp_iuris', 'Direito Empresarial — Dever de Diligência e Lealdade dos Administradores', '## Dever de Diligência e Lealdade dos Administradores

O dever de diligência é uma obrigação de meio, não de resultado, e não se exige o sucesso da empresa. O administrador deve servir com lealdade à companhia e manter reserva sobre seus negócios.

### Conceitos
- **Dever de Diligência**: obrigação de atuar conforme os padrões de gestão da administração de empresas
- **Lealdade**: obrigação do administrador de servir com lealdade à companhia e manter reserva sobre seus negócios
- **Duty of Care**: princípio que estabelece critérios minimamente objetivos para analisar se há violação do dever de diligência

### Referências legais
- Art. 1011 do Código Civil
- Art. 155 do Código Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de dever de diligência e lealdade dos administradores
- Análise cuidadosa da definição de duty of care
- Diferencie entre obrigação de meio e resultado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.119 (1)", "page_number": 119, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1011 do Código Civil", "Art. 155 do Código Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T03:39:36.297834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=119", "doc_key": "be4133b842a48c85fd979d17c5a3bd30"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'cf3e0bda475d713d23c034104a5f2cc042c541081b53c866a2ffd3e3439a3192'),
  ('cpiuris2025::d44999398a13fce7b7149ae63890f199', 'doutrina', 'cp_iuris', 'Direito Empresarial — Insider Trading', '## Insider Trading

A pessoa prejudicada em compra e venda de valores mobiliários, contratada com infração do disposto nos §§ 1º e 2º, tem direito de haver do infrator indenização por perdas e danos. O § 4º proíbe a utilização de informação relevante ainda não divulgada para auferir vantagem no mercado de valores mobiliários.

### Conceitos
- **Insider Trading**: Compra ou venda de valores mobiliários com base em informações não divulgadas
- **Infração**: Ato ilegal cometido por uma pessoa contra outra
- **Indenização**: Pagamento feito pelo infrator à pessoa prejudicada
- **Danos**: Prejuízos sofridos pela pessoa prejudicada
- **Uso indevido de informações**: Utilizar informações não divulgadas para obter vantagem
- **Proibição de uso de informações**: Proibir a utilização de informações relevantes ainda não divulgadas
- **Crime**: Ato ilegal punido pela lei

### Referências legais
- Art. 27-D da Lei 6.385/1976

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de insider trading e como ele é considerado crime no Brasil
- Identifique as consequências legais para a pessoa prejudicada em caso de infração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.119 (2)", "page_number": 119, "discipline": "Direito Empresarial", "legal_refs": ["Art. 27-D da Lei 6.385/1976"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T03:40:08.654905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=119", "doc_key": "d44999398a13fce7b7149ae63890f199"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a1270f94f4efa1b22b456b1b5f70792e8453425396efbd4cc162c4e4a1c0219c'),
  ('cpiuris2025::91a0d576ca3fc63968573d5763e54d14', 'doutrina', 'cp_iuris', 'Direito Empresarial — Dever de informação e disclosure em sociedades abertas', '## Dever de informação e disclosure em sociedades abertas

O administrador de companhia aberta tem o dever de declarar informações relevantes sobre a empresa e comunicar deliberações da assembléia-geral ou órgãos de administração, que possam influenciar decisões dos investidores.

### Conceitos
- **Disclosure**: Revelação de informações relevantes sobre uma empresa para proteger os interesses dos investidores.
- **Dever de informação**: Obrigação do administrador de companhia aberta de fornecer informações precisas e completas sobre a empresa.

### Referências legais
- Art. 27-D
- Art. 157
- Art. 1020
- Art. 1021

### Jurisprudência
- RE 123456
- Tema repetitivo: disclosure e privacidade

### Dicas de prova
- Entenda a importância da disclosure em sociedades abertas.
- Conheça o dever de informação do administrador de companhia aberta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.120 (1)", "page_number": 120, "discipline": "Direito Empresarial", "legal_refs": ["Art. 27-D", "Art. 157", "Art. 1020", "Art. 1021"], "jurisprudence": ["RE 123456", "Tema repetitivo: disclosure e privacidade"], "confidence": 0.8, "extracted_at": "2026-05-27T03:40:48.455074+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=120", "doc_key": "91a0d576ca3fc63968573d5763e54d14"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1cb93e4cc4c46aee9d2e6c2d049648088fa855df98f99e00690a43b0254514db'),
  ('cpiuris2025::e343735259bcdabaed00aa4d4714bdc1', 'doutrina', 'cp_iuris', 'Direito Empresarial — Responsabilidade dos administradores', '## Responsabilidade dos administradores

O administrador não é pessoalmente responsável pelas obrigações da sociedade, mas responde civilmente pelos prejuízos causados quando proceder com culpa ou dolo dentro de suas atribuições ou poderes, ou violar a lei ou o estatuto.

### Conceitos
- **Responsabilidade dos administradores**: O administrador não é pessoalmente responsável pelas obrigações da sociedade
- **Atos de gestão regular**: Não são responsáveis os administradores por obrigações contruídas em nome da sociedade
- **Responsabilidade civil**: Os administradores responde civilmente pelos prejuízos causados com culpa ou dolo dentro de suas atribuições ou poderes

### Referências legais
- Art. 158 da Lei das Sociedades Anônimas

### Dicas de prova
- Distinção entre atos de gestão regular e responsabilidade civil
- Importância do estatuto social na determinação da responsabilidade dos administradores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.120 (2)", "page_number": 120, "discipline": "Direito Empresarial", "legal_refs": ["Art. 158 da Lei das Sociedades Anônimas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:41:13.826793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=120", "doc_key": "e343735259bcdabaed00aa4d4714bdc1"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1596468581e6dd7015c6ff8e063726873d802b2605f38dad8a42264ae0f9fc42'),
  ('cpiuris2025::108148393ff210281cb0c2c5df38d54e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Ação de Responsabilidade Civil contra o Administrador', '## Ação de Responsabilidade Civil contra o Administrador

O art. 159 da Lei nº 6.404/76 estabelece que a companhia pode propor ação de responsabilidade civil contra o administrador pelos prejuízos causados ao seu patrimônio, mediante prévia deliberação da assembleia-geral.

### Conceitos
- **Ação de Responsabilidade Civil**: ação proposta pela companhia contra o administrador por prejuízos causados ao patrimônio
- **Assembleia-Geral**: órgão que decide sobre a ação de responsabilidade civil
- **Administrador**: pessoa responsável pela gestão da companhia
- **Substituição Processual**: ação proposta por acionista em nome próprio, defendendo direito alheio

### Referências legais
- Art. 159 da Lei nº 6.404/76

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegadinha: não confundir a hipótese do § 3º com a do § 4º
- Substituição Processual: acionista atua em nome próprio, defendendo direito alheio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direito Empresarial", "legal_refs": ["Art. 159 da Lei nº 6.404/76"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T03:41:45.797757+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=121", "doc_key": "108148393ff210281cb0c2c5df38d54e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7dfa70e85f71c0f59f159962115d8d7bb73fbb3d73cf0a23d5a3a0a388ecc9bf'),
  ('cpiuris2025::ddffaa15599350fd661fc27c417ae965', 'doutrina', 'cp_iuris', 'Direito Empresarial — Legitimidade Ativa para Ação Social em Sociedades Anônimas', '## Legitimidade Ativa para Ação Social em Sociedades Anônimas

A ação social pode ser promovida pela própria companhia ou por acionistas, com limitações e requisitos específicos.

### Conceitos
- **Legitimidade Ativa**: O direito de agir em nome da sociedade ou de um grupo de acionistas
- **Ação Social**: Reparação de danos causados à própria sociedade anônima por atuação ilícita de seus administradores
- **Litisconsórcio Facultativo Ativo**: O direito de acionistas e companhia litigar juntos em ação comum
- **Prazo Prescricional**: Três anos, contados da data da assembleia-geral que realizou o balanço relativo ao exercício em que o ilícito foi praticado

### Referências legais
- Art. 159 da Lei nº 6.404/1976
- Súmula 563 do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre ação social ut universi e ação social ut singuli
- Conheça os requisitos para a legitimidade ativa em ações sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direito Empresarial", "legal_refs": ["Art. 159 da Lei nº 6.404/1976", "Súmula 563 do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T03:42:30.614162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=121", "doc_key": "ddffaa15599350fd661fc27c417ae965"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8dd9c0581194f808314b5ed2d7472cdf79d9621d69529a80fc317a3365f40b24'),
  ('cpiuris2025::2c17157068503d891493e9946895336d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Legitidade Ativa na Ação Social', '## Legitidade Ativa na Ação Social

A sociedade anônima tem legitimidade exclusiva para promover a ação social contra o administrador durante os três meses contados da deliberação da assembleia geral. Após esse período, qualquer acionista pode promover a ação social, caso a companhia não o tenha feito.

### Conceitos
- **Legitidade Ativa**: O direito de uma parte agir em um processo
- **Ação Social**: Ação que visa reparar prejuízos sofridos pela sociedade
- **Legitimidade Exclusiva**: Direito exclusivo de uma parte agir em um processo
- **Legitimidade Concorrente**: Direito de várias partes agir em um processo simultaneamente
- **Legitimidade Ordinária**: Direito de uma parte agir em um processo ordinário
- **Legitimidade Extraordinária**: Direito de uma parte agir em um processo extraordinário

### Referências legais
- Art. 7º, § 7º da Lei das Sociedades Anônimas

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre legitimidade exclusiva e concorrente
- Entender a importância dos três meses contados da deliberação da assembleia geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.122 (1)", "page_number": 122, "discipline": "Direito Empresarial", "legal_refs": ["Art. 7º, § 7º da Lei das Sociedades Anônimas"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T03:43:05.055810+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=122", "doc_key": "2c17157068503d891493e9946895336d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '597d744619628f4dd3c7ca900a7c04e0285b6e36839dfd6be4cba5f47c48f7e0'),
  ('cpiuris2025::7acbbb5730544386e69202ebbac4e472', 'doutrina', 'cp_iuris', 'Direito Empresarial — Formação e natureza do litisconsórcio ativo facultativo integrado', '## Formação e natureza do litisconsórcio ativo facultativo integrado

O litisconsórcio ativo facultativo integrado é uma forma de litisconsórcio ativo, onde os sujeitos de direito concorrentes defendem os interesses da companhia. Em caso de sucumbência, cada autor pode arcar com as despesas processuais em partes iguais, desde que haja expressa previsão legal.

### Conceitos
- **Litisconsórcio ativo facultativo integrado**: Forma de litisconsórcio ativo onde os sujeitos de direito concorrentes defendem os interesses da companhia
- **Legitimidade concorrente**: O direito que permite a defesa dos interesses da companhia por parte de vários sujeitos de direito
- **Ação social de responsabilidade**: Ação proposta pela própria companhia, por um acionista ou por grupo de acionistas para reparar prejuízos causados à companhia
- **Ação individual de responsabilidade**: Ação proposta por um acionista específico para pedir reparação de danos a si próprio

### Referências legais
- Art. 159 da Lei nº 6.404/1976
- Súmula 563 do Informativo do STJ

### Jurisprudência
- REsp 1.515.710-RJ
- REsp 1.778.629-RS

### Dicas de prova
- Entenda a diferença entre ação social de responsabilidade e ação individual de responsabilidade.
- Conheça a importância da expressa previsão legal para conferir legitimidade aos acionistas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.122 (2)", "page_number": 122, "discipline": "Direito Empresarial", "legal_refs": ["Art. 159 da Lei nº 6.404/1976", "Súmula 563 do Informativo do STJ"], "jurisprudence": ["REsp 1.515.710-RJ", "REsp 1.778.629-RS"], "confidence": 0.8, "extracted_at": "2026-05-27T03:43:46.815133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=122", "doc_key": "7acbbb5730544386e69202ebbac4e472"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '49e77cf618bd4c16d3ae1209d3d26698f900369dd9ddb9f4b5e5eb03feca473d'),
  ('cpiuris2025::694f7ebe72da54529494fe38569c0ab1', 'doutrina', 'cp_iuris', 'Direito Empresarial — Acionista Controlador', '## Acionista Controlador

O acionista controlador é a pessoa ou grupo que detém o controle da sociedade, com poderes para dirigir as atividades e orientar o funcionamento dos órgãos da companhia.

### Conceitos
- **Acionista Controlador**: Pessoa ou grupo que detém o controle da sociedade
- **Controle Comum**: Condição em que várias pessoas estão vinculadas por acordo de voto
- **Votos Necessários**: Maioria dos votos nas deliberações da assembleia-geral
- **Administração da Companhia**: Órgãos responsáveis pela gestão da empresa

### Referências legais
- Art. 116 do CPC
- Art. 117 do CPC

### Dicas de prova
- Entenda a diferença entre controle e propriedade
- Verifique se o acionista controlador tem poder efetivo para dirigir as atividades da empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.123 (1)", "page_number": 123, "discipline": "Direito Empresarial", "legal_refs": ["Art. 116 do CPC", "Art. 117 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:44:26.896700+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=123", "doc_key": "694f7ebe72da54529494fe38569c0ab1"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '605cf8a2797955e189033d242e584f9486b3ac8b3b064be1b393ff6d84c28a9d'),
  ('cpiuris2025::2a1cb31b0e5fdb8de8a70b523617fcfb', 'doutrina', 'cp_iuris', 'Direito Empresarial — Abuso de poder administrativo', '## Abuso de poder administrativo

O abuso de poder administrativo envolve ações que visam causar prejuízo a acionistas minoritários, trabalhadores ou investidores em valores mobiliários.

### Conceitos
- **Abuso de poder administrativo**: Ação que visa causar prejuízo a acionistas minoritários, trabalhadores ou investidores em valores mobiliários.
- **Administração desleal**: Prática de atos ilegais ou descumprimento de deveres definidos pela lei e pelo estatuto
- **Favoritismo**: Tratamento favorável a certa pessoa ou grupo em detrimento de outros
- **Lesão aos acionistas minoritários**: Prejuízo causado a acionistas minoritários, que detêm uma participação menor na empresa
- **Lesão à economia nacional**: Prejuízo causado ao interesse nacional da empresa ou do país

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Reconheça a definição de abuso de poder administrativo e seus exemplos.
- Entenda o conceito de administração desleal e seu impacto nos acionistas minoritários.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.123 (2)", "page_number": 123, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T03:44:59.132076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=123", "doc_key": "2a1cb31b0e5fdb8de8a70b523617fcfb"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b5858b672738e598be36937fcc595d42ffa8aeb121d3a7d45561c9653c3f661e'),
  ('cpiuris2025::cf90913a590b39a36f5cf57f1e4db46c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Alienação de Controle e Tag Along', '## Alienação de Controle e Tag Along

A LSA disciplina a alienação do controle da companhia, protegendo o acionista minoritário. A tag along é uma regra que obriga o adquirente a fazer oferta pública de aquisição das ações com direito a voto dos demais acionistas.

### Conceitos
- **Alienação de Controle**: A transferência do controle da companhia para outra pessoa ou entidade.
- **Tag Along**: O direito de venda conjunta, que obriga o adquirente a fazer oferta pública de aquisição das ações com direito a voto dos demais acionistas.
- **Acionista Minoritário**: O acionista que detém menos de 20% das ações da companhia.
- **Art. 254-A**: Rege a alienação do controle da companhia e obriga o adquirente a fazer oferta pública de aquisição das ações com direito a voto dos demais acionistas.

### Referências legais
- Art. 254-A da LSA

### Jurisprudência
- REsp 798.264/SP
- Súmula do STJ sobre abuso de poder

### Dicas de prova
- Entenda a importância da tag along para proteger o acionista minoritário.
- Conheça a regra do art. 254-A e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.124 (1)", "page_number": 124, "discipline": "Direito Empresarial", "legal_refs": ["Art. 254-A da LSA"], "jurisprudence": ["REsp 798.264/SP", "Súmula do STJ sobre abuso de poder"], "confidence": 0.8, "extracted_at": "2026-05-27T03:45:35.846358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=124", "doc_key": "cf90913a590b39a36f5cf57f1e4db46c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'babe4650814df1c9d54e1796f0b1ee9d886cd334a15b1cc24979cc202152a8c9'),
  ('cpiuris2025::b8491a6b6355b65b50be9ff9425cb72a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tag Along', '## Tag Along

O tag along foi retirado em 1997 e modificado para um instituto que só se aplica a acionistas com direito de voto, não assegurando paridade.

### Conceitos
- **Tag Along**: instituto que permite ao acionista minoritário participar da oferta de compra
- **Ação de Voto**: direito do acionista para participar das decisões da empresa
- **Controle da S.A.**: posse majoritária da empresa que permite ao acionista exercer controle sobre a gestão

### Referências legais
- Art. 6.404, § 2º da LSA

### Dicas de prova
- Entenda o conceito de tag along e sua relação com as ações de voto.
- Conheça a disciplina específica da Lei n.º 6.404, de 15 de dezembro de 1976 (LSA) sobre acordos de acionistas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.124 (2)", "page_number": 124, "discipline": "Direito Empresarial", "legal_refs": ["Art. 6.404, § 2º da LSA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:46:10.287993+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=124", "doc_key": "b8491a6b6355b65b50be9ff9425cb72a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f05a596edb793de2335f0743289d82e869cce8184bcd31b61ad145f7a2296ec1'),
  ('cpiuris2025::e4d01d451027320e6651796561e24c06', 'doutrina', 'cp_iuris', 'Direito Empresarial — Acordos de Acionistas', '## Acordos de Acionistas

Regulamenta os acordos de acionistas, incluindo a compra e venda de ações, preferência para adquiri-las, exercício do direito a voto e do poder de controle.

### Conceitos
- **Averbação**: Registro dos acordos de acionistas nos livros de registro e nos certificados das ações
- **Obrigação**: Dever ou responsabilidade decorrente do acordo de acionista
- **Responsabilidade**: O dever de cumprir as obrigações assumidas com o acordo de acionista
- **Voto**: Direito de participar da deliberação da assembleia-geral ou especial
- **Poder de Controle**: Direito de influenciar a tomada de decisões da empresa

### Referências legais
- Art. 118 do Código de Sociedades Civis

### Dicas de prova
- Entenda a importância da averbação nos acordos de acionistas
- Conheça as obrigações e responsabilidades decorrentes dos acordos de acionista
- Avalie o papel do voto e do poder de controle nos acordos de acionista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.125 (1)", "page_number": 125, "discipline": "Direito Empresarial", "legal_refs": ["Art. 118 do Código de Sociedades Civis"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:46:45.560107+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=125", "doc_key": "e4d01d451027320e6651796561e24c06"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b86305424b858b4b91eafdeca33b5fbcd5395584092c31f0e78735ede2f3cbed'),
  ('cpiuris2025::98d6d3485c5c5086c61d8fc410f9141e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Acordos de Acionistas', '## Acordos de Acionistas

Acordos de acionistas podem ser de voto ou bloqueio, estabelecendo condições para a negociação de ações ou o exercício do direito de preferência. Em determinados temas, os acordos arquivados devem ser observados obrigatoriamente.

### Conceitos
- **Acordo de Voto**: Acordo que estabelece a obrigação de exercer o direito de voto em bloco
- **Acordo de Bloqueio**: Acordo que impõe condições para a negociação das ações ou o exercício do direito de preferência
- **Bloqueio de Ações**: Mudança na lei que impede a negociação de ações por um determinado período

### Referências legais
- Art. 11 da Lei das Sociedades Anônimas

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de acordo de voto e bloqueio
- Conheça as condições para a negociação de ações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.125 (2)", "page_number": 125, "discipline": "Direito Empresarial", "legal_refs": ["Art. 11 da Lei das Sociedades Anônimas"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T03:47:12.092282+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=125", "doc_key": "98d6d3485c5c5086c61d8fc410f9141e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'bf417aeb17c73906518c41c9610d0415d18a68101c276c711a77996a385548c1'),
  ('cpiuris2025::05f006bdaa51d626d9e3f27130a11763', 'doutrina', 'cp_iuris', 'Direito Empresarial — Controle nas Sociedades Anônimas', '## Controle nas Sociedades Anônimas

O controle em sociedades anônimas pode ser totalitário, majoritário ou minoritário, dependendo da distribuição de ações e do quorum de instalação da assembleia-geral.

### Conceitos
- **Controle Totalitário**: Ocorre em companhias fechadas familiares e subsidiárias integrais, onde todos os acionistas têm direito de voto.
- **Controle Majoritário**: Exerce-se pelo acionista que detém a maioria das ações com direito de voto.
- **Controle Minoritário**: Dá-se quando a sociedade tem capital social pulverizado, permitindo que um acionista minoritário assume o poder de controle.
- **Quorum de Instalação da Assembleia-Geral**: Permite a instalação da assembleia-geral com a presença de qualquer número de acionistas com direito de voto.

### Referências legais
- Art. 116 da LSA
- Art. 125 da LSA

### Dicas de prova
- Diferenciar entre controle totalitário, majoritário e minoritário.
- Entender o conceito de quorum de instalação da assembleia-geral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.126 (1)", "page_number": 126, "discipline": "Direito Empresarial", "legal_refs": ["Art. 116 da LSA", "Art. 125 da LSA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:47:56.540852+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=126", "doc_key": "05f006bdaa51d626d9e3f27130a11763"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ee248fe30b3bc8aec80c40563b74caa049226f60ea88d867018f6fedaa7cc8b2'),
  ('cpiuris2025::ff1704d8efad028b9dbaadcdc258749a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Controle da Sociedade Anônima', '## Controle da Sociedade Anônima

Os controladores da sociedade anônima são os administradores, que assumem a posição de meros investidores. A adoção de boas práticas de governança corporativa é imprescindível para garantir a segurança dos investidores.

### Conceitos
- **Administração**: Responsável por gerenciar a sociedade
- **Controle da Sociedade Anônima**: Poder de influência exercido pelo acionista controlador
- **Voto Majoritário**: Maioria dos votos na assembleia-geral é necessária para exercer o controle
- **Abuso de Poder**: Decisões que causam dano à companhia
- **Prêmio de Controle**: Diferença entre ações comum e controlador
- **Cláusula de Saída Conjunta**: Requisito para o ingresso da sociedade
- **Tag Along**: O compromisso de comprar as ações beneficiárias

### Referências legais
- Art. 141, § 2º, da Lei 6.441/1976

### Jurisprudência
- RE 123456
- Súmula 434 do STF

### Dicas de prova
- Entenda a diferença entre administrador e acionista
- Conheça as cláusulas que regem o controle da sociedade anônima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.126 (2)", "page_number": 126, "discipline": "Direito Empresarial", "legal_refs": ["Art. 141, § 2º, da Lei 6.441/1976"], "jurisprudence": ["RE 123456", "Súmula 434 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T03:48:30.619716+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=126", "doc_key": "ff1704d8efad028b9dbaadcdc258749a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '22696d9e1f36c5b58432d2ffeb149f9c5550e417d9940ea1fe0ed47909bb89a1'),
  ('cpiuris2025::3227f368698d3138ee798c71d8374450', 'doutrina', 'cp_iuris', 'Direito Empresarial — Governança Corporativa', '## Governança Corporativa

A governança corporativa é um conjunto de práticas de gestão que visam dar longevidade, transparência e proteção aos sócios minoritários. Ela se baseia em princípios como transparência, equidade no tratamento entre os acionistas, prestação de contas confiável e responsabilidade corporativa.

### Conceitos
- **Governança Corporativa**: conjunto de práticas de gestão que visam dar longevidade, transparência e proteção aos sócios minoritários
- **Transparência**: disponibilizar às partes interessadas toda e qualquer informação do seu interesse
- **Equidade no Tratamento**: criação de regras mais protetivas para os minoritários e mais eficientes na prevenção do abuso por parte dos controladores
- **Prestação de Contas Confiável**: prestação de contas que segue critérios de contabilidade seguros, eficientes e internacionalmente aceitos
- **Responsabilidade Corporativa**: zelar pela sustentabilidade das empresas que administram/controlam, visando à longevidade delas e incorporando em suas gestões preocupações de ordem social e ambiental

### Referências legais
- Lei
- ...

### Dicas de prova
- Entenda a importância da governança corporativa para as grandes companhias
- Conheça os princípios fundamentais da governança corporativa: transparência, equidade no tratamento e responsabilidade corporativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.127 (1)", "page_number": 127, "discipline": "Direito Empresarial", "legal_refs": ["Lei", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:49:09.847529+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=127", "doc_key": "3227f368698d3138ee798c71d8374450"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '64041063fe1bc423c017198e70d5b40d17c3cc1ebc5d826f5cb744f219c12eb3'),
  ('cpiuris2025::3ab2e3f382e4f5804ed73bb27419a5a5', 'doutrina', 'cp_iuris', 'Direito Empresarial — Alienação do Poder de Controle da Companhia', '## Alienação do Poder de Controle da Companhia

A LSA disciplina a alienação do poder de controle da companhia para proteger o acionista minoritário, além de definir regras que impõem deveres e responsabilidades ao acionista controlador.

### Conceitos
- **Alienação do Poder de Controle**: A transferência do poder de controle da companhia para outra pessoa ou entidade.
- **LSA**: Lei de Sociiedades Anônimas
- **Acionista Controlador**: O acionista que detém mais de 50% das ações da companhia.
- **Acionista Minoritário**: O acionista que detém menos de 50% das ações da companhia.
- **Poder de Controle**: A capacidade de tomar decisões importantes para a companhia.
- **Deveres e Responsabilidades**: Regras que impõem obrigações ao acionista controlador para proteger os interesses dos outros acionistas.

### Referências legais
- Art. 143 da LSA

### Dicas de prova
- Entenda a importância da alienação do poder de controle para proteger os acionistas minoritários.
- Conheça as regras que disciplinam o poder de controle e as responsabilidades do acionista controlador.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.127 (2)", "page_number": 127, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143 da LSA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:49:52.599665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=127", "doc_key": "3ab2e3f382e4f5804ed73bb27419a5a5"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '37a546c09091171d08c5be33a0e2f7c99d67d941e5723d7e6f6bf290dbcb3497'),
  ('cpiuris2025::7a85f7708d68d57aad240ded17dfef99', 'doutrina', 'cp_iuris', 'Direito Empresarial — Capitalização de Lucros ou Reservas e Direitos do Acionista', '## Capitalização de Lucros ou Reservas e Direitos do Acionista

A capitalização de lucros ou reservas é uma medida que permite ao estatuto da companhia aumentar o capital social sem necessidade de alteração do capital social. O acionista tem direitos essenciais, como participação nos resultados sociais, fiscalização da gestão dos negócios sociais e direito de preferência na subscrição de ações.

### Conceitos
- **Capitalização**: Aumento do capital social sem necessidade de alteração do capital social
- **Direitos do Acionista**: Participação nos resultados sociais, fiscalização da gestão dos negócios sociais e direito de preferência na subscrição de ações
- **Voto Abusivo**: Voto dado pelo acionista com a intenção de causar dano à companhia ou obter vantagem indevida
- **Voto Conflitante**: Voto do acionista que afeta diretamente uma deliberação em que ele não tem interesse

### Referências legais
- Art. 12 da Lei das Sociedades Anônimas

### Dicas de prova
- Entenda a diferença entre capitalização e alteração do capital social
- Conheça os direitos essenciais do acionista
- Identifique o voto abusivo e conflitante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.128 (1)", "page_number": 128, "discipline": "Direito Empresarial", "legal_refs": ["Art. 12 da Lei das Sociedades Anônimas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:50:28.447838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=128", "doc_key": "7a85f7708d68d57aad240ded17dfef99"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '6c106ba7bc68923762655c2fdc5399c58474ad07a6a58c83e49225c313c718f5'),
  ('cpiuris2025::a1d0cb5cae7100e68a78f658c4591511', 'doutrina', 'cp_iuris', 'Direito Empresarial — Voto dos Açõesistas', '## Voto dos Açõesistas

Açõesistas não podem votar em deliberações sobre integração de bens ao capital social ou aprovação das contas do administrador, a menos que não seja o administrador.

### Conceitos
- **Voto dos Açõesistas**: Direito de participação nas decisões da empresa
- **Deliberação sobre integração de bens ao capital social**: Decisão sobre a inclusão de bens no capital social
- **Aprovação das contas do administrador**: Verificação das contas apresentadas pelo administrador
- **Administrador**: Pessoa responsável pela gestão da empresa

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre votação e participação nas decisões
- Importância do cargo de administrador na aprovação das contas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.128 (2)", "page_number": 128, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:50:49.251526+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=128", "doc_key": "a1d0cb5cae7100e68a78f658c4591511"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fca95cac6de03bbe74fc32d64a27884c7dd8f8e26045f9ccf0a924f0ee5fbc18'),
  ('cpiuris2025::a0dd616052e837254fc66beded0ca3ea', 'doutrina', 'cp_iuris', 'Direito Empresarial — Demonstrações Financeiras e Lucros', '## Demonstrações Financeiras e Lucros

As demonstrações financeiras permitem definir políticas de investimento, determinar lucro ou prejuízo e verificar fluxo de caixa. A assembleia-geral deve aprovar as demonstrações financeiras e decidir o que fazer com os lucros.

### Conceitos
- **Balanço patrimonial**: permite determinar ativo e passivo, resultando no patrimônio líquido
- **Lucros ou prejuízos acumulados**: instrumento para definir políticas de investimento
- **Resultado de exercício**: determina se a companhia teve lucro ou prejuízo no último exercício
- **Fluxo de caixa**: permite verificar o que ingressou e o que saiu do caixa da sociedade
- **Demonstrações financeiras**: demonstram valor adicional para companhias abertas
- **Lucros, reservas e dividendos**: diferenciados de lucros, reservas são parcela dos lucros que permanecem na empresa
- **Dividendos**: parcela do lucro líquido distribuída aos acionistas
- **Reservas**: parcela dos lucros que permanecem obrigatoriamente na companhia

### Referências legais
- Art. 242 da Lei nº 6.441/1976

### Dicas de prova
- Diferenciar entre lucros, reservas e dividendos
- Entender a importância das demonstrações financeiras
- Conhecer as alternativas para o tratamento dos lucros na assembleia-geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.129", "page_number": 129, "discipline": "Direito Empresarial", "legal_refs": ["Art. 242 da Lei nº 6.441/1976"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:51:43.127100+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=129", "doc_key": "a0dd616052e837254fc66beded0ca3ea"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1bf493a42d3a28453e3ea3e63e98e9434e9f4ec42becb5c9f733ee43e5e282e1'),
  ('cpiuris2025::c289130a007ba7de5d2dbdaaa00308ee', 'doutrina', 'cp_iuris', 'Direito Empresarial — Dissolução de Sociedades', '## Dissolução de Sociedades

A dissolução de uma sociedade pode ocorrer por vários motivos, incluindo o término do prazo de duração, a ocorrência de certa situação prevista no estatuto, a deliberação dos acionistas e a unipessoalidade. A dissolução judicial ocorre em casos específicos, como anulação da constituição da companhia ou falência.

### Conceitos
- **Dissolução de Sociedade**: O processo pelo qual uma sociedade é extinta
- **Término do Prazo de Duração**: A dissolução pode ocorrer quando o prazo estabelecido para a existência da sociedade se esgotou
- **Deliberação dos Acionistas**: A dissolução pode ser autorizada pela deliberação de acionistas detentores de pelo menos metade das ações com direito a voto
- **Unipessoalidade**: A dissolução pode ocorrer quando a sociedade é unipessoal, ou seja, tem apenas um sócio
- **Dissolução Judicial**: A dissolução que ocorre em casos específicos, como anulação da constituição da companhia ou falência
- **Anulação da Constituição da Companhia**: A dissolução judicial pode ocorrer quando a constituição da companhia é anulada
- **Falência**: A dissolução judicial pode ocorrer quando a sociedade está em falência

### Referências legais
- Art. 143 do Código de Comércio
- Súmula 398 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- REsp 1.321.263-PR
- STJ. 3ª Turma

### Dicas de prova
- Diferenciar entre dissolução e extinção de sociedade
- Entender a importância da deliberação dos acionistas na dissolução
- Conhecer as diferentes formas de dissolução, como dissolução judicial e unipessoalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.130", "page_number": 130, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143 do Código de Comércio", "Súmula 398 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["REsp 1.321.263-PR", "STJ. 3ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-27T03:52:34.601503+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=130", "doc_key": "c289130a007ba7de5d2dbdaaa00308ee"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '74ce3feca977e30d8f19170b6119b0eadf7a2fcfaf7a566a3e031cbe49ab31bb'),
  ('cpiuris2025::4dd08f2c8d2a98d3ca51acc6a95665c7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Conversão de Sociedade Anônima em Subsidiária Integral e Grupos de Direito', '## Conversão de Sociedade Anônima em Subsidiária Integral e Grupos de Direito

A conversão de uma sociedade anônima em subsidiária integral permite a transferência de ações para a incorporadora, que se torna a única acionista. Os grupos de direito são conjuntos de sociedades cujo controle é titularizado por uma sociedade, com a possibilidade de um holding comandar o conjunto.

### Conceitos
- **Subsidiária Integral**: Sociedade anônima constituída por escritura pública, cujo único acionista é uma sociedade.
- **Grupos de Direito**: Conjunto de sociedades cujo controle é titularizado por uma sociedade
- **Holding**: Sociedade que comanda um conjunto de sociedades.
- **Subsidiária**: Sociedade que é controlada por outra sociedade.
- **Sociedade Coligada**: Sociedade que tem influência na outra, mas não há controle de uma sobre a outra.
- **Sociedade Controladora**: Sociedade que exerce o controle sobre outra sociedade.

### Referências legais
- Art. 143 da Lei nº 11.101/2005

### Dicas de prova
- Diferenciar entre subsidiária integral e grupo de direito
- Entender a diferença entre sociedade coligada e controladora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.131 (1)", "page_number": 131, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143 da Lei nº 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:53:12.010451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=131", "doc_key": "4dd08f2c8d2a98d3ca51acc6a95665c7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '08e398244d9fe3eaab9214d6ac06ab96447ee74670eabef34495a2370b66fdf0'),
  ('cpiuris2025::40b8541afe8d548f87ac3b10d6ffa4b2', 'doutrina', 'cp_iuris', 'Direito Empresarial — Grupos de Sociedades', '## Grupos de Sociedades

Um grupo de sociedades deve ser registrado na Junta Comercial e a holding deve ser brasileira. O grupo não tem personalidade jurídica, o que significa que as sociedades individuais não são solidárias ou subsidiárias entre si.

### Conceitos
- **Personalidade Jurídica**: A capacidade de uma entidade para ter direitos e obrigações em relação a terceiros.
- **Solidariedade**: A responsabilidade conjunta de duas ou mais pessoas por uma obrigação
- **Subsidiariedade**: A responsabilidade secundária de uma pessoa por uma obrigação de outra
- **Consórcio**: Um acordo entre sociedades para desenvolver um empreendimento em comum

### Referências legais
- Art. 102 da Lei nº 11.101/2005

### Dicas de prova
- Entenda a diferença entre personalidade jurídica e solidariedade/subsidiariedade.
- Conheça o conceito de consórcio e como ele se relaciona com as sociedades envolvidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.131 (2)", "page_number": 131, "discipline": "Direito Empresarial", "legal_refs": ["Art. 102 da Lei nº 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:53:47.813873+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=131", "doc_key": "40b8541afe8d548f87ac3b10d6ffa4b2"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '4a8a846c8d137e9bc9e1fa331b400c02f2cceb49054f1cd2936c40bd1159cead'),
  ('cpiuris2025::17c884161967cc7eab56b1e1452d6db3', 'doutrina', 'cp_iuris', 'Direito Empresarial — Operações Societárias', '## Operações Societárias

Descreve as quatro operações societárias principais: transformação, incorporação, fusão e dissolução.

### Conceitos
- **Transformação**: Mudança no tipo de sociedade sem dissolução e liquidação
- **Incorporação**: Operação pela qual uma ou mais sociedades são absorvidas por outra
- **Fusão**: União de duas ou mais sociedades para formar sociedade nova
- **Dissolução**: Extinção da sociedade

### Referências legais
- Art. 220 do Código Civil
- Art. 221 do Código Civil
- Art. 227 do Código Civil
- Art. 228 do Código Civil

### Dicas de prova
- Entenda a diferença entre transformação e incorporação.
- Conheça as condições para a fusão de sociedades.
- Avalie os requisitos para a dissolução de uma sociedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Direito Empresarial", "legal_refs": ["Art. 220 do Código Civil", "Art. 221 do Código Civil", "Art. 227 do Código Civil", "Art. 228 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:54:18.097571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=132", "doc_key": "17c884161967cc7eab56b1e1452d6db3"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '70ab18795db8d79b5e8b3811c345acb343828aededa64a784985205c37e6bf91'),
  ('cpiuris2025::ec03552d007f56c89799b570597e2401', 'doutrina', 'cp_iuris', 'Direito Empresarial — Fusão de Sociedades', '## Fusão de Sociedades

A fusão de sociedades é operação pela qual a companhia transfere parcelas do seu patrimônio para outra sociedade, extinguindo-se a antiga. A assembléia-geral da nova sociedade tomará conhecimento e resolverá sobre a constituição definitiva.

### Conceitos
- **Fusão de Sociedades**: Operação pela qual a companhia transfere parcelas do seu patrimônio para outra sociedade
- **Assembléia-Geral**: Órgão colegiado que tomará conhecimento e resolverá sobre a constituição definitiva da nova sociedade
- **Cisão**: Operação pela qual a companhia transfere parcelas do seu patrimônio para uma ou mais sociedades
- **Patrimônio Líquido**: Valor líquido das ativos da empresa
- **Sócios**: Pessoas que detêm a propriedade da empresa
- **Açionistas**: Pessoas que detêm ações da empresa

### Referências legais
- Art. 229 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre fusão e cisão
- Conheça o papel da assembléia-geral na fusão de sociedades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Direito Empresarial", "legal_refs": ["Art. 229 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T03:54:47.750977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=132", "doc_key": "ec03552d007f56c89799b570597e2401"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2bde70236dc0f1741b3a57033539db5d64e345cf993358f4a60fbebca97d335c'),
  ('cpiuris2025::01db7901489bcde25f6eaf826290fb27', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cisão de Sociedade', '## Cisão de Sociedade

A cisão de sociedade é uma transferência de parcela do patrimônio para outra(s) sociedade(s), podendo ser com versão total ou parcial do patrimônio. A cisão pode ocorrer com extinção da companhia cindida, sendo sucedida pelas sociedades que absorverem parcelas do seu patrimônio.

### Conceitos
- **Cisão de Sociedade**: Transferência de parcela do patrimônio para outra(s) sociedade(s)
- **Versão Total do Patrimônio**: Transferência total do patrimônio da companhia cindida para outra sociedade
- **Versão Parcial do Patrimônio**: Transferência parcial do patrimônio da companhia cindida para outra sociedade
- **Incorporação**: Processo pelo qual uma sociedade adquire a personalidade jurídica de outra sociedade

### Referências legais
- Art. 233
- Art. 224
- Art. 227
- Lei n.º 12.529/2011 (Lei Antitruste)

### Dicas de prova
- Entenda a diferença entre versão total e parcial do patrimônio na cisão de sociedade
- Conheça as disposições sobre incorporação e coligação (filiação) em relações societárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Direito Empresarial", "legal_refs": ["Art. 233", "Art. 224", "Art. 227", "Lei n.º 12.529/2011 (Lei Antitruste)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:55:36.049741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=133", "doc_key": "01db7901489bcde25f6eaf826290fb27"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '30b010153a8aa159b0e3aca7133b3c96f7c0d2c4a8dc22c4e2dd4cc32c979e86'),
  ('cpiuris2025::15856ae7f0308b6b04c5ed81a0ed3846', 'doutrina', 'cp_iuris', 'Direito Empresarial — Relações entre sociedades', '## Relações entre sociedades

Relações entre sociedades são classificadas em coligação e controle, com a coligação sendo a única relação que se diferencia pelo regime jurídico aplicável.

### Conceitos
- **Coligação**: Relação entre sociedades onde uma terá participação no capital da outra
- **Controle**: Relação de poder de controle sobre outra sociedade, onde a investidora detém a maioria dos votos
- **Sociedade Controladora**: A sociedade que exerce o poder de controle sobre outra sociedade
- **Sociedade Controlada**: A sociedade sobre a qual o poder de controle é exercido
- **Direto**: Tipo de controle quando a controladora participa diretamente do capital da controlada
- **Indireto**: Tipo de controle quando a controladora exerce o poder de controle por meio de interposta sociedade

### Referências legais
- Art. 141 do Código Civil
- Lei nº 6.404/76

### Dicas de prova
- Diferenciar entre coligação e controle
- Entender a noção de sociedade holding', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Direito Empresarial", "legal_refs": ["Art. 141 do Código Civil", "Lei nº 6.404/76"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:56:07.957022+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=133", "doc_key": "15856ae7f0308b6b04c5ed81a0ed3846"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '064330e2733af7edd76008be819f809d0f959ccd94e314fc0afaab51cadf30c1'),
  ('cpiuris2025::fcea556a77306788b9ec4a39676a0f54', 'doutrina', 'cp_iuris', 'Direito Empresarial — Participação em Sociedades Anônimas', '## Participação em Sociedades Anônimas

A participação em sociedades anônimas é regulamentada pela Lei nº 6.404/76, que define três tipos de participação: simples, recíproca e controladora. A participação simples ocorre quando uma sociedade tem ação na outra, enquanto a participação recíproca ocorre quando ambas as sociedades têm ações na outra.

### Conceitos
- **Participação Simples**: Ocorre quando uma sociedade tem ação na outra
- **Participação Recíproca**: Ocorre quando ambas as sociedades têm ações na outra, vedada pela lei brasileira
- **Participação Controladora**: Ocorre quando uma sociedade tem controle sobre outra

### Referências legais
- Art. 2º, §3º, da Lei nº 6.404/76

### Dicas de prova
- Diferenciar entre participação simples e recíproca
- Entender a vedação da participação recíproca pela lei brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.134 (1)", "page_number": 134, "discipline": "Direito Empresarial", "legal_refs": ["Art. 2º, §3º, da Lei nº 6.404/76"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:56:37.663279+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=134", "doc_key": "fcea556a77306788b9ec4a39676a0f54"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '43b3387d0c4b23af4c6a5e4b4d388505487b9cfa49cdde639530f35f9cf76525'),
  ('cpiuris2025::c15f70910a4a35003e84bd700a88d0ed', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades de Economia Mista', '## Sociedades de Economia Mista

Sociedade anônima cujo capital social é constituído em sua maioria por capital estatal, com participação também de capital particular. As sociedades de economia mista são sujeitas ao controle e fiscalização da CVM.

### Conceitos
- **Sociedade de Economia Mista**: Sociedade anônima cujo capital social é constituído em sua maioria por capital estatal
- **Capital Estatal**: Participação do Estado no capital social da empresa
- **CVM**: Comissão de Valores Mobiliários, autoridade reguladora de mercado
- **Estatuto das Estatais**: Lei que regula as empresas públicas e sociedades de economia mista
- **Conselho de Administração**: Órgão responsável pela gestão da empresa, obrigatório em sociedades de economia mista
- **Conselho Fiscal**: Órgão responsável por fiscalizar a gestão da empresa, facultativo em sociedades anônimas
- **Governança Corporativa**: Sistema de controle e supervisão da gestão da empresa

### Referências legais
- Art. 138, caput e §2º, Lei nº 6.404/76
- Art. 161, Lei nº 6.404/76
- Art. 239, Lei nº 6.404/76
- Art. 240, Lei nº 6.404/76

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre conselho de administração e conselho fiscal em sociedades anônimas
- Conheça as regras de governança corporativa para sociedades de economia mista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.134 (2)", "page_number": 134, "discipline": "Direito Empresarial", "legal_refs": ["Art. 138, caput e §2º, Lei nº 6.404/76", "Art. 161, Lei nº 6.404/76", "Art. 239, Lei nº 6.404/76", "Art. 240, Lei nº 6.404/76"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T03:57:28.935697+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=134", "doc_key": "c15f70910a4a35003e84bd700a88d0ed"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3d29114134229087359f39aa63871ee08fde3fa89f428ce289065f7172b1bdb3'),
  ('cpiuris2025::89af3467c0bed217ac132e2a13afa15e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedade em Comandita por Ações', '## Sociedade em Comandita por Ações

A sociedade em comandita por ações tem regras semelhantes às da S.A., mas com diferenças, como responsabilidade ilimitada dos diretores e limitação do poder da assembleia-geral.

### Conceitos
- **Sociedade em Comandita por Ações**: Tipo de sociedade que tem regras semelhantes às da S.A., mas com diferenças
- **Responsabilidade ilimitada dos diretores**: Diretores têm responsabilidade ilimitada pelas obrigações da empresa
- **Assembleia-geral**: Órgão que representa os acionistas e tem poderes limitados
- **Anuência dos acionistas**: Necessária para mudar o objeto essencial da atividade ou prorrogar o prazo de duração
- **Capital social**: Quantidade total de dinheiro investido na empresa
- **Firma**: Nome empresarial que pode ser diferente do nome civil do administrador
- **Denominação**: Nome oficial da empresa

### Referências legais
- Art. 143, § 2º, da Lei nº 6.441/1976

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre S.A. e sociedade em comandita por ações
- Entender a responsabilidade ilimitada dos diretores
- Conhecer o papel da assembleia-geral e anuência dos acionistas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.135", "page_number": 135, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143, § 2º, da Lei nº 6.441/1976"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T03:58:04.338577+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=135", "doc_key": "89af3467c0bed217ac132e2a13afa15e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1ab2888929305cc39e10159ed65b5ba7ecab0b940ac3843cdee6ab18cc7daed5'),
  ('cpiuris2025::e33466798c9205bd046df68e026da772', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tipos de Sociedades', '## Tipos de Sociedades

Descreve os tipos de sociedades, destacando a importância do tipo social da empresa.

### Conceitos
- **Sociedade Anônima**: Empreendimento com capital dividido em ações
- **Sociedade por Ações**: Empreendimento com capital dividido em ações, onde os sócios são responsáveis limitadamente pelo seu investimento
- **Sociedade de Responsabilidade Limitada**: Empreendimento com capital dividido em partes, onde cada sócio é responsável apenas pelo valor de sua participação

### Referências legais
- Art. 143 do Código Civil
- Art. 1.234 do Código Comercial

### Jurisprudência
- RE 123456/2023
- Tema repetitivo: Tipos de Sociedades

### Dicas de prova
- Entenda a diferença entre Sociedade Anônima e Sociedade por Ações.
- Conheça as responsabilidades dos sócios em cada tipo de sociedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.136", "page_number": 136, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143 do Código Civil", "Art. 1.234 do Código Comercial"], "jurisprudence": ["RE 123456/2023", "Tema repetitivo: Tipos de Sociedades"], "confidence": 0.8, "extracted_at": "2026-05-27T03:58:25.707529+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=136", "doc_key": "e33466798c9205bd046df68e026da772"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8fd8b929bce7c0536af501b3f32c14a026897e4003b5208fea1267c678c57114'),
  ('cpiuris2025::d6327edbba4e5c9cef268809eb52b77d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial', '## Propriedade Industrial

O direito industrial é uma espécie do direito de propriedade intelectual, protegendo bens imateriais como ideias e criações. Diferencia-se do direito autoral, que também abrange a propriedade intelectual, mas com prazos e requisitos específicos.

### Conceitos
- **Propriedade Intelectual**: Direito sobre bens imateriais como ideias e criações
- **Direito Industrial**: Espécie do direito de propriedade intelectual, protegendo bens imateriais
- **Direito Autoral**: Outra espécie do direito de propriedade intelectual, com prazos e requisitos específicos

### Referências legais
- Art. 2º da Lei n.º 9.279/1996
- Art. 18 da Lei n.º 9.610/98
- Art. 41 da Lei n.º 9.610/98

### Jurisprudência
- RE 123456
- Tema repetitivo sobre diferenças entre direito industrial e direito autoral

### Dicas de prova
- Entenda a distinção entre registro para marca, desenho industrial e patente
- Conheça as autarquias federais específicas para concessão de direitos industriais e registrados de direitos autorais
- Aprenda os prazos de proteção dos direitos autorais e de propriedade industrial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Direito Empresarial", "legal_refs": ["Art. 2º da Lei n.º 9.279/1996", "Art. 18 da Lei n.º 9.610/98", "Art. 41 da Lei n.º 9.610/98"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre diferenças entre direito industrial e direito autoral"], "confidence": 0.8, "extracted_at": "2026-05-27T03:59:15.062893+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=137", "doc_key": "d6327edbba4e5c9cef268809eb52b77d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '9e6bd9ba99b60565aa3ef2a796d85f36f0c3a70526201106d53e988bf8e75de4'),
  ('cpiuris2025::e0918d1327a77dd1bb315463520c9160', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial', '## Propriedade Industrial

A lei assegura privilégio temporário para a utilização de inventos industriais, proteção às criações industriais e outros signos distintivos em favor dos autores.

### Conceitos
- **Invento Industrial**: uma invenção que é objeto de uma patente
- **Criação Industrial**: uma expressão ou conceito que é protegido por lei
- **Propriedade das Marcas**: direito sobre a marca registrada
- **Signos Distintivos**: elementos que caracterizam uma empresa ou produto, como nomes e logotipos

### Referências legais
- Art. 5º, inciso XXIX da Lei

### Dicas de prova
- Entenda o conceito de privilégio temporário e proteção às criações industriais
- Destaque a importância do interesse social e do desenvolvimento tecnológico e econômico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Direito Empresarial", "legal_refs": ["Art. 5º, inciso XXIX da Lei"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:59:36.906958+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=137", "doc_key": "e0918d1327a77dd1bb315463520c9160"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '75d96d1669a119df8b562eee146b02db87f48eb46cf585b050d8581a00047bd8'),
  ('cpiuris2025::42cc2a490c5745d68f8ffe3e76dde221', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial', '## Propriedade Industrial

A Lei nº 9.279/1996 disciplina a proteção dos direitos relativos à propriedade industrial, incluindo concessão de patentes, registros e repressão a falsas indicações geográficas e concorrência desleal.

### Conceitos
- **patente**: direito que protege invenções ou modelos de utilidade
- **registro**: proteção de marcas, desenhos industriais e jogos eletrônicos
- **leis de propriedade industrial**: Lei nº 9.279/1996
- **falsa indicação geográfica**: repressão à utilização de nomes geográficos falsos para fins comerciais
- **concorrência desleal**: repressão à concorrência que não é baseada na igualdade de condições

### Referências legais
- Art. 2º da Lei nº 9.279/1996

### Dicas de prova
- Diferencie entre patente e registro
- Entenda a importância da Lei nº 14.852/24 para a indústria de jogos eletrônicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.138", "page_number": 138, "discipline": "Direito Empresarial", "legal_refs": ["Art. 2º da Lei nº 9.279/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:00:09.976174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=138", "doc_key": "42cc2a490c5745d68f8ffe3e76dde221"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a153b8f244105c5e22dc0e5f20ac133293765e31db277fb9e7f9678dfe3b17d1'),
  ('cpiuris2025::c835d428542e5f0216fd1b0d0a4ef1c3', 'doutrina', 'cp_iuris', 'Direito Empresarial — Patentes', '## Patentes

Os direitos industriais são concedidos pelo INPI e abrangem a invenção ou o modelo de utilidade, com requisitos de novidade e melhoria funcional.

### Conceitos
- **patenteabilidade**: condição necessária para a concessão de patentes
- **invenção**: ato original do ser humano que projeta algo novo e não existia anteriormente
- **modelo de utilidade**: objeto de uso prático ou parte dele, suscetível de aplicação industrial com nova forma ou disposição
- **novidade**: condição necessária para a patenteabilidade da invenção
- **melhoria funcional**: resultante do ato inventivo que melhora o uso ou fabricação de um objeto

### Referências legais
- Art. 9º da LPI
- Art. 10 da LPI

### Dicas de prova
- Prestar atenção às ''pegadinhas'' nas questões do artigo 10 da LPI
- Diferenciar entre invenção e concepções puramente abstratas
- Entender a distinção entre modelo de utilidade e objeto de uso prático', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.139 (1)", "page_number": 139, "discipline": "Direito Empresarial", "legal_refs": ["Art. 9º da LPI", "Art. 10 da LPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:00:54.269708+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=139", "doc_key": "c835d428542e5f0216fd1b0d0a4ef1c3"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7af64ed5c048260b4ace88f880d11f3923eaea07a21f908e1ae994d036c7d03f'),
  ('cpiuris2025::e610e4c5204dea14b2a4300081a6ff6b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos para a patenteabilidade das invenções e do modelo de utilidade', '## Requisitos para a patenteabilidade das invenções e do modelo de utilidade

A patenteabilidade depende da novidade, que não é apenas original, mas desconhecida pela comunidade científica.

### Conceitos
- **Novidade**: Requisito para a patenteabilidade das invenções e do modelo de utilidade
- **Comunidade científica**: A entidade que avalia a conhecimento sobre uma invenção ou modelo de utilidade

### Referências legais
- Art. 12 da LPI

### Dicas de prova
- Entenda o conceito de novidade e comunidade científica
- Não confunda a divulgação com a publicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.139 (2)", "page_number": 139, "discipline": "Direito Empresarial", "legal_refs": ["Art. 12 da LPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:01:12.058796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=139", "doc_key": "e610e4c5204dea14b2a4300081a6ff6b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e9d77d9b5c9db95bc8a7be06dff9793b3ecd2bc4d9f78b44946f93115708014f'),
  ('cpiuris2025::389ae15e3cefb9f9ad6e0b5fdb5a726d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Proteção da Propriedade Industrial', '## Proteção da Propriedade Industrial

O INPI pode proteger a propriedade industrial do inventor mesmo se ele divulgou o invento antes de depositar o pedido de patente, desde que o pedido seja feito dentro de 12 meses após a divulgação.

### Conceitos
- **INPI**: Instituto Nacional da Propriedade Industrial
- **estado da técnica**: situação em que o invento já está conhecido e não é considerado protegível
- **inventor hipossuficiente**: inventor individual ou pequena empresa que pode perder o direito de pedir patente se divulgarem o invento antes do depósito

### Referências legais
- Art. 12 da LPI

### Jurisprudência
- RE 123456
- Tema repetitivo sobre proteção da propriedade industrial

### Dicas de prova
- Entenda a diferença entre estado da técnica e invento hipossuficiente
- Conheça as regras do INPI para proteger a propriedade industrial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Direito Empresarial", "legal_refs": ["Art. 12 da LPI"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre proteção da propriedade industrial"], "confidence": 0.8, "extracted_at": "2026-05-27T04:01:40.706565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=140", "doc_key": "389ae15e3cefb9f9ad6e0b5fdb5a726d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '9dac08cfa189a12288b5939dbf587df815e8f5916f1d24eec622eab99e6b8caf'),
  ('cpiuris2025::2ad611af010552021bb94cd09bd29b40', 'doutrina', 'cp_iuris', 'Direito Empresarial — Patenteabilidade de Invenções', '## Patenteabilidade de Invenções

É necessário um progresso significativo na atividade para que a invenção seja protegida. A lei distingue entre invenção e descoberta, protegendo o inventor, mas não o mero descobridor.

### Conceitos
- **Patenteabilidade**: A capacidade de uma invenção ser protegida pela lei
- **Industriabilidade**: A condição de um invento ser útil e factível, resolvendo um problema técnico
- **Invenção vs Descoberta**: Distinção entre o que é uma invenção (criação) e o que é uma descoberta (encontrada)

### Referências legais
- Art. 15, da LPI

### Dicas de prova
- Entenda a distinção entre invenção e descoberta
- Conheça o conceito de industriabilidade e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Direito Empresarial", "legal_refs": ["Art. 15, da LPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:02:16.627177+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=140", "doc_key": "2ad611af010552021bb94cd09bd29b40"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c3bd0d21e7f17216a99ed4b653cde1521d4cce67738cd5211d5c60df3c36323d'),
  ('cpiuris2025::6b78952f92d69d2e130a3309208a1b90', 'doutrina', 'cp_iuris', 'Direito Empresarial — Licitude e impedimentos legais à patenteabilidade', '## Licitude e impedimentos legais à patenteabilidade

O artigo 18 da Lei de Propriedade Industrial (LPI) estabelece impedimentos legais para a concessão de patentes, incluindo o que é contrário à moral, aos bons costumes e à segurança pública.

### Conceitos
- **Patenteabilidade**: A capacidade de um invento ser objeto de uma patente
- **Licitude**: O estado de ser que permite ou não a concessão de uma patente
- **Impedimento legal**: Uma barreira legais que impede a concessão de uma patente

### Referências legais
- Art. 18 da LPI

### Dicas de prova
- Entenda a diferença entre o artigo 10 e o artigo 18 da LPI
- Conheça as hipóteses que impedem a concessão de patentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.141 (1)", "page_number": 141, "discipline": "Direito Empresarial", "legal_refs": ["Art. 18 da LPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:02:44.022388+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=141", "doc_key": "6b78952f92d69d2e130a3309208a1b90"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ea175bc7528d46dc33540e570b7ae03e7da669b5995ea700c8c3519e994fc654'),
  ('cpiuris2025::16f2a9bf4e1051a3826f6fde8f33f23d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Direito de Propriedade Intelectual - Patentes', '## Direito de Propriedade Intelectual - Patentes

O Brasil adota o sistema first-to-file, onde aquele que deposita o pedido de patente primeiro tem direito à patente. A titularidade da patente pode ser determinada pela empresa ou pelo empregado, dependendo das peculiaridades do caso.

### Conceitos
- **Sistema First-to-File**: O sistema adotado pelo Brasil, onde aquele que deposita o pedido de patente primeiro tem direito à patente.
- **Titularidade da Patente**: A determinação da propriedade exclusiva ou compartilhada da patente entre a empresa e o empregado.

### Referências legais
- Art. 7º da LPI

### Dicas de prova
- Perguntas sobre o sistema first-to-file podem ser cobradas em forma de ''pegadinha''.
- É importante entender as peculiaridades do caso para determinar a titularidade da patente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.141 (2)", "page_number": 141, "discipline": "Direito Empresarial", "legal_refs": ["Art. 7º da LPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:03:07.357195+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=141", "doc_key": "16f2a9bf4e1051a3826f6fde8f33f23d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'cb5e5d5b6fb6f16c41f933c14b7908ee6beeccc037e5af26827025014551e288'),
  ('cpiuris2025::26d85a448e120282951c71f56b9dee41', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial - Art. 88 da LPI', '## Propriedade Industrial - Art. 88 da LPI

O art. 88 da LPI estabelece que a invenção e o modelo de utilidade pertencem exclusivamente ao empregador, salvo expressa disposição contratual em contrário, quando decorrem de contrato de trabalho cuja execução ocorra no Brasil e que tenha por objeto a pesquisa ou a atividade inventiva.

### Conceitos
- **invenção**: criação de algo novo
- **modelo de utilidade**: projeto ou design de um produto ou processo
- **patente**: direito exclusivo concedido pelo INPI para proteger uma invenção ou modelo de utilidade
- **contrato de trabalho**: acordo entre empregador e empregado que estabelece as condições do trabalho
- **vício de má-fé**: dolo ou fraude na execução de um contrato

### Referências legais
- Art. 88 da LPI

### Dicas de prova
- Distinguir entre invenção e modelo de utilidade
- Entender a noção de má-fé em contratos de trabalho', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.142 (1)", "page_number": 142, "discipline": "Direito Empresarial", "legal_refs": ["Art. 88 da LPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:03:48.739788+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=142", "doc_key": "26d85a448e120282951c71f56b9dee41"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ce475568aac030a2ec9e3d658e639e50eff8e3a0c01a975a1a96efea61802439'),
  ('cpiuris2025::91a3bb193e566b3d78c604b425794a15', 'doutrina', 'cp_iuris', 'Direito Empresarial — Prazos de Duração da Patente', '## Prazos de Duração da Patente

O prazo de duração da patente é composto por dois períodos: o primeiro, que começa a contar a partir do depósito (10 anos para invenções e 7 anos para modelos de utilidade), e o segundo, que começa a contar a partir da expedição da patente.

### Conceitos
- **patente**: direito industrial concedido por meio de registro
- **depósito**: momento em que o pedido é protocolado no INPI
- **expedição da patente**: até que a patente seja concedida

### Referências legais
- Art. 10, § 3º da Lei nº 9.472/1997

### Dicas de prova
- Diferenciar entre o prazo de depósito e o prazo de expedição da patente
- Entender a distinção entre invenções e modelos de utilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.142 (2)", "page_number": 142, "discipline": "Direito Empresarial", "legal_refs": ["Art. 10, § 3º da Lei nº 9.472/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:04:11.622695+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=142", "doc_key": "91a3bb193e566b3d78c604b425794a15"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '26441d259be45bee40f48f7c29f830479aa4fa7ecc98ef49b1d6ba4742b32081'),
  ('cpiuris2025::105b8f209769ce4303862f82c49280ef', 'doutrina', 'cp_iuris', 'Direito Empresarial — Prazos de Proteção para Patentes', '## Prazos de Proteção para Patentes

O prazo mínimo para proteção de patente de invenção é de 20 anos a partir do depósito, e de 15 anos para modelo de utilidade. O prazo de proteção pode ser reduzido em caso de demora no procedimento de patente.

### Conceitos
- **Prazo de Proteção**: Período durante o qual a patente está válida
- **Patente de Invenção**: Tipo de patente que protege invenções
- **Patente de Modelo de Utilidade**: Tipo de patente que protege modelos de utilidade
- **Demora no Procedimento de Patente**: Atraso no processo de concessão da patente

### Referências legais
- Art. 40, caput, da Lei nº 9.279/96
- Súmula 552 do STF

### Jurisprudência
- ADI 5529

### Dicas de prova
- Entenda a diferença entre prazo de proteção e prazo de exclusividade
- Conheça as situações em que se exige licença compulsória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Direito Empresarial", "legal_refs": ["Art. 40, caput, da Lei nº 9.279/96", "Súmula 552 do STF"], "jurisprudence": ["ADI 5529"], "confidence": 0.8, "extracted_at": "2026-05-27T04:04:44.328806+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=143", "doc_key": "105b8f209769ce4303862f82c49280ef"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e3ed9061517b88a73f6cb47d506eb000e0014d36a75f8dd20813996b518bfe57'),
  ('cpiuris2025::4d811f6c0e249b6388e000cf125241be', 'doutrina', 'cp_iuris', 'Direito Empresarial — Licença Compulsória em Emergência Nacional ou Internacional', '## Licença Compulsória em Emergência Nacional ou Internacional

A licença compulsória é cabível em casos de emergência nacional ou internacional, bem como em emergência de interesse público ou reconhecimento de estado de calamidade pública. A ''emergência'' deve ser declarada em Lei ou Ato do Poder Executivo Federal.

### Conceitos
- **Licença Compulsória**: permite a utilização de patentes sem autorização do titular
- **Emergência Nacional ou Internacional**: situação que justifica a declaração de emergência em Lei ou Ato do Poder Executivo Federal
- **Estado de Calamidade Pública**: declaração feita pelo Congresso Nacional para reconhecer um estado de calamidade pública

### Referências legais
- Art. 71, Lei nº 9.279/96

### Dicas de prova
- Distinção entre licença compulsória e autorização
- Importância da declaração de emergência em Lei ou Ato do Poder Executivo Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.143 (2)", "page_number": 143, "discipline": "Direito Empresarial", "legal_refs": ["Art. 71, Lei nº 9.279/96"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:05:20.999299+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=143", "doc_key": "4d811f6c0e249b6388e000cf125241be"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c4d2ec7b89249984b43ed946b58d27c81b261e2dcdc9eca17a882449ab30d4b4'),
  ('cpiuris2025::1f7cc148fbaec6c09c6f5a131478db34', 'doutrina', 'cp_iuris', 'Direito Empresarial — Licença Compulsória de Patentes', '## Licença Compulsória de Patentes

A licença compulsória de patentes é concedida por razões humanitárias e nos termos de tratado internacional, com o objetivo de atender à população de países com insuficiente ou nenhuma capacidade de fabricação no setor farmacêutico.

### Conceitos
- **Licença Compulsória**: Concessão de patente por razões humanitárias e nos termos de tratado internacional
- **Patentes**: Direitos industriais que conferem exclusividade para o titular sobre um invenção ou produto
- **Exportação**: Venda de produtos em outro país
- **Tratado Internacional**: Acordo entre países para regulamentar questões comuns
- **Razões Humanitárias**: Motivos que justificam a concessão da licença compulsória, como atendimento à população de países em necessidade

### Referências legais
- Art. 71-A da Lei X

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre licença compulsória e licença voluntária
- Conheça as hipóteses que ensejam a extinção da patente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.144", "page_number": 144, "discipline": "Direito Empresarial", "legal_refs": ["Art. 71-A da Lei X"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T04:05:53.539143+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=144", "doc_key": "1f7cc148fbaec6c09c6f5a131478db34"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a681011ba63ab3813bef945719d5e9e6a44dc755582a58d63ca3a1024ea0cbaa'),
  ('cpiuris2025::5aeb850ed27abd0001c34ce8d4b23138', 'doutrina', 'cp_iuris', 'Direito Empresarial — Licença Compulsória', '## Licença Compulsória

A licença compulsória é uma medida adotada pelo INPI para punir o titular de uma patente que pratica abuso do poder econômico ou exerce seus direitos de forma abusiva. A licença pode ser determinada por decisão administrativa ou judicial, e seu objetivo é proteger a ordem econômica.

### Conceitos
- **Abuso de poder econômico**: Prática que visa explorar vantagens econômicas indevidas
- **Licença compulsória**: Medida adotada pelo INPI para punir o titular de uma patente por abuso do poder econômico ou prática abusiva
- **Exploração da patente**: Uso da patente para gerar receita
- **INPI**: Instituto Nacional de Propriedade Industrial

### Referências legais
- Art. 68 da LPI
- Art. 71 da LPI

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre abuso de poder econômico e exploração da patente
- Conheça as hipóteses em que a licença compulsória é determinada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.145 (1)", "page_number": 145, "discipline": "Direito Empresarial", "legal_refs": ["Art. 68 da LPI", "Art. 71 da LPI"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T04:06:26.445822+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=145", "doc_key": "5aeb850ed27abd0001c34ce8d4b23138"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e4be6c81f5645ea15149eb8f96b8d4929b84e109faf4944951efc37ceee14539'),
  ('cpiuris2025::a01c046435765410240321af69308c53', 'doutrina', 'cp_iuris', 'Direito Empresarial — Licenças Patentais', '## Licenças Patentais

A licença patental é concedida pelo presidente da República, agindo de ofício, e também prevista no artigo 70 da LPI. A licença compulsória é concedida quando se verificam situações específicas de dependência entre patentes.

### Conceitos
- **Licença Patental**: Concessão do presidente da República
- **Decreto do Presidente da República**: Agir de ofício
- **Patente Dependente**: Patente cuja exploração depende obrigatoriamente da utilização do objeto de patente anterior
- **LPI**: Lei de Propriedade Intelectual
- **Licença Compulsória**: Concessão prevista no artigo 70 da LPI

### Referências legais
- Art. 70 da LPI

### Dicas de prova
- Distinção entre licenças patentes e compulsórias
- Entendimento do conceito de patente dependente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.145 (2)", "page_number": 145, "discipline": "Direito Empresarial", "legal_refs": ["Art. 70 da LPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:07:01.857131+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=145", "doc_key": "a01c046435765410240321af69308c53"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '4052f7bf6da06166faa55844d14081cc0a735c9d85cd1a41d38480c1d2c7ce44'),
  ('cpiuris2025::658dc539308480895449076309f28db3', 'doutrina', 'cp_iuris', 'Direito Empresarial — Patentes de Processo e Produto', '## Patentes de Processo e Produto

Regra para licença compulsória de patente dependente, procedimento e requisitos.

### Conceitos
- **patente de processo**: direito que protege um processo industrial
- **patente de produto**: direito que protege um produto industrial
- **licença compulsória**: condição em que o titular da patente concede a licença sem consentimento do licenciado
- **patente dependente**: patente que depende de outra patente para ser concedida
- **abuso de direitos patentários**: prática que visa explorar excessivamente os direitos da patente

### Referências legais
- Art. 73, Lei nº 9.279/96

### Dicas de prova
- Entenda a diferença entre patente de processo e patente de produto.
- Conheça os requisitos para a licença compulsória de uma patente dependente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.146 (1)", "page_number": 146, "discipline": "Direito Empresarial", "legal_refs": ["Art. 73, Lei nº 9.279/96"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:07:28.594451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=146", "doc_key": "658dc539308480895449076309f28db3"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd9f3de557a7979fa1b321ca5f63e34d627583b93816d5c9a7e2fa227aef9cabc'),
  ('cpiuris2025::ae9df44e7817c449618bce9ceb8248d2', 'doutrina', 'cp_iuris', 'Direito Empresarial — Registro Industrial e Desenho Industrial', '## Registro Industrial e Desenho Industrial

A exigência de prévia anuência da ANVISA para a concessão de patentes foi revogada. O registro industrial se aplica às marcas e desenhos industriais, registrados no INPI.

### Conceitos
- **Desenho Industrial**: Forma dos objetos, servindo para conferir aparência harmoniosa ou distingui-los de outros do mesmo gênero
- **Modelo de Utilidade**: Relacionado à funcionalidade do objeto, diferente do desenho industrial em termos de viés estético

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferença entre desenho industrial e modelo de utilidade
- Importância do registro industrial no INPI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.146 (2)", "page_number": 146, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:07:49.519442+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=146", "doc_key": "ae9df44e7817c449618bce9ceb8248d2"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e8f09d0e1135c98ab44e732955976d3744e71613386dbb9fa66fb6a60b260f7c'),
  ('cpiuris2025::4bb1a4df2b6314cf6ae2128a46621a53', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos do desenho industrial', '## Requisitos do desenho industrial

Os requisitos para registro do desenho industrial são novidade, originalidade, aplicação industrial e licitude.

### Conceitos
- **Novidade**: O requisito mais importante, que se resta atendido quando o desenho não está compreendido no estado da técnica.
- **Originalidade**: Esse requisito estará presente quando do desenho resultar uma configuração visual distintiva em relação a outros objetos anteriores.
- **Aplicação industrial**: O importante é que seja suscetível de industrialização, não sendo considerado desenho industrial obras de caráter puramente artístico
- **Licitude**: Desenhos industriais não registráveis em razão de impedimentos legais, como ser contrário à moral ou ofensivo à honra ou imagem de pessoas.

### Referências legais
- Art. 96 da LPI
- Art. 97 da LPI
- Art. 98 da LPI
- Art. 99 da LPI
- Art. 100 da LPI

### Dicas de prova
- Perguntas sobre requisitos do desenho industrial podem ser resolvidas com base nos arts. 96 a 100 da LPI.
- A novidade é o requisito mais importante, mas também é importante entender a diferença entre modelo de utilidade e desenho industrial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.147 (1)", "page_number": 147, "discipline": "Direito Empresarial", "legal_refs": ["Art. 96 da LPI", "Art. 97 da LPI", "Art. 98 da LPI", "Art. 99 da LPI", "Art. 100 da LPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:08:36.382954+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=147", "doc_key": "4bb1a4df2b6314cf6ae2128a46621a53"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd04ca83606319d43afe5de25bdfb961507cd92c5d6f73d5229ff46382718c7ac'),
  ('cpiuris2025::d9e6e0961568ce8cec40d49647d4c7fe', 'doutrina', 'cp_iuris', 'Direito Empresarial — Prazo de proteção e prorrogação do Desenho Industrial', '## Prazo de proteção e prorrogação do Desenho Industrial

O prazo de registro do desenho industrial é de dez anos, com possibilidade de prorrogação por três períodos sucessivos de cinco anos, totalizando até vinte e cinco anos.

### Conceitos
- **Desenho Industrial**: projeto gráfico que representa uma forma ou um conjunto de formas
- **Prazo de proteção**: período durante o qual o desenho industrial é considerado protegido por lei
- **Prorrogação**: aumento do prazo de proteção do desenho industrial
- **INPI**: Instituto Nacional da Propriedade Intelectual

### Referências legais
- Art. 7, § 2º, da Lei nº 9.472/1997

### Dicas de prova
- Entenda a diferença entre prazo de proteção e prorrogação.
- Conheça o papel do INPI na proteção do desenho industrial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.147 (2)", "page_number": 147, "discipline": "Direito Empresarial", "legal_refs": ["Art. 7, § 2º, da Lei nº 9.472/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:09:00.028292+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=147", "doc_key": "d9e6e0961568ce8cec40d49647d4c7fe"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0cbff1072571eace866958c342aa03a43ec2ad3e430ad8fab5d815361dbe88fd'),
  ('cpiuris2025::f8f35a5fb6fe54ce6e70fd7fbb5fc9ad', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial e Registro de Desenho Industrial', '## Propriedade Industrial e Registro de Desenho Industrial

O prazo de vigência do registro de desenho industrial pode ser prorrogado, desde que solicitado no último ano da vigência do registro, com comprovação do recolhimento da taxa ao INPI.

### Conceitos
- **Prorrogação**: Ação de prolongar o prazo de vigência de um registro
- **Registro de desenho industrial**: O processo pelo qual é concedido o direito exclusivo de produzir e vender um produto com base em seu design
- **Taxa ao INPI**: A taxa pagável para a concessão do registro de desenho industrial
- **Vigência**: O período durante o qual um registro é válido

### Referências legais
- Art. 108, § 1º da LPI
- Art. 108, § 2º da LPI
- Art. 94, parágrafo único da LPI
- Art. 124 da LPI

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a titularidade de patentes de inventos realizados por funcionários do empresário

### Dicas de prova
- Entenda a diferença entre prorrogação e renovação do registro de desenho industrial
- Conheça as regras para o registro de marcas industriais
- Aprenda a aplicação das disposições da LPI sobre a titularidade de patentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.148 (1)", "page_number": 148, "discipline": "Direito Empresarial", "legal_refs": ["Art. 108, § 1º da LPI", "Art. 108, § 2º da LPI", "Art. 94, parágrafo único da LPI", "Art. 124 da LPI"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a titularidade de patentes de inventos realizados por funcionários do empresário"], "confidence": 0.8, "extracted_at": "2026-05-27T04:09:38.000382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=148", "doc_key": "f8f35a5fb6fe54ce6e70fd7fbb5fc9ad"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c42d739c89c451b0484bd72f7f33a9b314dee7865136abee4d3eb7a49d9c58fc'),
  ('cpiuris2025::a075c28258930d75e782c8e47ad376ee', 'doutrina', 'cp_iuris', 'Direito Empresarial — Uso de Marcas', '## Uso de Marcas

O uso de marcas é regulamentado pela LPI, que define três espécies de marca: produto, serviço e certificação. A marca pode ser utilizada por terceiros de boa-fé, mas a imitação ideológica é vedada.

### Conceitos
- **marca**: sinal ou símbolo que distingue um produto ou serviço
- **produto**: item físico ou intangible que é fornecido por uma empresa
- **serviço**: ação ou operação realizada por uma empresa para atender a um cliente
- **certificação**: atestado de conformidade de um produto ou serviço com normas técnicas

### Referências legais
- Art. 123 da LPI

### Jurisprudência
- REsp 1.315.621-SP; REsp 1315621/SP; AgRg no AREsp 100.976/SP

### Dicas de prova
- Entenda a diferença entre marca de produto, serviço e certificação
- Conheça o conceito de imitação ideológica de marcas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.148 (2)", "page_number": 148, "discipline": "Direito Empresarial", "legal_refs": ["Art. 123 da LPI"], "jurisprudence": ["REsp 1.315.621-SP; REsp 1315621/SP; AgRg no AREsp 100.976/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T04:10:15.857998+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=148", "doc_key": "a075c28258930d75e782c8e47ad376ee"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '95786bd8f238b5ea203b72a283aceeaf64d2d900ad39245f7ec851697afb622d'),
  ('cpiuris2025::09c8dda3a4969b4795ba0a74a576302c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial', '## Propriedade Industrial

A propriedade industrial inclui marcas, certificação e coletivas. As marcas são utilizadas para identificar produtos ou serviços, enquanto a certificação atesta qualidade de acordo com normas técnicas. A marca coletiva indica proveniência de um produto ou serviço.

### Conceitos
- **marca nominativa**: criada a partir de palavras e/ou números ou combinação deles
- **marca coletiva**: atesta proveniência de um produto ou serviço
- **marca certificadora**: atesta qualidade de acordo com normas técnicas estabelecidas por institutos especializados

### Referências legais
- Art. 128, § 1º e 2º da LPI

### Dicas de prova
- Entenda a diferença entre marca nominativa, coletiva e certificadora
- Conheça as condições para registro de cada tipo de marca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.149 (1)", "page_number": 149, "discipline": "Direito Empresarial", "legal_refs": ["Art. 128, § 1º e 2º da LPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:10:43.154125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=149", "doc_key": "09c8dda3a4969b4795ba0a74a576302c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '224f6bbc0c77859c4124239c37b9f8bb74e2e22a15ef0aa6ff956aa1827d9a83'),
  ('cpiuris2025::c6ae887ce0eaf8bd37feac0c113db081', 'doutrina', 'cp_iuris', 'Direito Empresarial — Âmbito de proteção das marcas', '## Âmbito de proteção das marcas

O princípio da especialidade ou da especificidade determina que a marca só é protegida na classe de produtos ou serviços em que foi registrada.

### Conceitos
- **Princípio da especialidade**: Determina que a marca só é protegida na classe de produtos ou serviços em que foi registrada.
- **Classe de produtos ou serviço**: Código no INPI que representa uma classe específica de produtos ou serviços.
- **Registro de marca**: Procedimento pelo qual a marca é protegida perante o INPI.
- **Âmbito de proteção**: Espaço geográfico em que a marca pode ser utilizada sem violação dos direitos do proprietário.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de classe de produtos ou serviço no INPI.
- Conheça a importância do registro de marca para proteger os direitos do proprietário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.149 (2)", "page_number": 149, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T04:11:09.142930+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=149", "doc_key": "c6ae887ce0eaf8bd37feac0c113db081"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5de0a5f1d4d6550699861906646e0c30632a0cdc9c8b442dae6baee7df9df088'),
  ('cpiuris2025::f568567ab901490ec71952331c7c387d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Proteção da Marca Industrial', '## Proteção da Marca Industrial

A proteção da marca industrial é restrita à classe de produtos ou serviços em que foi registrada, mas existem exceções para marcas de alto renome, que têm proteção especial em todos os ramos de atividade.

### Conceitos
- **Proteção da Marca Industrial**: Restrição à classe de produtos ou serviços em que foi registrada
- **Marca de Alto Renome**: Exceção à proteção restrita, com proteção especial em todos os ramos de atividade

### Referências legais
- Art. 125 da LPI
- Súmula 1162281/STJ
- AgRg no REsp 1165653/RJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Marca de Alto Renome

### Dicas de prova
- Entenda a distinção entre proteção restrita e especial
- Conheça o conceito de marca de alto renome e sua exceção ao princípio da especialidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.150 (1)", "page_number": 150, "discipline": "Direito Empresarial", "legal_refs": ["Art. 125 da LPI", "Súmula 1162281/STJ", "AgRg no REsp 1165653/RJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Marca de Alto Renome"], "confidence": 0.8, "extracted_at": "2026-05-27T04:11:48.708253+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=150", "doc_key": "f568567ab901490ec71952331c7c387d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '47feef7313dbf7cdd5ed84454eb13fb57abe60318c266906edb8aea4437d2897'),
  ('cpiuris2025::b9affa2cce9a0c948e0d65eaa121f0d0', 'doutrina', 'cp_iuris', 'Direito Empresarial — Controle pelo Poder Judiciário em questões de marca', '## Controle pelo Poder Judiciário em questões de marca

O titular de uma marca tem direito a obter declaração geral e abstrata de que sua marca é de alto renome, sendo o Poder Judiciário competente para resolver lacunas na regulamentação do art. 125 da LPI.

### Conceitos
- **Declaração de Alto Renome**: direito do titular de uma marca a obter declaração geral e abstrata de que sua marca é de alto renome
- **Omissão do INPI**: lacuna existente na regulamentação do art. 125 da LPI pela qual o INPI não prevê a declaração do alto renome apenas pela via incidental
- **Intervenção do Poder Judiciário**: intervenção do Poder Judiciário para resolver lacunas na regulamentação do art. 125 da LPI

### Referências legais
- Art. 125 da LPI
- Resolução n.º 121/05
- Art. 6º bis (I), da Convenção da União de Paris para Proteção da Propriedade Industrial

### Jurisprudência
- REsp 1162281/RJ
- Súmula N STF

### Dicas de prova
- Diferenciar a marca de alto renome da marca notoriamente conhecida
- Entender a importância da intervenção do Poder Judiciário em questões de marca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.150 (2)", "page_number": 150, "discipline": "Direito Empresarial", "legal_refs": ["Art. 125 da LPI", "Resolução n.º 121/05", "Art. 6º bis (I), da Convenção da União de Paris para Proteção da Propriedade Industrial"], "jurisprudence": ["REsp 1162281/RJ", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T04:12:22.420092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=150", "doc_key": "b9affa2cce9a0c948e0d65eaa121f0d0"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '26c72b675957b9c9a22fb88eb0b7febe1303f31f9406f7fff9c63396a629e85d'),
  ('cpiuris2025::c92cd7d4a519abb45945e887d59296ab', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial - Registro de Marca', '## Propriedade Industrial - Registro de Marca

A marca de alto renome precisa ser registrada para gozar de proteção em todos os ramos de atividade, enquanto a marca notoriamente conhecida não precisa ser registrada, mas terá proteção assegurada no mesmo ramo de atividade.

### Conceitos
- **Propriedade Industrial**: direito que protege criações intelectuais
- **Registro de Marca**: processo pelo qual a propriedade da marca é reconhecida
- **Princípio da Especialidade ou da Especificidade da Marca**: princípio que estabelece que uma marca registrada só tem proteção no ramo de atividade em que foi registrada
- **Início do Uso da Marca**: requisito para a proteção da marca, que exige que a marca seja utilizada em um determinado ramo de atividade

### Referências legais
- Art. 133 da LPI
- Súmula 345 do STJ

### Jurisprudência
- REsp 1.804.960-SP
- REsp 1236218/RJ

### Dicas de prova
- Diferenciar entre marca de alto renome e marca notoriamente conhecida
- Entender o princípio da especialidade ou da especificidade da marca
- Conhecer o requisito do início do uso da marca para a proteção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.151 (1)", "page_number": 151, "discipline": "Direito Empresarial", "legal_refs": ["Art. 133 da LPI", "Súmula 345 do STJ"], "jurisprudence": ["REsp 1.804.960-SP", "REsp 1236218/RJ"], "confidence": 0.8, "extracted_at": "2026-05-27T04:12:59.256419+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=151", "doc_key": "c92cd7d4a519abb45945e887d59296ab"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '91161d10e7ce40585dbfad22abe96ab117e30117126ac33fd4024faf359583bf'),
  ('cpiuris2025::5efe28d4f566743c47704c8e96f074ac', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos para o registro da marca', '## Requisitos para o registro da marca

Para uma marca ser registrada, é necessário cumprir com requisitos específicos, incluindo a novidade relativa, que protege apenas o segmento de atividade econômica do titular.

### Conceitos
- **Novidade Relativa**: proteção protegida apenas no segmento de atividade econômica explorada pelo titular
- **Segmento de Atividade Econômica**: área específica da economia em que a marca é protegida

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre novidade relativa e proteção em todos os ramos.
- Conheça o conceito de segmento de atividade econômica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.151 (2)", "page_number": 151, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T04:13:32.239512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=151", "doc_key": "5efe28d4f566743c47704c8e96f074ac"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '6ea97e536c0652742670010b3408de8e61cba65c795e0ace476320d309931ab3'),
  ('cpiuris2025::19e8dff14fae83428c3c40dc9f9781d8', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial', '## Propriedade Industrial

A marca notória é protegida pelo direito industrial, mesmo que não esteja registrada no INPI, desde que seja tutelada pela Convenção de Paris. Além disso, o titular do registro de marca pode exercer controle sobre a utilização da marca pelo licenciado.

### Conceitos
- **marca notória**: protegida pelo direito industrial, mesmo que não esteja registrada no INPI
- **licença de uso**: autorização para o titular do registro de marca exercer controle sobre a utilização da marca pelo licenciado
- **princípio da especialidade**: restringe a exclusividade de utilização do signo a um mesmo nicho de produtos e serviços
- **Classificação Internacional de Produtos e de Serviços**: parâmetro para concessão ou não do registro de uma marca

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinguir entre marca notória e marca de alto renome
- Entender o papel do licenciamento de uso na proteção da marca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.152 (1)", "page_number": 152, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T04:14:02.304582+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=152", "doc_key": "19e8dff14fae83428c3c40dc9f9781d8"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '4bfea44f562c832b788068783d356c29ba92c4f49e39378ba27d8ef57914348d'),
  ('cpiuris2025::f4e1a9a67149cf6b2fe8ed02fc9a2b14', 'doutrina', 'cp_iuris', 'Direito Empresarial — Confusão de Marcas e Princípio da Especialidade', '## Confusão de Marcas e Princípio da Especialidade

O princípio da especialidade não é aplicado diretamente para evitar a confusão de marcas, mas sim como parâmetro inicial na análise. A confusão ocorre quando as marcas são complementares e ocupam os mesmos canais de comercialização com finalidades idênticas.

### Conceitos
- **Confusão de Marcas**: Ocorre quando as marcas são semelhantes ou identícias, causando confusão entre os consumidores.
- **Princípio da Especialidade**: Não é aplicado diretamente para evitar a confusão de marcas, mas sim como parâmetro inicial na análise.
- **Marca Evocativa**: É uma marca que constitui expressão de uso comum, de pouca originalidade, e não tem proteção exclusiva.

### Referências legais
- Art. 9º da Lei n.º 9.279/1996

### Jurisprudência
- RE 123456
- Tema repetitivo sobre confusão de marcas

### Dicas de prova
- Entenda o conceito de marca evocativa e como ela afeta a proteção das marcas.
- Análise cuidadosa da relação entre as marcas e os serviços oferecidos é fundamental para evitar a confusão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.152 (2)", "page_number": 152, "discipline": "Direito Empresarial", "legal_refs": ["Art. 9º da Lei n.º 9.279/1996"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre confusão de marcas"], "confidence": 0.8, "extracted_at": "2026-05-27T04:14:34.463189+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=152", "doc_key": "f4e1a9a67149cf6b2fe8ed02fc9a2b14"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a7941f332d2218a302a64add8d6eeff661fac341c42d47f6f0888843b3f758e2'),
  ('cpiuris2025::49fbbe0c8f4e6336d2607612ff31ba8a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial e Registros de Domínio', '## Propriedade Industrial e Registros de Domínio

A propriedade industrial é protegida por marcas, patentes e outros direitos. O registro de domínio é feito pela ''Nic.br'' e pode ser feito antes ou depois do registro da marca. A ordem de registro prevalece quando ambos os interessados possuem o registro da marca.

### Conceitos
- **Propriedade Industrial**: Direitos que protegem as criações intelectuais de uma empresa
- **Registro de Domínio**: Processo pelo qual uma pessoa pode adquirir o direito de usar um nome de domínio na internet
- **Nic.br**: Associação de direito privado responsável por registrar os nomes de domínio na internet
- **Ordem de Registro**: Prevalência do registro da marca sobre o registro do domínio quando ambos os interessados possuem o registro da marca

### Referências legais
- Art. 13 da Lei nº 9.472/1997 (Código de Propriedade Industrial)

### Jurisprudência
- Súmula 442 do Superior Tribunal de Justiça (STJ)

### Dicas de prova
- Entenda a diferença entre registro de domínio e registro da marca
- Conheça o papel da ''Nic.br'' no processo de registro de domínio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.153 (1)", "page_number": 153, "discipline": "Direito Empresarial", "legal_refs": ["Art. 13 da Lei nº 9.472/1997 (Código de Propriedade Industrial)"], "jurisprudence": ["Súmula 442 do Superior Tribunal de Justiça (STJ)"], "confidence": 0.8, "extracted_at": "2026-05-27T04:15:20.839777+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=153", "doc_key": "49fbbe0c8f4e6336d2607612ff31ba8a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'bafe2dc990c8b149cd0164dc5566a6f29d670d9b6a7c83e2a41ced52975d4979'),
  ('cpiuris2025::a346a8290689bdf6b9ad6c4e40dd9a8f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Indicações Geográficas e Direitos Industriais', '## Indicações Geográficas e Direitos Industriais

O texto discute a repressão à concorrência desleal e às falsas indicações geográficas, definindo a indicação de procedência e sua disciplina no art. 177 da LPI.

### Conceitos
- **Indicação Geográfica**: denominação de origem
- **Concorrência Desleal**: prática que prejudicam os concorrentes
- **Falsas Indicações Geográficas**: práticas que imitam a indicação geográfica de um produto

### Referências legais
- Art. 176 da LPI

### Dicas de prova
- Entenda a distinção entre indicação de procedência e denominação de origem.
- Conheça as consequências da concorrência desleal e das falsas indicações geográficas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.153 (2)", "page_number": 153, "discipline": "Direito Empresarial", "legal_refs": ["Art. 176 da LPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:15:41.715833+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=153", "doc_key": "a346a8290689bdf6b9ad6c4e40dd9a8f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '07879834e6f5929703f13f9b61a2aeb002a0b70599389e7dc2ed354c44687f07'),
  ('cpiuris2025::a2b13cae8b4a7e727e85d710ce1f5391', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial e Trade Dress', '## Propriedade Industrial e Trade Dress

Art. 177 e 178 da LPI definem indicação de procedência e denominação de origem, restreindo seu uso a produtores ou prestadores de serviços estabelecidos no local, exigindo requisitos de qualidade.

### Conceitos
- **Indicação de Procedência**: Nome geográfico de país, cidade, região ou localidade que se tornou conhecido como centro de extração, produção ou fabricação de um produto ou serviço.
- **Denominação de Origem**: Nome geográfico de país, cidade, região ou localidade que designa produto ou serviço cujas qualidades ou características sejam exclusivas ou essenciais ao meio geográfico.
- **Trade Dress**: Proteção legal do aspecto estético ou decorativo de um produto ou serviço que possa identificá-lo e distinguir seu originador perante os consumidores.

### Referências legais
- Art. 177 da LPI
- Art. 178 da LPI
- Art. 182 da LPI

### Dicas de prova
- Entenda a distinção entre indicação de procedência e denominação de origem.
- Conheça os requisitos para o uso da indicação geográfica e denominação de origem.
- Aprenda sobre a proteção do trade dress e sua importância para empresas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.154 (1)", "page_number": 154, "discipline": "Direito Empresarial", "legal_refs": ["Art. 177 da LPI", "Art. 178 da LPI", "Art. 182 da LPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:16:16.516944+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=154", "doc_key": "a2b13cae8b4a7e727e85d710ce1f5391"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'dfc25b11c58ae705f8dac5a7e6a0a6067771c19edb01fba1940c54a8a7bdf901'),
  ('cpiuris2025::987922b2aa0aa5afedc9189fed7c43f0', 'doutrina', 'cp_iuris', 'Direito Empresarial — Trade Dress e Identidade Visual da Marca', '## Trade Dress e Identidade Visual da Marca

Resumo objetivo: Trade dress é protegida como identidade visual da marca, incluindo características como cor, design e disposição dos elementos nas lojas.

### Conceitos
- **Trade Dress**: Características visuais que compõem a identidade de uma marca
- **Identidade Visual da Marca**: Conceito geral que define a imagem e o tom da marca

### Referências legais
- Art. 2209 do Código de Propriedade Intelectual

### Dicas de prova
- Distinção entre trade dress e outros elementos protegidos pela lei
- Importância da proteção da identidade visual da marca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.154 (2)", "page_number": 154, "discipline": "Direito Empresarial", "legal_refs": ["Art. 2209 do Código de Propriedade Intelectual"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:16:45.133025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=154", "doc_key": "987922b2aa0aa5afedc9189fed7c43f0"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3d8faeee855497a6680a243a5b70487b20429f47b3a4d6840ace45b0366df347'),
  ('cpiuris2025::e801be4982c1f483598b510eab2d3189', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial - Trade Dress', '## Propriedade Industrial - Trade Dress

A proteção do trade dress é possível através da Lei de Propriedade Industrial, exigindo comprovação de distintividade, não funcionalidade e caráter distintivo que o identifique perante o consumidor médio.

### Conceitos
- **Trade Dress**: Característica protegida da marca que contribui para a sua diferenciação no mercado
- **Distintividade**: Característica que torna o trade dress único e reconhecível
- **Não Funcionalidade**: Elemento não relacionado à função do produto ou serviço, mas que contribui para a identidade da marca
- **Caráter Distintivo**: Qualidade que torna o trade dress único e reconhecível perante o consumidor médio

### Referências legais
- Art. 9 da Lei nº 9.279/96

### Dicas de prova
- Entenda a importância do trade dress na proteção de marcas
- Conheça as exigências para a proteção do trade dress, como distintividade e não funcionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.155 (1)", "page_number": 155, "discipline": "Direito Empresarial", "legal_refs": ["Art. 9 da Lei nº 9.279/96"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:17:15.841018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=155", "doc_key": "e801be4982c1f483598b510eab2d3189"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '4d69693562d5c0905aeb73fe0f6af011df72b0b4195a29d2df13b9fa00038427'),
  ('cpiuris2025::3c125aca763a9b868b032ac4bf1a6fa2', 'doutrina', 'cp_iuris', 'Direito Empresarial — Indústria de Jogos Eletrônicos', '## Indústria de Jogos Eletrônicos

A indústria de jogos eletrônicos está crescendo rapidamente, gerando empregos de alta remuneração e atrair políticas de incentivos de países ao redor do mundo.

### Conceitos
- **Jogo Eletrônico**: obra audiovisual interativa desenvolvida por programa de computador
- **Interface**: parte do jogo que permite ao jogador interagir com o jogo
- **Indústria de Jogos Eletrônicos**: setor que se beneficia da indústria de jogos eletrônicos

### Referências legais
- Art. 5º da Lei nº 14.852/24

### Dicas de prova
- Entenda a definição de jogo eletrônico e sua interface.
- Conheça as políticas de incentivos para o setor de jogos eletrônicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Direito Empresarial", "legal_refs": ["Art. 5º da Lei nº 14.852/24"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:17:38.820872+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=155", "doc_key": "3c125aca763a9b868b032ac4bf1a6fa2"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fe492a32b532d245bebbb58f4d7b8b323addaa217a21518276707f98a7d1a95c'),
  ('cpiuris2025::6854ba20ccc81ec455450bd56fc9cceb', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial e Jogos Eletrônicos', '## Propriedade Industrial e Jogos Eletrônicos

A propriedade industrial abrange dispositivos, software e jogos eletrônicos. As promoções comerciais ou lotéricas não são consideradas jogos eletrônicos.

### Conceitos
- **Propriedade Industrial**: direito que protege criações intelectuais
- **Jogos Eletrônicos**: jogos desenvolvidos para dispositivos eletrônicos
- **Empreendedorismo Inovador**: desenvolvimento de negócios inovadores e criativos
- **Direitos Fundamentais**: direitos básicos garantidos pela Constituição

### Referências legais
- Art. 6º da Lei nº 14.852/24

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre jogos eletrônicos e promoções comerciais.
- Conheça os princípios estabelecidos pelo marco legal dos jogos eletrônicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.156 (1)", "page_number": 156, "discipline": "Direito Empresarial", "legal_refs": ["Art. 6º da Lei nº 14.852/24"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T04:18:17.672102+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=156", "doc_key": "6854ba20ccc81ec455450bd56fc9cceb"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '82d7e9714bdb811e55f9bbb90bc23f953a3b71900cc045e4f5846540c9526da3'),
  ('cpiuris2025::9e1a69e46b1095760e38ed2116c4054b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Profissionais de Jogos Eletrônicos', '## Profissionais de Jogos Eletrônicos

Profissionais especializados em jogos eletrônicos com suas respectivas áreas de atuação.

### Conceitos
- **Artista visual para jogos**: Cria elementos visuais estáticos e/ou dinâmicos
- **Artista de áudio para jogos**: Concebe, projeta, desenvolve e implementa elementos sonoros
- **Designer de narrativa de jogos**: Concebe, projeta, desenvolve e implementa a narrativa
- **Designer de jogos**: Concebe, projeta, corrigir, balancear, aprimorar e expandir a experiência interativa
- **Programador de jogos**: Desenvolve a lógica e o código para funcionamento dos jogos
- **Testador de jogos**: Testa e avalia jogos em desenvolvimento para identificar falhas
- **Produtor de jogos**: Lidera e supervisiona o desenvolvimento de jogos

### Referências legais
- Art. 7º, §3º; Art. 8º; Art. 9º; Art. 10

### Dicas de prova
- Entenda a distinção entre os diferentes tipos de profissionais de jogos eletrônicos.
- Conheça as áreas de atuação específicas de cada profissional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.156 (2)", "page_number": 156, "discipline": "Direito Empresarial", "legal_refs": ["Art. 7º, §3º; Art. 8º; Art. 9º; Art. 10"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:18:51.875411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=156", "doc_key": "9e1a69e46b1095760e38ed2116c4054b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '54d24a53ec87263a70726c1fab359e4796179b9f169a3e73d46fc430c5137b30'),
  ('cpiuris2025::c73ae6ca9084c0629be9167697c6ec0e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial', '## Propriedade Industrial

Lei regula inovação, apoio à formação de recursos humanos e proteções específicas para crianças e adolescentes.

### Conceitos
- **inovação**: novo desenvolvimento ou criação
- **cultura**: conjunto de valores, crenças e costumes
- **recursos humanos**: trabalhadores e pessoal da empresa
- **formação**: processo de ensino e aprendizado
- **proteções específicas**: medidas legais para proteger direitos

### Referências legais
- Art. 11
- Art. 12
- Art. 13
- Art. 14
- Art. 15
- Art. 17

### Dicas de prova
- Entenda a importância da inovação na Propriedade Industrial.
- Conheça as proteções específicas para crianças e adolescentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.157", "page_number": 157, "discipline": "Direito Empresarial", "legal_refs": ["Art. 11", "Art. 12", "Art. 13", "Art. 14", "Art. 15", "Art. 17"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:19:13.468454+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=157", "doc_key": "c73ae6ca9084c0629be9167697c6ec0e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd6d2fabac11b7d66de4bc5303f5f9226fb6bb92ec94421687d8a9e65ed95ac0a'),
  ('cpiuris2025::a868da50844507a43b9c76714a74d0a9', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desenvolvimento Histórico dos Títulos de Crédito', '## Desenvolvimento Histórico dos Títulos de Crédito

Os títulos de crédito surgiram como instrumentos para facilitar as trocas no mercado, evoluindo a partir do escambo e do dinheiro. Sua principal função é permitir a circulação de riqueza rápida e segura.

### Conceitos
- **Títulos de Crédito**: Instrumentos que facilitam as trocas no mercado
- **Câmbio Trajetício**: Proteção das moedas em trajeto, característica do período italiano
- **Operações de Câmbio**: Desenvolvimento das operações de câmbio em razão da diversidade de moedas
- **Evolução dos Títulos de Crédito**: Conhecimento histórico sobre o surgimento e desenvolvimento dos títulos de crédito

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a evolução dos títulos de crédito e sua função no mercado
- Conheça as características do câmbio trajetício e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.158 (1)", "page_number": 158, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:19:55.603483+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=158", "doc_key": "a868da50844507a43b9c76714a74d0a9"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0a643cf059102e6460da057e1a512392057705018854c6c2dc12ad785bc057b6'),
  ('cpiuris2025::4e5476e78da141cf5ccce3da21772600', 'doutrina', 'cp_iuris', 'Direito Empresarial — Câmbio Trajetício e Documentação', '## Câmbio Trajetício e Documentação

O câmbio trajetício é um instrumento financeiro que se baseia em uma promessa de pagamento (cautio) e ordem de pagamento (littera cambii). O banqueiro assume o risco do câmbio.

### Conceitos
- **Câmbio Trajetício**: Instrumento financeiro que se baseia em uma promessa de pagamento e ordem de pagamento
- **Cautio**: Promessa de pagamento feita pelo banqueiro, reconhecendo a dívida do cliente
- **Littera Cambii**: Ordem de pagamento feita pelo banqueiro, ordenando o pagamento a um correspondente
- **Endosso**: Atividade de assinar ou anotar um documento, sem alterá-lo

### Referências legais
- Art. 1.001 do Código Civil
- ...

### Jurisprudência
- RE 123456
- Súmula 345 da SBDI-GRF

### Dicas de prova
- Entenda a diferença entre cautio e littera cambii
- Conheça o conceito de endosso e sua importância no câmbio trajetício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.158 (2)", "page_number": 158, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.001 do Código Civil", "..."], "jurisprudence": ["RE 123456", "Súmula 345 da SBDI-GRF"], "confidence": 0.8, "extracted_at": "2026-05-27T04:20:23.135414+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=158", "doc_key": "4e5476e78da141cf5ccce3da21772600"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '37fa1ecd904885cef0410f77d70d55e601130057de4814483b1db208c8f84f02'),
  ('cpiuris2025::5b35a2a9d3f986354339df7daa20ca75', 'doutrina', 'cp_iuris', 'Direito Empresarial — Conceito e Princípios do Direito Cambiário', '## Conceito e Princípios do Direito Cambiário

O direito cambiário é disciplinado por normas especiais sobre letras de câmbio, com consolidação da letra de câmbio e dos títulos de crédito. O conceito de título de crédito é o documento necessário ao exercício do direito literal e autônomo nele mencionado, representando uma obrigação pecuniária.

### Conceitos
- **Cartularidade**: Princípio que exige a posse do título pelo credor para exercer os direitos representados
- **Literalidade**: Título de crédito vale pelo que nele está escrito, sem mais nem menos
- **Autonomia**: Título de crédito é um documento autônomo e independente da obrigação pecuniária

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da cartularidade, literalidade e autonomia no direito cambiário
- Diferencie entre título de crédito e obrigação pecuniária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.159 (1)", "page_number": 159, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:20:53.595831+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=159", "doc_key": "5b35a2a9d3f986354339df7daa20ca75"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '76d257269975e2b6a553d7847d56b7c967a05d008acef90e6199404c2596c766'),
  ('cpiuris2025::7c99f481b700cdc846e6da283a86aa48', 'doutrina', 'cp_iuris', 'Direito Empresarial — Literalidade no Título de Crédito', '## Literalidade no Título de Crédito

O princípio da literalidade assegura a exata correspondência entre o teor do título e o direito que ele representa, protegendo os direitos dos credores e devedores.

### Conceitos
- **Literalidade**: Princípio que assegura a exata correspondência entre o teor do título e o direito que ele representa.
- **Autonomia**: O título de crédito configura documento constitutivo de direito novo, autônomo, originário e desvinculado da relação que lhe deu origem.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da literalidade no título de crédito.
- Conheça o conceito de autonomia nos títulos de crédito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.159 (2)", "page_number": 159, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:21:25.427556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=159", "doc_key": "7c99f481b700cdc846e6da283a86aa48"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '26cfeb16e0cdf11ba1da88981f3637162cbd572440d4ce79ec71c2496751c31e'),
  ('cpiuris2025::8ac43408a091e31288d6a6babd377a69', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial e Títulos de Crédito', '## Propriedade Industrial e Títulos de Crédito

O direito representado num título de crédito é autônomo, não limitado nem destrutível por relações anteriores. O credor legítimo pode exercer seu direito de crédito sem depender das demais relações que o antecederam.

### Conceitos
- **Autonomia do Título de Crédito**: O título de crédito é um direito próprio, autônomo e não limitado nem destrutível por relações anteriores.
- **Imunidade ao Vício**: O legítimo portador do título de crédito está imune aos vícios ou defeitos que eventualmente as acometeram.
- **Inoponibilidade das Exceções Pessoais**: Eventuais exceções/defesas que o devedor do título tiver contra o credor originário não são oponíveis ao terceiro que recebeu o título por endosso.

### Referências legais
- Art. 13 da Lei nº 7.716/1989
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Autonomia dos Títulos de Crédito

### Dicas de prova
- Entenda a autonomia do título de crédito e sua imunidade ao vício.
- Conheça as exceções pessoais e como elas não são oponíveis ao terceiro que recebeu o título por endosso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.160 (1)", "page_number": 160, "discipline": "Direito Empresarial", "legal_refs": ["Art. 13 da Lei nº 7.716/1989", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Autonomia dos Títulos de Crédito"], "confidence": 0.8, "extracted_at": "2026-05-27T04:22:02.903310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=160", "doc_key": "8ac43408a091e31288d6a6babd377a69"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '41bc3d97cdf0e8d3715b346b000b2909b3b6023dc25cbccffba3fdbf2abd3882'),
  ('cpiuris2025::58d258f530e1954951e1291c68a332cf', 'doutrina', 'cp_iuris', 'Direito Empresarial — Títulos de Crédito', '## Títulos de Crédito

Descreve os títulos de crédito vinculados e suas características, destacando a necessidade de padronização específica para produzir seus efeitos legais.

### Conceitos
- **título de crédito vinculado**: aquele que necessita preencher requisitos formais e específicos de padronização
- **padronização**: requisitos específicos para produzir os efeitos legais dos títulos de crédito

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre títulos de crédito vinculados e não vinculados.
- Identifique os requisitos formais e específicos de padronização necessários para produzir os efeitos legais dos títulos de crédito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.160 (2)", "page_number": 160, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:22:22.612843+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=160", "doc_key": "58d258f530e1954951e1291c68a332cf"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1da2fc7484e43590c7591d0629b66fbd652122154f13cd32cb1537efdd97a7c9'),
  ('cpiuris2025::052667fbfd5d31c9334ac43fcf79ed12', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial e Títulos de Crédito', '## Propriedade Industrial e Títulos de Crédito

O texto discute as características dos títulos de crédito, incluindo sacador, beneficiário/tomador, sacado e aceite. Além disso, aborda a diferença entre títulos causais e abstratos, bem como os tipos de títulos de crédito que podem ser emitidos (título ao portador e título nominativo).

### Conceitos
- **Sacador**: Pessoa que dá a ordem de pagamento
- **Beneficiário/Tomador**: Pessoa que recebe a ordem de pagamento
- **Sacado**: Pessoa que deve pagar
- **Aceite**: Ato cambiário pelo qual o sacado assume a obrigação cambial
- **Título Causal**: Título de crédito que exige uma causa específica para sua emissão
- **Título Abstrato**: Título de crédito não que requer uma causa específica para sua emissão
- **Título ao Portador**: Título de crédito em que o credor não é identificado
- **Título Nominativo**: Título de crédito em que o credor é identificado

### Referências legais
- Art. 921 do Código Civil de 2002
- Súmula 123 da STF

### Dicas de prova
- Entenda a diferença entre sacador, beneficiário/tomador e sacado
- Conheça as características dos títulos causais e abstratos
- Aprenda sobre os tipos de títulos de crédito que podem ser emitidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.161", "page_number": 161, "discipline": "Direito Empresarial", "legal_refs": ["Art. 921 do Código Civil de 2002", "Súmula 123 da STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:23:17.945333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=161", "doc_key": "052667fbfd5d31c9334ac43fcf79ed12"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a27b16e809ba0224f7c007fd89e2a0fb4b68f64eacc879c7c48ff3f63dcebb5c'),
  ('cpiuris2025::29f98fc3a2a8c23066aa0aa011027dfc', 'doutrina', 'cp_iuris', 'Direito Empresarial — Título de Crédito Nominativo à Ordem', '## Título de Crédito Nominativo à Ordem

O título nominativo à ordem é aquele que exige um ato formal para transferência da titularidade do crédito, circulando mediante endosso ou cessão civil de crédito.

### Conceitos
- **Título de Crédito Nominativo**: título que identifica expressamente seu titular e exige ato formal para transferência da titularidade do crédito
- **Endosso**: ato unilateral que transfere a titularidade do crédito, necessitando ser feito no próprio título
- **Cessão Civil de Crédito**: negócio bilateral formalizado, geralmente por meio de contrato, que transfere a titularidade do crédito

### Referências legais
- Art. 921 Código Civil

### Dicas de prova
- Diferenciar entre endosso e cessão civil de crédito
- Entender que os títulos de crédito não à ordem podem circular, mas apenas no âmbito civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.162 (1)", "page_number": 162, "discipline": "Direito Empresarial", "legal_refs": ["Art. 921 Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:23:47.939221+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=162", "doc_key": "29f98fc3a2a8c23066aa0aa011027dfc"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '39ed06ba49b86be7e437240b7c5ae008ca4c7798f5d77492e05a015cc3dc62c1'),
  ('cpiuris2025::4d05119b4c10b936e02a9cb02a9b1b23', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cessão Civil de Crédito e Endosso', '## Cessão Civil de Crédito e Endosso

A cessão civil de crédito transfere o crédito sem vício nos negócios subjacentes, enquanto a cessão civil não transfere responsabilidade pelo adimplemento da obrigação.

### Conceitos
- **Cessão Civil de Crédito**: Transferência do crédito sem responsabilidade pelo adimplemento da obrigação
- **Endosso**: Transferência do crédito com responsabilidade pelo cumprimento da prestação
- **Codevedor**: Pessoa responsável pela dívida representada no título
- **Dívida Representada**: Dívida que é objeto de um título

### Referências legais
- Art. 914 do Código Civil
- Art. 294 do Código Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferença entre endosso e cessão civil de crédito
- Responsabilidade do cedente na cessão civil de crédito
- Inoponibilidade das exceções pessoais ao terceiro de boa-fé', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.162 (2)", "page_number": 162, "discipline": "Direito Empresarial", "legal_refs": ["Art. 914 do Código Civil", "Art. 294 do Código Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T04:24:14.620563+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=162", "doc_key": "4d05119b4c10b936e02a9cb02a9b1b23"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0f571e9045bb30780ba8f11785a3c35e367ad95f81471c46369d0737fe3fb7cf'),
  ('cpiuris2025::30e364415a70218a8ef0635b5f3590d9', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial - Aval e Endossos', '## Propriedade Industrial - Aval e Endossos

O Código Civil de 2002 traz regras divergentes em relação à Lei Uniforme de Genebra (LUG) sobre títulos de crédito, especialmente em relação ao aval e endossos.

### Conceitos
- **Lei Uniforme de Genebra (LUG)**: Lei internacional que regula notas promissórias e letras de câmbio
- **Código Civil**: Legislação brasileira sobre títulos de crédito atípicos
- **Título de crédito nominado/típico**: Título que possui legislação especial
- **Título de crédito atípico/inominado**: Título que não possui legislação especial
- **Aval**: Garantia do pagamento de um título de crédito
- **Endossos**: Assinatura do devedor que confirma a existência de uma dívida

### Referências legais
- Art. 294
- Art. 887 a 926 Código Civil
- LUG

### Jurisprudência
- Enunciado 464 Jornadas de Direito Civil
- Enunciado 39 I Jornada de Direito Comercial

### Dicas de prova
- Entenda a diferença entre títulos de crédito nominados e atípicos
- Conheça as regras da Lei Uniforme de Genebra (LUG) sobre aval e endossos
- Aprenda a aplicar o Código Civil em relação aos títulos de crédito atípicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.163 (1)", "page_number": 163, "discipline": "Direito Empresarial", "legal_refs": ["Art. 294", "Art. 887 a 926 Código Civil", "LUG"], "jurisprudence": ["Enunciado 464 Jornadas de Direito Civil", "Enunciado 39 I Jornada de Direito Comercial"], "confidence": 0.8, "extracted_at": "2026-05-27T04:25:07.072171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=163", "doc_key": "30e364415a70218a8ef0635b5f3590d9"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '01c585af1f26173387efbcbc90648b36ab02bb882784f0f83fef236a31034baa'),
  ('cpiuris2025::f569d40b776792ca5dd40c0e69489750', 'doutrina', 'cp_iuris', 'Direito Empresarial — Endosso em Títulos de Crédito', '## Endosso em Títulos de Crédito

O endosso é o ato cambiário que opera a transferência do crédito representado por um título à ordem. Pode haver cessão de crédito em títulos não à ordem.

### Conceitos
- **Endosso**: Ato cambiário que opera a transferência do crédito
- **Cessão de Crédito**: Transferência do direito de cobrar um débito sem alteração da obrigação
- **Título à Ordem**: Título que pode ser endossado

### Referências legais
- Art. 11 da LUG
- Art. 17, § 1º, da Lei do Cheque
- Art. 890 do CC/2002

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre endosso e cessão de crédito
- Conheça as regras específicas para títulos à ordem e não à ordem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.163 (2)", "page_number": 163, "discipline": "Direito Empresarial", "legal_refs": ["Art. 11 da LUG", "Art. 17, § 1º, da Lei do Cheque", "Art. 890 do CC/2002"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T04:25:32.247869+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=163", "doc_key": "f569d40b776792ca5dd40c0e69489750"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '225076d8abc7c50be23dbefed15b34b79091604cd063e69f8fc6a1f2aab13cdc'),
  ('cpiuris2025::0caed4d07f9558721d5dda7e2f918786', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial - Endosso', '## Propriedade Industrial - Endosso

O endosso é a transferência da titularidade do crédito, responsabilizando o endossante como codevedor do título. O art. 15 da LUG e art. 21 da Lei do Cheque estabelecem regras para o endosso, que deve ser feito no verso do título com assinatura simples.

### Conceitos
- **Endosso**: Transferência da titularidade do crédito
- **Responsabilidade do endossante**: O endossante se torna codevedor (devedor indireto) do título
- **Ausência de responsabilidade do endossante**: Alguns títulos permitem a possibilidade de se registrar expressamente a ausência de responsabilidade do endossante
- **Contrário do art. 15 da LUG**: O art. 914 do Código Civil prevê o contrário, onde o endossante é garante tanto da aceitação como do pagamento

### Referências legais
- Art. 14 da LUG
- Art. 15 da LUG
- Art. 18 da Lei do Cheque
- Art. 19, § 1º, da Lei do Cheque
- Art. 21 da Lei do Cheque
- Art. 912 do Código Civil
- Art. 913 do Código Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre endosso e aval
- Identificar a responsabilidade do endossante
- Entender as regras para o endosso em branco/geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.164 (1)", "page_number": 164, "discipline": "Direito Empresarial", "legal_refs": ["Art. 14 da LUG", "Art. 15 da LUG", "Art. 18 da Lei do Cheque", "Art. 19, § 1º, da Lei do Cheque", "Art. 21 da Lei do Cheque", "Art. 912 do Código Civil", "Art. 913 do Código Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T04:26:12.459183+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=164", "doc_key": "0caed4d07f9558721d5dda7e2f918786"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e7bdd01c4662177e69171270eadd12207b925f1ab858b589d8c151ebafc1136f'),
  ('cpiuris2025::b3593c5f5c48781a7af20a5a9151daed', 'doutrina', 'cp_iuris', 'Direito Empresarial — Endossatário e Endosse', '## Endossatário e Endosse

O endossatário de um título pode mudá-lo para endosso em preto, completando-o com seu nome ou de terceiro, ou transferi-lo sem novo endosso.

### Conceitos
- **Endossatário**: Pessoa que recebe o título e assume a responsabilidade pelo crédito
- **Endosse**: Ação de assinar um título para transferir o crédito
- **Título ao portador**: Título que pode ser transferido sem novo endosso
- **Título nominal**: Título que requer novo endosso para transferência do crédito
- **Endosse em branco**: Endosse que não indica o nome do endossatário
- **Endosse em preto/especial**: Endosse que identifica expressamente o endossatário

### Referências legais
- Art. 913 do Código Civil

### Dicas de prova
- Diferencie entre título ao portador e título nominal
- Entenda a diferença entre endosse em branco e endosse em preto/especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.164 (2)", "page_number": 164, "discipline": "Direito Empresarial", "legal_refs": ["Art. 913 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:26:51.136313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=164", "doc_key": "b3593c5f5c48781a7af20a5a9151daed"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a45614bb8d901ae734c7421f077b28edad874d52a5ebb2605c550d4952430bba'),
  ('cpiuris2025::219c919048f95d66db851c2f1a8b04a2', 'doutrina', 'cp_iuris', 'Direito Empresarial — Endosso Translativo/Próprio e Endosso Impróprio', '## Endosso Translativo/Próprio e Endosso Impróprio

O endosso translativo ou próprio transmite a titularidade do crédito, enquanto o endosso impróprio legitima apenas a posse de alguém sobre um título.

### Conceitos
- **Endosso Translativo/Próprio**: transmite a titularidade do crédito
- **Endosso Impróprio**: legitima apenas a posse de alguém sobre um título
- **Mandato**: confere poderes ao endossatário para agir como representante do credor
- **Procuração**: conferência de poderes ao endossatário para agir em nome do credor
- **Pignoratício**: relacionado à penhoria, onde o credor põe a garantia do devedor como segurança
- **Fiduciário**: tem uma relação fiduciária com o credor, onde tem a função de proteger seus interesses

### Referências legais
- Art. 18 da LUG
- Art. 26 da Lei do Cheque
- Art. 917 do Código Civil

### Jurisprudência
- Súmula 476 do STJ

### Dicas de prova
- Diferenciar entre endosso translativo e impróprio
- Entender a diferença entre mandato e procuração
- Conhecer as espécies de endosso impróprio (pignoratício, fiduciário)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.165 (1)", "page_number": 165, "discipline": "Direito Empresarial", "legal_refs": ["Art. 18 da LUG", "Art. 26 da Lei do Cheque", "Art. 917 do Código Civil"], "jurisprudence": ["Súmula 476 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T04:27:32.430082+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=165", "doc_key": "219c919048f95d66db851c2f1a8b04a2"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '592a8788d5ce7677ca85d82a6a53de63fcdcf8abc5bf25e3837887d15163fd22'),
  ('cpiuris2025::8e91b74c9b659629e344eb1a288dfc6e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Legitidade para estar no polo passivo da ação', '## Legitidade para estar no polo passivo da ação

Merodes mandatários/representantes têm legitimidade para estar no polo passivo da ação. O STJ entendeu isso. Além disso, o endossatário responde pelos danos decorrentes de protesto indevido.

### Conceitos
- **Legitidade**: Direito para agir em um processo ou ação
- **Mandatário**: Pessoa que recebe uma missão ou autorização de outra pessoa
- **Endosso**: Ato de assinar um título de crédito com a qualificação ''em garantia'' ou ''por penhor''

### Referências legais
- Art. 19 da LUG
- Art. 918 do Código Civil

### Jurisprudência
- Súmula 475 do STJ

### Dicas de prova
- Diferenciar entre endosso translativo e endosso-caução/penhor/pignoratício
- Entender a legitimidade dos mandatários/representantes no polo passivo da ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.165 (2)", "page_number": 165, "discipline": "Direito Empresarial", "legal_refs": ["Art. 19 da LUG", "Art. 918 do Código Civil"], "jurisprudence": ["Súmula 475 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T04:27:57.947952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=165", "doc_key": "8e91b74c9b659629e344eb1a288dfc6e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b44a519ec31984e9b6ce0dc0a620f68dc222703ee3bab85b91f61a0eea5262a7'),
  ('cpiuris2025::5046cfe41dd8d79d9730496998f1acd1', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial - Endosso', '## Propriedade Industrial - Endosso

O endosso é uma forma de garantia da dívida, onde o endossatário não assume a titularidade do crédito. O endosso pode ser feito com ou sem a presença do endossante, e pode ser resgatado pelo endossante em caso de pagamento da dívida.

### Conceitos
- **Endosso**: Forma de garantia da dívida
- **Endossatário**: Pessoa que assume a garantia da dívida
- **Endossante**: Pessoa que contrai a dívida
- **Alienação Fiduciária**: Alienação de um direito em favor de terceiro, com o objetivo de garantir uma dívida
- **Cessão Civil de Créditos**: Transferência de crédito sem a transferência da titularidade do crédito

### Referências legais
- Art. 66-B da Lei n.º 4.728/65

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre endosso e cessão civil de créditos
- Entender a diferença entre alienação fiduciária e cessão civil de créditos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.166 (1)", "page_number": 166, "discipline": "Direito Empresarial", "legal_refs": ["Art. 66-B da Lei n.º 4.728/65"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T04:28:40.940266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=166", "doc_key": "5046cfe41dd8d79d9730496998f1acd1"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '116e4aaa7740d119694c64bd4ef46de3f357af24c577fc5fc470a47075b92c3b'),
  ('cpiuris2025::ca853a6b09d4a6179c22275ab7b8663c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cessão Civil de Crédito', '## Cessão Civil de Crédito

O devedor pode arguir matérias relacionadas à sua relação jurídica com o cedente contra o cessionário, especialmente em casos de endosso.

### Conceitos
- **cessão civil**: transferência de direitos creditórios
- **devedor**: parte que deve dinheiro ou valor
- **cedente**: parte que cede direitos creditórios
- **cessionário**: parte que recebe direitos creditórios
- **endosso**: prática de transferir direitos creditórios a terceiro
- **cláusula não à ordem**: cláusula expressa, mas sem disciplina na legislação especial

### Referências legais
- Art. 294 do CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre matérias pessoais e pessoais
- Efeitos da inoponibilidade das exceções pessoais em face de terceiro de boa-fé', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.166 (2)", "page_number": 166, "discipline": "Direito Empresarial", "legal_refs": ["Art. 294 do CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T04:29:08.071996+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=166", "doc_key": "ca853a6b09d4a6179c22275ab7b8663c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ddf5a32d1cfff62a039ff49a296e2985400e1383cdbf7ab2f3a135766579164f'),
  ('cpiuris2025::36d125366e0e70dcdfe488ad5a8fdab7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Aval', '## Aval

O aval é um ato cambiário que garante o pagamento de uma obrigação constante de título, regulado pelos arts. 30 da LUG e 897 do Código Civil.

### Conceitos
- **Aval**: Ato cambiário que garante o pagamento de uma obrigação constante de título
- **Avalista**: Pessoa que assina o aval, garantindo o pagamento de uma obrigação
- **Avalizado**: Pessoa que é equiparada à avalista na cadeia cambial
- **Endosso**: Ato de assinar o título, com ou sem especificação do avalizado
- **Cadeia cambial**: Série de títulos e ações que se sucedem na posse de um bem ou direito
- **Simultâneo**: Aval simultâneo é quando duas pessoas avalizam o mesmo indivíduo, responsáveis solidariamente pela obrigação garantida
- **Sucessivo**: Aval sucessivo é quando um avalista avaliza outro avalista, não podendo ser acionado regressivamente pelo primeiro avalista

### Referências legais
- Art. 30 da LUG
- Art. 897 do Código Civil
- Art. 31 da LUG
- Art. 898, § 1º do Código Civil

### Dicas de prova
- Diferenciar entre aval e endosso
- Entender a cadeia cambial e seus componentes
- Conhecer as diferenças entre simultâneo e sucessivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.167 (1)", "page_number": 167, "discipline": "Direito Empresarial", "legal_refs": ["Art. 30 da LUG", "Art. 897 do Código Civil", "Art. 31 da LUG", "Art. 898, § 1º do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:29:51.205952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=167", "doc_key": "36d125366e0e70dcdfe488ad5a8fdab7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c198748bcf483c341569721f85299224192c7ffea50c55ff14f03c72f421c299'),
  ('cpiuris2025::f1dbc363f9717e6a2737aa92f80ba247', 'doutrina', 'cp_iuris', 'Direito Empresarial — Aval e Fiança', '## Aval e Fiança

Resumo objetivo: A avaliação de avalistas e fiançados, suas diferenças e regras.

### Conceitos
- **Aval**: Garantia pessoal para dívidas assumidas por alguém
- **Fiança**: Obrigação acessória que acompanha uma obrigação principal
- **Vício de forma**: Erro ou irregularidade no ato de formação da obrigação
- **Avalista**: Pessoa responsável pela dívida assumida pelo avalizado
- **Avalizado**: Pessoa que assume a dívida

### Referências legais
- Art. 32 da LUG
- Art. 899, § 2º, do Código Civil

### Jurisprudência
- Súmula 189 do STF

### Dicas de prova
- Diferenciar aval e fiança
- Entender a relação entre avalista e avalizado
- Conhecer o conceito de vício de forma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.167 (2)", "page_number": 167, "discipline": "Direito Empresarial", "legal_refs": ["Art. 32 da LUG", "Art. 899, § 2º, do Código Civil"], "jurisprudence": ["Súmula 189 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T04:30:26.472807+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=167", "doc_key": "f1dbc363f9717e6a2737aa92f80ba247"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '66538283eafd2ec2ff79af236f8271d9092945318db94f2962f2e7a8e6d5c9f4'),
  ('cpiuris2025::809171e794238edb70b9dc814010847d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Necessidade de outorga conjugal para aval e fiança', '## Necessidade de outorga conjugal para aval e fiança

A necessidade de outorga conjugal é exigida para a prestação de aval e fiança por pessoa casada, exceto no regime de separação convencional de bens.

### Conceitos
- **Outorga conjugal**: Consentimento do cônjuge não unido à prestação de garantia
- **Aval**: Garantia pessoal que assegura o pagamento de uma dívida
- **Fiança**: Garantia pessoal que assegura a realização de um compromisso
- **Responsabilidade solidária**: Responsabilidade conjunta do avalista e do avalizado
- **Responsabilidade subsidiária**: Responsabilidade do fiador que só é acionado após tentativa de execução contra o afiançado

### Referências legais
- Art. 1.647, III, do Código Civil
- Art. 32 da Lei de Processo Civil
- Art. 899 do Código Civil
- Art. 827 do Código Civil

### Jurisprudência
- Informativo 420 do STJ

### Dicas de prova
- Diferenciar entre a responsabilidade solidária e subsidiária
- Entender o significado da outorga conjugal em diferentes regimes matrimoniais
- Conhecer as implicações da prestação de garantia para os cônjuges casados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.168 (1)", "page_number": 168, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.647, III, do Código Civil", "Art. 32 da Lei de Processo Civil", "Art. 899 do Código Civil", "Art. 827 do Código Civil"], "jurisprudence": ["Informativo 420 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T04:31:07.613456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=168", "doc_key": "809171e794238edb70b9dc814010847d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b2cce6ae2821c6b3a16d94e80556193ecc00985b73f53fea300d2fc4ac43d6b4'),
  ('cpiuris2025::95c89c9bee51c867bc48932532e9542f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Aval em separação conjugal', '## Aval em separação conjugal

O art. 1.647 do CC/2002 exige autorização conjugal para o aval, mas apenas no regime de separação legal. Em separação convencional, os consortes têm interesse nos bens adquiridos onerosamente ao longo do casamento.

### Conceitos
- **Aval**: prestação de garantia para o crédito
- **Separação conjugal**: regime jurídico que não exige autorização conjugal para certas ações
- **Outorga conjugal**: autorização conjugal para o aval

### Referências legais
- Art. 1.647 do CC/2002

### Jurisprudência
- Súm. n.º 377-STF
- REsp 1.163.074-PB
- REsp 1633399/SP

### Dicas de prova
- Entenda a diferença entre separação conjugal e separação legal
- Conheça o conceito de outorga conjugal e sua exigibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.168 (2)", "page_number": 168, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.647 do CC/2002"], "jurisprudence": ["Súm. n.º 377-STF", "REsp 1.163.074-PB", "REsp 1633399/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T04:31:34.125911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=168", "doc_key": "95c89c9bee51c867bc48932532e9542f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0eaaa52a8af9dd2e5a1b42f6da53273c3d503a78b0e1f6a8866a5070b4aa879f'),
  ('cpiuris2025::3c56623c8b6e7a6c88b0c7138b05dc2a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Protesto em Títulos Cambiais', '## Protesto em Títulos Cambiais

O protesto é um ato formal que prova a inadimplência e o descumprimento de obrigação originada em títulos e outros documentos de dívida. É necessária para cobrar do coobrigado se o devedor principal não paga.

### Conceitos
- **Coobrigado**: Pessoa responsável por pagar um título cambial se o devedor principal não paga.
- **Protesto do título**: Ato formal que prova a inadimplência e o descumprimento de obrigação originada em títulos e outros documentos de dívida.
- **Endossante**: Pessoa responsável pela prestação do título cambial se o devedor principal não paga.
- **Cadeia de endossos**: Ordem cronológica em que os endossantes estão dispostos.

### Referências legais
- Art. 914 do Código Civil
- Art. 1º da Lei n.º 9.492/1997

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância do protesto em títulos cambiais e como ele afeta a relação entre o credor e os coobrigados.
- Conheça as diferenças entre endossante e coobrigado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.169 (1)", "page_number": 169, "discipline": "Direito Empresarial", "legal_refs": ["Art. 914 do Código Civil", "Art. 1º da Lei n.º 9.492/1997"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T04:32:20.084462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=169", "doc_key": "3c56623c8b6e7a6c88b0c7138b05dc2a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '04ea0c67e325e40ce2ab0505c1f3ebea90987d8b97d9ebbc3dfec602d90f74ae'),
  ('cpiuris2025::afa7d737cb028d6d201483b953d9338f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Protesto e Prescrição', '## Protesto e Prescrição

O protesto cambial interrompe a prescrição desde que feito no prazo e na forma da lei, de acordo com o art. 202, III do Código Civil.

### Conceitos
- **Prescrição**: Processo pelo qual um direito é considerado extinto por falta de ação ou reação do devedor.
- **Protesto Cambial**: Ação que visa notificar o devedor sobre a existência de uma dívida e exigir o pagamento.
- **Direito de Regresso**: O direito do credor de recuperar parte do valor da dívida se o devedor não pagar.
- **Devedor Direto**: O devedor principal de um título ou documento de crédito.
- **Prescrição Interrumpida**: A prescrição é interrompida quando o credor toma uma ação específica, como o protesto cambial.
- **Protesto Necessário**: O protesto é necessário para que o credor possa exigir o pagamento da dívida se o devedor principal for conhecido.
- **Devedor Indireto**: O devedor que não é o principal, mas que tem a obrigação de pagar a dívida.
- **Cancelamento do Protesto**: Ação que visa cancelar o protesto após o pagamento da dívida pelo devedor.

### Referências legais
- Art. 202, III do Código Civil

### Jurisprudência
- Súmula 153/STF
- REsp 694.766/RS
- REsp 1.339.436/SP

### Dicas de prova
- Entenda a diferença entre protesto necessário e desnecessário.
- Conheça o conceito de direito de regresso e como ele se relaciona com o protesto cambial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.169 (2)", "page_number": 169, "discipline": "Direito Empresarial", "legal_refs": ["Art. 202, III do Código Civil"], "jurisprudence": ["Súmula 153/STF", "REsp 694.766/RS", "REsp 1.339.436/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T04:33:07.876022+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=169", "doc_key": "afa7d737cb028d6d201483b953d9338f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ebf0c6f9ae6d356ac880902e78a20d695e2158d371952de3107b1769dc917a47'),
  ('cpiuris2025::a9a02a570c149144bcdbd7cb0275d444', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial e Letra de Câmbio', '## Propriedade Industrial e Letra de Câmbio

Resumo objetivo: A letra de câmbio é uma ordem de pagamento que se cria por meio do saque, vinculando o sacador ao pagamento. Os requisitos da letra de câmbio incluem expressão específica, ordem pura e simples de pagamento, nome do sacado, lugar do pagamento e data do saque.

### Conceitos
- **Saque**: Ato de criação do título que se dá por meio do saque
- **Sacador**: Pessoa que dá a ordem de pagamento
- **Sacado**: Pessoa a quem a ordem é dirigida
- **Tomador**: Pessoa beneficiária da ordem de pagamento
- **Lei Uniforme de Genebra (LUG)**: Legislação que regula as letras de câmbio e notas promissórias
- **Requisitos da letra de câmbio**: Expressão específica, ordem pura e simples de pagamento, nome do sacado, lugar do pagamento e data do saque

### Referências legais
- Art. 1º da LUG
- Art. 2º da LUG
- Súmula 548 do STJ
- Súmula 387 do STF
- Art. 891 do CC/2002

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegadinha ou distinção relevante para prova: entender a diferença entre sacador, sacado e tomador
- Requisitos da letra de câmbio são fundamentais para sua validade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.170", "page_number": 170, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1º da LUG", "Art. 2º da LUG", "Súmula 548 do STJ", "Súmula 387 do STF", "Art. 891 do CC/2002"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T04:33:51.673981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=170", "doc_key": "a9a02a570c149144bcdbd7cb0275d444"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8ab661f75b3ae99ee44c66b379d95df48065512c3a131be38648e0cefef35710'),
  ('cpiuris2025::ce4351d1d41b208b7115fd9d34068217', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial - Aceite e Letra de Câmbio', '## Propriedade Industrial - Aceite e Letra de Câmbio

O aceite é o ato pelo qual o sacado concorda com a letra de câmbio, tornando-se devedor principal. O aceite é facultativo, mas irretratável em caso de recusa.

### Conceitos
- **Aceite**: Ato pelo qual o sacado concorda com a letra de câmbio
- **Sacado**: Pessoa que recebe a letra de câmbio e pode exigir o pagamento
- **Sacador**: Pessoa que emite a letra de câmbio
- **Lei**: Regulamenta as consequências da recusa do aceite
- **Vencimento Antecipado**: Ocorre quando o sacado recusa o aceite

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre aceite limitativo e modificativo
- Importância da cláusula não aceitável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T04:34:32.882610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=171", "doc_key": "ce4351d1d41b208b7115fd9d34068217"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'def6095ed1e9e7486f32753deb82974dd9ab70e8f5967143ad51a59be676849a'),
  ('cpiuris2025::6c47115802597c44fadaa4403b320835', 'doutrina', 'cp_iuris', 'Direito Empresarial — Vencimento de Títulos e Juros Moratórios', '## Vencimento de Títulos e Juros Moratórios

O vencimento de um título depende do momento em que o título é aceito ou emitido, afetando a contagem dos juros moratórios. A inobservância desses prazos resulta na perda do direito de cobrança contra os coobrigados.

### Conceitos
- **Vencimento de Título**: O momento em que o título é considerado vencido
- **Aceite**: A ação pelo qual o sacado aceita o título
- **Emissão**: A data em que o título é emitido
- **Juros Moratórios**: Os juros cobrados após o vencimento do título

### Referências legais
- Art. 585, c/ R da Lei de Câmbio

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre aceite e emissão
- Identifique o termo inicial dos juros moratórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.171 (2)", "page_number": 171, "discipline": "Direito Empresarial", "legal_refs": ["Art. 585, c/ R da Lei de Câmbio"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T04:34:57.279990+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=171", "doc_key": "6c47115802597c44fadaa4403b320835"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5f6b9ec06801c963c28c5a5ada9a73837ef8422b37ffedf3201d29f8ae32018a'),
  ('cpiuris2025::b297396f11a8a15444479bc8fbc013b5', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial e Títulos de Crédito', '## Propriedade Industrial e Títulos de Crédito

Resumo do conteúdo sobre letras de câmbio e títulos de crédito, incluindo aceite, prazos e execução.

### Conceitos
- **Aceite**: Condição necessária para a validade de um título de crédito
- **Prazo de apresentação**: Prazo estabelecido para o aceite de um título de crédito
- **Prazo de vencimento**: Prazo estabelecido para o pagamento de um título de crédito
- **Protesto**: Ação tomada pelo sacador em caso de falta de aceite
- **Sacado**: Pessoa que não se vinculou ao título de crédito
- **Sacador**: Pessoa que ajuíza a execução do título de crédito
- **Coobrigado**: Pessoa que compartilha o crédito com o devedor principal
- **Avalista**: Pessoa que garante o pagamento do título de crédito

### Referências legais
- Art. 23 da LUG
- Art. 784, I e XII do CPC/2015

### Dicas de prova
- Entenda a distinção entre prazo de apresentação e prazo de vencimento
- Conheça as regras de protesto e execução de títulos de crédito
- Identifique os coobrigados e avalistas em um título de crédito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.172 (1)", "page_number": 172, "discipline": "Direito Empresarial", "legal_refs": ["Art. 23 da LUG", "Art. 784, I e XII do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:35:38.656638+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=172", "doc_key": "b297396f11a8a15444479bc8fbc013b5"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ead753d0d7d8d22743edb808c6c5ff38d6e78a4497bc3fbe7378d8a7327e6699'),
  ('cpiuris2025::6d204b99059b7c6532e78db777788739', 'doutrina', 'cp_iuris', 'Direito Empresarial — Nota Promissória', '## Nota Promissória

A nota promissória é uma promessa de pagamento que gera duas situações jurídicas: a do emitente, o beneficiário e o sacador. Os requisitos da nota promissória são definidos pelo art. 75 da LUG.

### Conceitos
- **Nota Promissória**: promessa de pagamento
- **Subscritor**: pessoa que assina a nota promissória
- **Sacador**: pessoa que saca a nota promissória
- **Beneficiário**: pessoa ao qual se obriga o pagamento
- **Condição**: limitação ou ressalva à promessa de pagamento

### Referências legais
- Art. 75 da LUG

### Dicas de prova
- Entenda a distinção entre subscritor e sacador
- Leia atentamente o art. 75 da LUG para identificar os requisitos da nota promissória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.172 (2)", "page_number": 172, "discipline": "Direito Empresarial", "legal_refs": ["Art. 75 da LUG"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:36:15.221007+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=172", "doc_key": "6d204b99059b7c6532e78db777788739"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '9a85b7f2e1021acedd0b381cb25f06838482e2bff0486dc8b53bb3267174a316'),
  ('cpiuris2025::d6a6fe85d7beb0f374b110fba52dbfa9', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial e Nota Promissória', '## Propriedade Industrial e Nota Promissória

A nota promissória é um título de crédito regido pela Lei n.º 7.357/1987, que pode ser emitida em qualquer situação sem causa pré-determinada. Se não for mencionada a data de vencimento, considera-se à vista. A prescrição intercorrente observará o mesmo prazo de prescrição da pretensão, observadas as causas de impedimento, suspensão e interrupção da prescrição.

### Conceitos
- **Nota Promissória**: título de crédito regido pela Lei n.º 7.357/1987
- **Prescrição Intercorrente**: observará o mesmo prazo de prescrição da pretensão, observadas as causas de impedimento, suspensão e interrupção da prescrição

### Referências legais
- Art. 206-A do CC/2002
- Súmula 504 do STJ
- Art. 921 da Lei n.º 13.105/2015

### Jurisprudência
- RE 123456
- Tema repetitivo

### Dicas de prova
- Distinção entre prescrição intercorrente e prescrição da pretensão
- Características do cheque como título de crédito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.173 (1)", "page_number": 173, "discipline": "Direito Empresarial", "legal_refs": ["Art. 206-A do CC/2002", "Súmula 504 do STJ", "Art. 921 da Lei n.º 13.105/2015"], "jurisprudence": ["RE 123456", "Tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-27T04:36:48.946234+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=173", "doc_key": "d6a6fe85d7beb0f374b110fba52dbfa9"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '87f6e96b639775ff2bc4d4c4ea3d3e5342cf1db4e55a71cfdfeac1aa3e26be12'),
  ('cpiuris2025::f10adbf3b6ec0305517349009ceb56a1', 'doutrina', 'cp_iuris', 'Direito Empresarial — Responsabilidade por danos morais e quebra da boa-fé', '## Responsabilidade por danos morais e quebra da boa-fé

A responsabilidade por danos morais é estabelecida quando há quebra da boa-fé em relação ao emitente, de acordo com a Súmula 370 do STJ.

### Conceitos
- **boa-fé**: Conduzimento honesto e justo em uma relação
- **danos morais**: Prejuízos causados à dignidade ou reputação de uma pessoa

### Referências legais
- Súmula 370 do STJ

### Dicas de prova
- Entenda a noção de boa-fé e seus impactos na responsabilidade por danos morais
- Conheça as modalidades de cheque previstas na Lei n.º 7.357/85', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.173 (2)", "page_number": 173, "discipline": "Direito Empresarial", "legal_refs": ["Súmula 370 do STJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:37:08.022923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=173", "doc_key": "f10adbf3b6ec0305517349009ceb56a1"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3786f02313b355f79d0d4a814a05c0927a536810cec58609d59f4de7a448b38d'),
  ('cpiuris2025::707201814cd4cd6df1e0f70a931c2dfb', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial - Cheque', '## Propriedade Industrial - Cheque

O cheque é um título vinculado que deve cumprir requisitos legais, como a denominação ''cheque'', ordem incondicional de pagar uma quantia determinada e assinatura do emitente.

### Conceitos
- **Título de crédito**: documento que representa um direito à recebimento de dinheiro
- **Vinculação**: relação entre o título e a pessoa física ou jurídica que o detém
- **Formalidade dos títulos de crédito**: necessidade de cumprir requisitos legais para que um documento seja considerado válido

### Referências legais
- Art. 1º da Lei do Cheque
- Art. 2º da Lei do Cheque

### Dicas de prova
- Entenda a noção de título vinculado e formalidade dos títulos de crédito
- Conheça os requisitos legais para que um cheque seja considerado válido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.174 (1)", "page_number": 174, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1º da Lei do Cheque", "Art. 2º da Lei do Cheque"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:37:47.247112+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=174", "doc_key": "707201814cd4cd6df1e0f70a931c2dfb"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '6fa84a78a8058ca7344057409a7f45534773d19c7fdad1c9b8b8d16cb1cab1cd'),
  ('cpiuris2025::4491d2dbe6836bdff04442927c537f3e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cheques e Endossos', '## Cheques e Endossos

O cheque é emitido no lugar indicado junto ao nome do emitente, sendo necessário endosso para valores acima de R$ 100,00.

### Conceitos
- **Cheque**: documento financeiro que autoriza o pagamento de uma determinada quantia
- **Endosso**: assinatura do detentor do cheque para permitir seu uso
- **Circulação de cheques**: movimentação de cheques entre pessoas físicas ou jurídicas

### Referências legais
- Art. 69 da Lei n.º 9069/95

### Dicas de prova
- Diferenciar entre cheque e endosso
- Conhecer as regras de circulação de cheques', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.174 (2)", "page_number": 174, "discipline": "Direito Empresarial", "legal_refs": ["Art. 69 da Lei n.º 9069/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:38:06.316676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=174", "doc_key": "4491d2dbe6836bdff04442927c537f3e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '49f4fb284202ad134d86b9df3927bcac48dee2ec9b7cba0e17e7000ba6083bfa'),
  ('cpiuris2025::399bf9f3ef3d3a71f0a2f468b7068a17', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial e Cheques', '## Propriedade Industrial e Cheques

O endosso em cheque é nulo como endosso, mas valido como quitação. O aval em preto ou branco tem efeitos diferentes. O prazo para apresentação do cheque varia de trinta dias para sessenta dias, dependendo da praça.

### Conceitos
- **Endosso**: Acordo entre o sacado e o instituição financeira para garantir a devolução do cheque
- **Aval em preto**: Avalização que indica quem é o avalizado
- **Aval em branco**: Avalização que não indica quem será o avalizado, considerando-se que será o emitente
- **Prazo de apresentação do cheque**: Trinta dias para prças da mesma cidade e sessenta dias para prças distintas
- **Cobrança do cheque**: O cheque é pago com a sua apresentação, já que se trata de uma ordem de pagamento à vista

### Referências legais
- Art. 645 do Código Civil
- Súmula 600 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre aval em preto e branco
- Prazo de apresentação do cheque: trinta dias para prças da mesma cidade, sessenta dias para prças distintas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.175 (1)", "page_number": 175, "discipline": "Direito Empresarial", "legal_refs": ["Art. 645 do Código Civil", "Súmula 600 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T04:38:42.428898+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=175", "doc_key": "399bf9f3ef3d3a71f0a2f468b7068a17"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a787102ae8f7e19a8d959994a0991c497f866cdd4899986669553ad1cd407bcb'),
  ('cpiuris2025::a4386c3a0cccf20ad3e55edcfdb4124b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Prazos para ações contra coobrigados em cheque prescrito', '## Prazos para ações contra coobrigados em cheque prescrito

Resumo objetivo: O direito de regresso contra o outro coobrigado surge após o pagamento do título. A ação executiva pode ser prescrita, mas também é cabível ação monitória dentro de dois anos. Além disso, a ação monitória tem prazo quinquenal para ajuizamento.

### Conceitos
- **coobrigado**: Pessoa que compartilha o ônus da dívida com outra pessoa
- **direito de regresso**: Direito do coobrigado que pode ser exercido contra o outro coobrigado após o pagamento do título
- **ação executiva**: Ação judicial para cobrar uma dívida
- **ação monitória**: Ação judicial para reparar a perda patrimonial causada por um ato ilícito

### Referências legais
- Art. 61 da Lei do Cheque

### Jurisprudência
- Súmula 299 do STJ
- Súmula 503 do STJ
- Súmula 531 do STJ

### Dicas de prova
- Entenda a diferença entre ação executiva e ação monitória
- Conheça o prazo para ajuizamento da ação monitória
- Identifique o direito de regresso contra o outro coobrigado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.175 (2)", "page_number": 175, "discipline": "Direito Empresarial", "legal_refs": ["Art. 61 da Lei do Cheque"], "jurisprudence": ["Súmula 299 do STJ", "Súmula 503 do STJ", "Súmula 531 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T04:39:23.688210+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=175", "doc_key": "a4386c3a0cccf20ad3e55edcfdb4124b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5d73c1178ec229c4cb64ec4bccc458d4740cc42f85318b8a1f6afa65834b2e06'),
  ('cpiuris2025::313fd2b72f490249bca385a3678b43c0', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial - Ação Monitória Fundada em Cheque Prescrito', '## Propriedade Industrial - Ação Monitória Fundada em Cheque Prescrito

A ação monitória fundada em cheque prescrito não exige menção ao negócio jurídico subjacente à emissão da cártula. Com a prescrição do título de crédito, a pretensão se baseia no próprio negócio subjacente, tornando inviável a propositura de ação de execução.

### Conceitos
- **Ação Monitória**: Procedimento destinado a proteger os direitos do autor
- **Cheque Prescrito**: Título de crédito que prescreveu sem ser pago
- **Negócio Jurídico Subjetivo**: O que é objeto da relação jurídica entre as partes
- **Prescrição do Título de Crédito**: Fim do prazo legal para a ação
- **Prova da Origem da Dívida**: Não exigida na ação monitória fundada em cheque prescrito

### Referências legais
- Art. 180 do Código de Processo Civil
- Súmula 531/STJ

### Jurisprudência
- RE 123456
- Informativo 658/STJ

### Dicas de prova
- Distinção entre ação monitória e ação de execução
- Entendimento da prescrição do título de crédito em ações monitórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.176 (1)", "page_number": 176, "discipline": "Direito Empresarial", "legal_refs": ["Art. 180 do Código de Processo Civil", "Súmula 531/STJ"], "jurisprudence": ["RE 123456", "Informativo 658/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T04:39:59.768271+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=176", "doc_key": "313fd2b72f490249bca385a3678b43c0"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ef77cb40e3c735cc69c9ff2fdf6aa782d8b631c9a64d13353be32894d8a004f2'),
  ('cpiuris2025::7087df25c47a3d6ef66b1e9400b1bb93', 'doutrina', 'cp_iuris', 'Direito Empresarial — Papel de curso forçado e pagamento por meio de cheque', '## Papel de curso forçado e pagamento por meio de cheque

O cheque não é um papel de curso forçado, significando que ninguém está obrigado a recebê-lo contra a sua vontade. O pagamento por meio de cheque tem efeito pro-solvendo, não somente pro-soluto.

### Conceitos
- **Papel de curso forçado**: Obrigação de receber algo contra a vontade
- **Pagamento pro-solvendo**: Efeito do cheque ser compensado, significando a obrigação está quitada
- **Pagamento pro-soluto**: Efeito do cheque ser pago, mas não necessariamente a obrigação estar quitada
- **Cheque sem fundos**: Situação em que o cheque não tem valor para compensar a obrigação

### Referências legais
- Art. 645 CC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre pro-solvendo e pro-soluto
- Conheça o conceito de cheque sem fundos
- Não confunda papel de curso forçado com pagamento por meio de cheque', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.176 (2)", "page_number": 176, "discipline": "Direito Empresarial", "legal_refs": ["Art. 645 CC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T04:40:26.212989+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=176", "doc_key": "7087df25c47a3d6ef66b1e9400b1bb93"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '241f137a1858c1f4ac1d6edcb46edb46f2c4f6e67b7f91d88638bfb733d9e8da'),
  ('cpiuris2025::c429dabb83e9534c4b4f25dcf2f1378a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial, Cheque e Duplicata', '## Propriedade Industrial, Cheque e Duplicata

O cheque sem fundos deve ser protestado no prazo de apresentação para preservar o direito contra os coobrigados. A emissão de cheque sem fundos pode caracterizar crime de fraude por meio do uso de cheque. A duplicata é um título causal que pode ser emitida apenas diante de uma compra e venda mercantil ou prestação de serviços.

### Conceitos
- **Cheque sem fundos**: Documento financeiro que não possui valor líquido
- **Protesto do cheque**: Ação necessária para preservar o direito contra os coobrigados
- **Coobrigado**: Pessoa responsável por pagar um título de crédito
- **Duplicata**: Título de crédito regido pela Lei n.º 5.474/1968
- **Nota promissória**: Título de crédito emitido pelo comprador
- **Cheque**: Documento financeiro que representa um débito

### Referências legais
- Art. 47, II, da Lei do Cheque
- Súmula do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Duplicata

### Dicas de prova
- Entenda a diferença entre nota promissória e cheque
- Conheça as regras para emitir uma duplicata', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.177 (1)", "page_number": 177, "discipline": "Direito Empresarial", "legal_refs": ["Art. 47, II, da Lei do Cheque", "Súmula do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Duplicata"], "confidence": 0.8, "extracted_at": "2026-05-27T04:41:14.266193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=177", "doc_key": "c429dabb83e9534c4b4f25dcf2f1378a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a43edade4b0100eebe920d86a6741756ee49810beadcfba598b873395208a4e0'),
  ('cpiuris2025::7eeba725618db4d76ea9ce24f96dec4d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Duplicata', '## Duplicata

A duplicata adquire abstração e autonomia após aceite e circulação, desvinculando-se do negócio jurídico subjacente e protegendo terceiros endossatários de boa-fé.

### Conceitos
- **Duplicata**: Título de crédito emitido junto à fatura
- **Abstração e autonomia**: Desvinculação da duplicata do negócio jurídico subjacente, protegendo terceiros endossatários de boa-fé

### Referências legais
- Art. 2º do Código de Comércio
- ...

### Jurisprudência
- STJ. 2ª Seção. EREsp 1.439.749-RS
- RE 123456

### Dicas de prova
- Entenda a noção de duplicata e sua autonomia
- Distinção entre duplicata e outros títulos de crédito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.177 (2)", "page_number": 177, "discipline": "Direito Empresarial", "legal_refs": ["Art. 2º do Código de Comércio", "..."], "jurisprudence": ["STJ. 2ª Seção. EREsp 1.439.749-RS", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T04:41:37.290571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=177", "doc_key": "7eeba725618db4d76ea9ce24f96dec4d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3355ae805b05d66af73129021e70243050abd7ecc81a04a339e68232359b1a41'),
  ('cpiuris2025::7ff926c23c6ae6bef4cd0e16db6e90f6', 'doutrina', 'cp_iuris', 'Direito Empresarial — Duplicata', '## Duplicata

A duplicata é um título de crédito que deve conter informações específicas sobre o vendedor, comprador, valor e prazo de pagamento.

### Conceitos
- **Duplicata**: Título de crédito emitido pelo vendedor para cobrar uma dívida
- **Fatura**: Unidade de medida do valor das prestações
- **Vencimento**: Prazo em que a dívida deve ser pago
- **Parcelamento**: Divisão do pagamento em várias prestações

### Referências legais
- Art. 2º da Lei das Duplicatas
- Informativo 660 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: emissão de duplicata

### Dicas de prova
- Entenda a importância da assinatura do emitente na duplicata
- Conheça as regras para o número de ordem das duplicatas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.178 (1)", "page_number": 178, "discipline": "Direito Empresarial", "legal_refs": ["Art. 2º da Lei das Duplicatas", "Informativo 660 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: emissão de duplicata"], "confidence": 0.8, "extracted_at": "2026-05-27T04:42:05.817680+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=178", "doc_key": "7ff926c23c6ae6bef4cd0e16db6e90f6"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c0f9bb81236816dabcca54592bda51617b33f27bc228bed90fbe120f55b2f182'),
  ('cpiuris2025::bc9ac4152caa89fea823e50f8b230f2c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Emissão de duplicata simulada e crimes relacionados', '## Emissão de duplicata simulada e crimes relacionados

O artigo 172 do Código Penal prevê o crime de emissão de duplicata simulada, que pode ser punida com detenção de 2 a 4 anos e multa. Além disso, o artigo também prevê a punição de falsificar ou adulterar a escrituração do Livro de Registro de Duplicatas.

### Conceitos
- **Duplicata simulada**: Documento que não corresponde à mercadoria vendida
- **Emissão de duplicata**: Atividade que envolve a emissão de documentos financeiros
- **Crime**: Ato ilegal que pode ser punido pela lei
- **Detenção**: Pena que envolve a privação da liberdade por um período determinado
- **Multa**: Sancionamento financeiro imposto ao infrator
- **Falsificação**: Atividade que envolve a criação de documentos falsos
- **Adulteração**: Atividade que envolve a alteração de documentos para fins ilícitos

### Referências legais
- Art. 172 do Código Penal
- Lei nº 5.474/1968

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegadinha: cada duplicata deve corresponder a uma fatura, mas esta pode abranger mais de uma nota fiscal parcial
- Distinção relevante: art. 172 do CP prevê crime em relação à emissão de duplicata simulada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.178 (2)", "page_number": 178, "discipline": "Direito Empresarial", "legal_refs": ["Art. 172 do Código Penal", "Lei nº 5.474/1968"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T04:42:52.051274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=178", "doc_key": "bc9ac4152caa89fea823e50f8b230f2c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '09de9a87f6c6fc52fde9c101b30f0673ce21557869cb95058c59541269825640'),
  ('cpiuris2025::252627f3522a1158e71d1e2137e230d8', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial e Duplicata', '## Propriedade Industrial e Duplicata

A duplicata é título obrigatório de aceite para o comprador, exceto em casos específicos como falta de recebimento da mercadoria ou avaria. O aceite pode ser ordinário, por comunicação ou por presunção.

### Conceitos
- **Aceite**: Obrigação do comprador de assinar a duplicata e devolver ao vendedor
- **Duplicata**: Título mercantil que exige o aceite do comprador
- **Falta de Aceite**: Motivo pelo qual a duplicata pode ser protestada
- **Protesto da Duplicata**: Ação do credor para exigir o pagamento e devolução do título

### Referências legais
- Art. 13, § 4º, da Lei das Duplicatas

### Jurisprudência
- Súmula 361 do STJ

### Dicas de prova
- Entenda a obrigação de aceite para o comprador em relação à duplicata
- Conheça as hipóteses que excepcionam a obrigatoriedade do aceite', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.179", "page_number": 179, "discipline": "Direito Empresarial", "legal_refs": ["Art. 13, § 4º, da Lei das Duplicatas"], "jurisprudence": ["Súmula 361 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T04:43:25.371431+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=179", "doc_key": "252627f3522a1158e71d1e2137e230d8"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a31d05eea8146400803b6cecf48226f4ecc667159bbb2abe53be57b7d7f55878'),
  ('cpiuris2025::49928b1fca6a9c3147e19cb664455a1b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Propriedade Industrial - Duplicata', '## Propriedade Industrial - Duplicata

A duplicata é um título executivo que pode ser utilizado para exigir o pagamento de uma dívida. Existem diferentes tipos de duplicatas, incluindo a aceite ordinário, aceite por comunicação e aceite por presunção. Para cada tipo, existem requisitos específicos que devem ser cumpridos.

### Conceitos
- **Duplicata**: Título executivo que exige o pagamento de uma dívida
- **Aceite Ordinário**: Duplicata com assinatura simples para fins de ajuizamento da execução
- **Aceite por Comunicação**: Duplicata que serve como título executivo com base na carta de aceite
- **Aceite por Presunção**: Duplicata que pode ser utilizada sem a necessidade de protesto cambial e entrega da mercadoria ou prestação de serviços
- **Protesto Cambial**: Necessário para a duplicata aceite por presunção
- **Entrega da Mercadoria ou Prestação de Serviços**: Requisito para a duplicata aceite por presunção
- **Recusa Justificada do Aceite**: Não é um requisito para a duplicata aceite por presunção

### Referências legais
- Art. 8º, parágrafo único, da Lei n.º 9.492/1997
- Art. 889, § 3º, do CC/2002
- Lei n.º 13.775/2018

### Jurisprudência
- REsp 250.568
- REsp 204.894

### Dicas de prova
- Diferenciar entre aceite ordinário, aceite por comunicação e aceite por presunção
- Entender os requisitos para a duplicata aceite por presunção
- Conhecer as exceções ao princípio da cartularidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.180 (1)", "page_number": 180, "discipline": "Direito Empresarial", "legal_refs": ["Art. 8º, parágrafo único, da Lei n.º 9.492/1997", "Art. 889, § 3º, do CC/2002", "Lei n.º 13.775/2018"], "jurisprudence": ["REsp 250.568", "REsp 204.894"], "confidence": 0.8, "extracted_at": "2026-05-27T04:44:17.189448+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=180", "doc_key": "49928b1fca6a9c3147e19cb664455a1b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '9ec5291d3c78b120cbe5185a0b66c5d70f78d1a946f307e5cc8b4d2a72a8395d'),
  ('cpiuris2025::40ddcb63bd8d42650189b782b37c7d45', 'doutrina', 'cp_iuris', 'Direito Empresarial — Título Executivo Extrajudicial', '## Título Executivo Extrajudicial

Descrição do processo de protesto e execução contra um devedor inadimplente após o vencimento de uma obrigação.

### Conceitos
- **Duplicata Virtual**: Documento eletrônico que contém as características de uma duplicata
- **Título Executivo Extrajudicial**: Título que autoriza a execução contra um devedor inadimplente
- **Protesto**: Atividade realizada pelo Tabelionato para anular o título executivo
- **Execução Extrajudicial**: Processo que visa cobrar uma obrigação sem a necessidade de um processo judicial

### Referências legais
- Art. 143 do Código de Processo Civil
- Súmula 134 da Súmula Técnica do STF

### Jurisprudência
- RE 123456/2019
- Tema repetitivo: Execução Extrajudicial

### Dicas de prova
- Entenda a diferença entre um boleto bancário e um título de crédito.
- Conheça o processo de protesto e suas implicações para o devedor inadimplente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.180 (2)", "page_number": 180, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143 do Código de Processo Civil", "Súmula 134 da Súmula Técnica do STF"], "jurisprudence": ["RE 123456/2019", "Tema repetitivo: Execução Extrajudicial"], "confidence": 0.8, "extracted_at": "2026-05-27T04:44:54.626616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=180", "doc_key": "40ddcb63bd8d42650189b782b37c7d45"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c82c93099d7bbb9f0593534c237396ecc07a3d16d1a94c0b49466673fde1aba1'),
  ('cpiuris2025::88c19f3531c0a0381c610a8109eda0a4', 'doutrina', 'cp_iuris', 'Direito Empresarial — Duplicata Virtual e Execução', '## Duplicata Virtual e Execução

A duplicata virtual é válida desde antes da Lei nº 13.775/2018, podendo ser protestada por mera indicação. A execução da duplicata prescreve em três anos contados da data de vencimento do título contra o devedor principal ou seu avalista.

### Conceitos
- **Duplicata Virtual**: Título de crédito emitido por meio magnético ou gravação eletrônica
- **Execução da Duplicata**: Ação que visa cobrar o valor do título de crédito
- **Prazo para Cobrança**: A ação de execução da duplicata prescreve em três anos contados da data de vencimento do título contra o devedor principal ou seu avalista
- **Duplicata Mercantil**: Título de crédito emitido por meio físico
- **Protesto por Indicação**: Ação que visa cobrar o valor do título de crédito sem a necessidade da exibição do título

### Referências legais
- Art. 8º, §1º, da Lei n.º 9.492/1997

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Duplicata Virtual e Execução

### Dicas de prova
- Entenda a diferença entre duplicata virtual e física
- Conheça o prazo para cobrança da duplicata e as exceções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.181", "page_number": 181, "discipline": "Direito Empresarial", "legal_refs": ["Art. 8º, §1º, da Lei n.º 9.492/1997"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Duplicata Virtual e Execução"], "confidence": 0.8, "extracted_at": "2026-05-27T04:45:31.754366+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=181", "doc_key": "88c19f3531c0a0381c610a8109eda0a4"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f03d844d1766d6f821119675e3f32b9f0c3bc21362d7ec900297a1476652eccd'),
  ('cpiuris2025::f5f30c192ffb0c6192cebc52044eb5ae', 'doutrina', 'cp_iuris', 'Direito Empresarial — Títulos de Crédito Impróprios', '## Títulos de Crédito Impróprios

Descreve as categorias e características dos títulos de crédito impróprios, incluindo título de legitimação, título representativo, título de financiamento e título de investimentos.

### Conceitos
- **Título de Legitimação**: Documento que confere direito a uma prestação de serviço ou acesso a um prêmio
- **Título Representativo**: Instrumento que representa a titularidade de mercadorias custodiadas
- **Mercadoria Custodiada**: Mercadoria que está sob a custódia de uma pessoa, mas que pertence a outra pessoa
- **Conhecimento de Depósito**: Título que atesta a existência e depósito de mercadorias em armazém geral
- **Warrant**: Título que serve para constituir penhor sobre uma mercadoria

### Referências legais
- Art. 13 da Lei X
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo de Títulos de Crédito Impróprios

### Dicas de prova
- Entenda a diferença entre título de legitimação e título representativo
- Conheça as características do conhecimento de depósito e warrant', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.182 (1)", "page_number": 182, "discipline": "Direito Empresarial", "legal_refs": ["Art. 13 da Lei X", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo de Títulos de Crédito Impróprios"], "confidence": 0.8, "extracted_at": "2026-05-27T04:46:07.150552+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=182", "doc_key": "f5f30c192ffb0c6192cebc52044eb5ae"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f9cc617054e9fe2be5746b4a33068c67fa51bd1b64102798e05d4f9319a0dd34'),
  ('cpiuris2025::6cc8e5fdd707800ed6c947cd8b923aa7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Exceções no Direito de Garantia', '## Exceções no Direito de Garantia

Resumo objetivo: Exceções para liberação da mercadoria em prol do titular, caso de execução da garantia após protesto do warrant.

### Conceitos
- **Depósito**: Conhecimento de depósito é a garantia que o vendedor fornece ao comprador sobre a mercadoria.
- **Warrant**: O warrant é uma garantia adicional fornecida pelo vendedor para proteger o comprador em caso de não pagamento.
- **Execução da Garantia**: A execução da garantia ocorre quando o comprador não paga a mercadoria e o vendedor procura recuperar seu direito.
- **Protesto do Warrant**: O protesto do warrant é o ato pelo qual o vendedor notifica o comprador sobre a execução da garantia.
- **Retirada da Mercadoria**: A retirada da mercadoria ocorre quando o comprador não paga a mercadoria e o vendedor retira a mercadoria do estoque.

### Referências legais
- Art. 231, § 3º, CC/2002

### Jurisprudência
- RE 123456
- Súmula 234 da SBDI-1

### Dicas de prova
- Perguntas sobre exceções no direito de garantia podem ser resolvidas com base na análise do depósito e do warrant.
- Lembre-se de que a execução da garantia após protesto do warrant é um caso específico que pode afetar a liberação da mercadoria.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.182 (2)", "page_number": 182, "discipline": "Direito Empresarial", "legal_refs": ["Art. 231, § 3º, CC/2002"], "jurisprudence": ["RE 123456", "Súmula 234 da SBDI-1"], "confidence": 0.8, "extracted_at": "2026-05-27T04:46:51.289628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=182", "doc_key": "6cc8e5fdd707800ed6c947cd8b923aa7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ce2e2ae8886365a5583c361b1e8e6babc40db81bde5d3f6e7a44146528b11754'),
  ('cpiuris2025::21d7f64c7dd5bd70a12c45177397be04', 'doutrina', 'cp_iuris', 'Direito Empresarial — Títulos de Financiamento', '## Títulos de Financiamento

Descreve os diferentes tipos de títulos de financiamento e as diferenças entre eles, incluindo cédulas e notas de crédito.

### Conceitos
- **Cédula de Crédito**: Instrumento que representa créditos decorrentes de um financiamento aberto por instituições financeiras, com garantia real
- **Nota de Crédito**: Instrumento que representa créditos decorrentes de um financiamento aberto por instituições financeiras, sem garantia real
- **Privilégio Especial**: Direito especial que protege os credores do título de financiamento perante o mercado
- **Créditos Quirografários**: Créditos não garantidos, equiparados aos créditos de privilégio especial após a reforma da Lei nº 14.112/20

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre cédulas e notas de crédito
- Entender o conceito de privilégio especial e seus efeitos
- Conhecer as exceções nos segmentos imobiliário e bancário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.183 (1)", "page_number": 183, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:47:24.762478+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=183", "doc_key": "21d7f64c7dd5bd70a12c45177397be04"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '207a3eebe2841369f090980467d01b63594226f1c73c6a360e88657ecef29340'),
  ('cpiuris2025::76706b71b1c66345dbbeb0a42223efe8', 'doutrina', 'cp_iuris', 'Direito Empresarial — Títulos de Investimento', '## Títulos de Investimento

Resumo objetivo: Títulos de investimento são instrumentos que captam recursos pelo emitente, incluindo LCIs e letras de arrendamento mercantil. A Lei nº 14.937/24 instituiu a Letra de Crédito do Desenvolvimento (LCD), considerada título de crédito nominativa.

### Conceitos
- **Título de Investimento**: Instrumento que se destina à captação de recursos pelo emitente
- **Letras de Crédito Imobiliário (LCI)**: Tipo de título de investimento
- **Lei nº 14.937/24**: Lei que instituiu a Letra de Crédito do Desenvolvimento (LCD)
- **Título de Crédito Nominativa**: Tipo de título de crédito
- **Transferível**: Característica do título de investimento
- **Livre Circulação**: Característica do título de investimento

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre LCIs e letras de arrendamento mercantil
- Conheça as características da Letra de Crédito do Desenvolvimento (LCD)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.183 (2)", "page_number": 183, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:47:53.074830+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=183", "doc_key": "76706b71b1c66345dbbeb0a42223efe8"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '27a353df9ca76fffadf3723b07d3611ce6799968304bcf9d818fb45958fe06d4'),
  ('cpiuris2025::a68bfba4fb95de3934c4f6a000684722', 'doutrina', 'cp_iuris', 'Direito Empresarial — Lei de Falências e Recuperação', '## Lei de Falências e Recuperação

A Lei n.º 11.101/2005 trouxe inovações significativas em relação ao Decreto-Lei n.º 7.661/45, incluindo a substituição da concordata pela recuperação, aumento do prazo de contestação e exigência de impontualidade injustificada superior a 40 salários-mínimos.

### Conceitos
- **Concordata**: Figura revogada que permitia ao comerciante pedir concordata em crise
- **Recuperação**: Nova figura que substituiu a concordata, permitindo ao comerciante recuperar a empresa de forma judicial ou extrajudicial
- **Prazo de contestação**: Aumentou de 24 horas para 10 dias
- **Impontualidade injustificada**: Exigência de ser superior a 40 salários-mínimos
- **Participação do Ministério Público**: Reduzida
- **Administrador judicial**: Mudanças nas regras para definir quem pode ser administrador judicial
- **Ordem de classificação dos créditos**: Créditos tributários estão em terceiro lugar, seguidos por créditos com garantia real e trabalhistas limitados a 150 salários-mínimos
- **Ação revocatória**: Ação que os credores e o Ministério Público podem propor para trazer mais bens para a massa falida

### Referências legais
- Art. 15 da Lei n.º 11.101/2005
- Súmula 456 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Recuperação Judicial

### Dicas de prova
- Entenda a substituição da concordata pela recuperação
- Conheça as mudanças no prazo de contestação e na exigência de impontualidade injustificada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.185", "page_number": 185, "discipline": "Direito Empresarial", "legal_refs": ["Art. 15 da Lei n.º 11.101/2005", "Súmula 456 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Recuperação Judicial"], "confidence": 0.8, "extracted_at": "2026-05-27T04:48:58.430462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=185", "doc_key": "a68bfba4fb95de3934c4f6a000684722"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b385efd400ebefd85a4c92881ddd89218302699478b5534141c9583fd6e682bf'),
  ('cpiuris2025::5ea77d0d9daa764e2dad72eb98488ad7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Incidência Subjetiva da Lei Nº 11.101/2005', '## Incidência Subjetiva da Lei Nº 11.101/2005

A Lei de Falência e Recuperação de Empresas (LFRE) não se aplica a devedores civis, que se submetem às regras da execução contra devedores insolventes previstas no Código de Processo Civil. As sociedades cooperativas não podem requerer recuperação nem ter sua falência requerida.

### Conceitos
- **Devedor**: Pessoa física ou jurídica que contrai dívida
- **Empresário**: Pessoa física ou jurídica que exerce atividade empresarial
- **Sociedade Empresária**: Pessoa jurídica que exerce atividade empresarial
- **Cooperativa**: Sociedade simples, independentemente do seu objeto social

### Referências legais
- Art. 1º da Lei Nº 11.101/2005
- Código de Processo Civil de 1973 (arts. 748 a 786-A)
- Lei n.º 5.764/71

### Jurisprudência
- ADIs 3424 e 3934
- Súmula N STF

### Dicas de prova
- Entenda a noção de ''empresário'' e sua relação com a Lei de Falência e Recuperação de Empresas
- Conheça as exceções para a aplicação da LFRE, como a sociedade cooperativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.186 (1)", "page_number": 186, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1º da Lei Nº 11.101/2005", "Código de Processo Civil de 1973 (arts. 748 a 786-A)", "Lei n.º 5.764/71"], "jurisprudence": ["ADIs 3424 e 3934", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T04:49:33.689171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=186", "doc_key": "5ea77d0d9daa764e2dad72eb98488ad7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1170fd4108442f41020d4469477026b4222960eeadac53a5cadac64ee91abf31'),
  ('cpiuris2025::fbcf2005d443817290054c7784f12494', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falência e Recuperação Judicial', '## Falência e Recuperação Judicial

A falência pode ser requerida, mas os credores não empresários podem pleitear a falência de empresas que explorem atividade econômica. A Constituição Federal estabelece que as empresas públicas e sociedades de economia mista devem ser disciplinadas pelas mesmas regras das empresas privadas, mas a Lei n.º 13.303/2016 não disciplina aspectos falimentares.

### Conceitos
- **Falência**: processo que visa dissolver a empresa
- **Recuperação Judicial**: procedimento que visa evitar a falência
- **Credores não empresários**: partes que não são empresas privadas
- **Empresas públicas**: empresas controladas pelo Estado
- **Sociedades de economia mista**: empresas que combinam características de empresas privadas e públicas

### Referências legais
- Art. 173, § 1º, II, da CF/88
- Art. 2º, I, da LFRE

### Dicas de prova
- Entenda a diferença entre falência e recuperação judicial
- Conheça as regras para a aplicação da Lei n.º 13.303/2016', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.186 (2)", "page_number": 186, "discipline": "Direito Empresarial", "legal_refs": ["Art. 173, § 1º, II, da CF/88", "Art. 2º, I, da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:50:02.658741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=186", "doc_key": "fbcf2005d443817290054c7784f12494"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '630b779041f0193f85b97578ee8d1ab252c235d1623ef79e803cabe8ba044180'),
  ('cpiuris2025::8f27eb00ef65c74de9ba99b632df3c8c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Interpretação da Lei Federal de Recuperação de Empresas (LFRE) em relação às empresas públicas e sociedades de economia mista', '## Interpretação da Lei Federal de Recuperação de Empresas (LFRE) em relação às empresas públicas e sociedades de economia mista

A LFRE não se aplica às empresas públicas e sociedades de economia mista, mas pode ser aplicada se forem exploradoras de atividade econômica. As entidades citadas no artigo 2º, inciso II, estão excluídas da abrangência da LFRE.

### Conceitos
- **Interpretação literal**: A interpretação mais rígida da lei, que considera que a LFRE não se aplica às empresas públicas e sociedades de economia mista.
- **Interpretação à luz da Constituição**: A interpretação que considera que o artigo 173 da Constituição Federal é a base para a aplicação da LFRE.
- **Interpretação conforme à Constituição**: A interpretação que considera que a LFRE pode ser aplicada às empresas públicas e sociedades de economia mista, desde que forem exploradoras de atividade econômica.

### Referências legais
- Art. 173 da Constituição Federal
- Art. 2º, inciso I, da LFRE

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Recomenda-se a aplicação literal da lei nas provas de concurso.
- Se cair em provas de concurso a redação literal do art. 2º, deve-se marcar como correta a alternativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.187 (1)", "page_number": 187, "discipline": "Direito Empresarial", "legal_refs": ["Art. 173 da Constituição Federal", "Art. 2º, inciso I, da LFRE"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T04:50:50.780094+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=187", "doc_key": "8f27eb00ef65c74de9ba99b632df3c8c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3044f37c0fa103376037e322f0cb0cc6d3b0e062528967295abf332fba80ef71'),
  ('cpiuris2025::caf18de112967dffda114bf2e462e3a4', 'doutrina', 'cp_iuris', 'Direito Empresarial — Foro Competente', '## Foro Competente

O artigo 3º da LFRE estabelece que o juízo competente para homologar plano de recuperação extrajudicial ou deferir a recuperação judicial é o local do principal estabelecimento do devedor, considerando-se o aspecto econômico.

### Conceitos
- **Foro Competente**: A competência para homologar plano de recuperação extrajudicial ou deferir a recuperação judicial
- **Principal Estabelecimento**: O local onde partem as decisões empresariais, considerando-se o aspecto econômico
- **Sede da Empresa**: Não necessariamente o local do registro público

### Referências legais
- Art. 3º da LFRE

### Jurisprudência
- Enunciado 466 das Jornadas de Direito Civil do CJF

### Dicas de prova
- Entenda a distinção entre principal estabelecimento e sede da empresa
- Considere o aspecto econômico ao determinar a competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.187 (2)", "page_number": 187, "discipline": "Direito Empresarial", "legal_refs": ["Art. 3º da LFRE"], "jurisprudence": ["Enunciado 466 das Jornadas de Direito Civil do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T04:51:15.427693+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=187", "doc_key": "caf18de112967dffda114bf2e462e3a4"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5e91a2593f43e223957a859da1c51f898c63a676c85083cc12fb5228fbe0d743'),
  ('cpiuris2025::c411a712598dc29df332ee8e760456e3', 'doutrina', 'cp_iuris', 'Direito Empresarial — Competência e Participação do Ministério Público em Processos de Recuperação Judicial e Falência', '## Competência e Participação do Ministério Público em Processos de Recuperação Judicial e Falência

O artigo 4º da LFRE estabelece a participação obrigatória do MP nos processos de recuperação judicial e falência, mas foi vetado por considerar que poderia acarretar nulidade e atrasos. No entanto, o entendimento dominante é que o MP só participa obrigatoriamente em casos expressamente previstos pela lei.

### Conceitos
- **Competência**: A capacidade do juiz de processar um caso
- **Participação do Ministério Público**: O papel do MP na recuperação judicial e falência
- **Vetado**: O processo em que uma proposta é cancelada ou não aprovada
- **Lei de Falências e Recuperações**: A legislação que regula as falências e recuperações judiciais
- **Juiz**: O magistrado responsável por processar um caso
- **Processo**: O procedimento jurídico para resolver um conflito
- **Nulidade**: A invalidade de uma ação ou decisão

### Referências legais
- Art. 4º da LFRE

### Jurisprudência
- Súmula 480 do STJ

### Dicas de prova
- Entenda a competência e participação do MP em processos de recuperação judicial e falência
- Conheça o conceito de vetado e sua aplicação na legislação
- Aprenda com as jurisprudências do STJ sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.188 (1)", "page_number": 188, "discipline": "Direito Empresarial", "legal_refs": ["Art. 4º da LFRE"], "jurisprudence": ["Súmula 480 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T04:51:55.083819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=188", "doc_key": "c411a712598dc29df332ee8e760456e3"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1ce5903e482c99b112941d01404b2a548e1db02a50c8b61cbe21c30c3f95f61b'),
  ('cpiuris2025::fc583d095a77024a1faf3af45594786e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Intervenção do Ministério Público em ações falimentares', '## Intervenção do Ministério Público em ações falimentares

A intervenção do Ministério Público em ações falimentares foi alterada pela Lei n.º 11.101/2005, ficando restrita às hipóteses expressamente previstas em lei.

### Conceitos
- **Intervenção do Ministério Público**: Ação do Ministério Público em ações falimentares
- **Lei n.º 11.101/2005**: Lei que alterou as regras de intervenção do Ministério Público em ações falimentares
- **Lei n.º 14.112/2020**: Lei que fez significativas alterações na legislação sobre intervenção do Ministério Público em ações falimentares
- **Fase pré-falimentar**: Fase inicial da ação falimentar
- **Ações conexas**: Ações relacionadas à ação falimentar

### Referências legais
- Art. 8º da Lei n.º 11.101/2005

### Jurisprudência
- REsp 1.230.431/SP

### Dicas de prova
- Entenda a alteração na intervenção do Ministério Público em ações falimentares
- Conheça as hipóteses expressamente previstas em lei para a atuação do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.188 (2)", "page_number": 188, "discipline": "Direito Empresarial", "legal_refs": ["Art. 8º da Lei n.º 11.101/2005"], "jurisprudence": ["REsp 1.230.431/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T04:52:37.660589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=188", "doc_key": "fc583d095a77024a1faf3af45594786e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '621e6b23eb7e81abfe4232a3021a371beae06f5648f60c7bd9bfbc146763defb'),
  ('cpiuris2025::33cf7d93753f51ff80672ddb1dd78ebe', 'doutrina', 'cp_iuris', 'Direito Empresarial — Reclamações e Recuperação Judicial em Falências', '## Reclamações e Recuperação Judicial em Falências

Resumo do direito de reclamar e recuperação judicial em falências, incluindo os direitos dos credores e da empresa.

### Conceitos
- **Reclamação**: Ação apresentada pelos credores para reavaliar ou alterar a decisão de recuperação judicial.
- **Recuperação Judicial**: Procedimento jurídico que visa liquidar os ativos da empresa e pagar as dívidas aos credores.
- **Falência**: Situação em que a empresa não tem mais recursos para pagar suas dívidas.

### Referências legais
- Art. 19, Código de Processo Civil
- Art. 30, § 2º, Código de Processo Civil
- Art. 52, V, Código de Processo Civil
- Art. 58, § 3º, Código de Processo Civil
- Art. 99, XIII, Código de Processo Civil
- Art. 22, § 4º, Código de Processo Civil
- Art. 51-A, § 6º, Código de Processo Civil
- Art. 45-A, § 4º, Código de Processo Civil
- Art. 114-A, Código de Processo Civil
- Art. 142, § 7º, Código de Processo Civil
- Art. 143, Código de Processo Civil
- Art. 154, § 3º, Código de Processo Civil
- Art. 167-A, § 5º, Código de Processo Civil

### Jurisprudência
- RE 123456
- Tema repetitivo da Recuperação Judicial em Falências

### Dicas de prova
- Entenda a diferença entre reclamação e recuperação judicial.
- Conheça os direitos dos credores e da empresa em falência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.189", "page_number": 189, "discipline": "Direito Empresarial", "legal_refs": ["Art. 19, Código de Processo Civil", "Art. 30, § 2º, Código de Processo Civil", "Art. 52, V, Código de Processo Civil", "Art. 58, § 3º, Código de Processo Civil", "Art. 99, XIII, Código de Processo Civil", "Art. 22, § 4º, Código de Processo Civil", "Art. 51-A, § 6º, Código de Processo Civil", "Art. 45-A, § 4º, Código de Processo Civil", "Art. 114-A, Código de Processo Civil", "Art. 142, § 7º, Código de Processo Civil", "Art. 143, Código de Processo Civil", "Art. 154, § 3º, Código de Processo Civil", "Art. 167-A, § 5º, Código de Processo Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo da Recuperação Judicial em Falências"], "confidence": 0.8, "extracted_at": "2026-05-27T04:53:25.943753+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=189", "doc_key": "33cf7d93753f51ff80672ddb1dd78ebe"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8998930ea8d074d09477aadea2dff343ea283d63f1cad3b030fba06236853958'),
  ('cpiuris2025::483dce9323e09f26e4f792cb313108d2', 'doutrina', 'cp_iuris', 'Direito Empresarial — Prazos processuais e Lei de Falências', '## Prazos processuais e Lei de Falências

A Lei de Falências (LFRE) estabelece prazos que devem ser contados em dias corridos, com exceção do stay period, que possui natureza material. Com a Reforma da LFRE, todos os prazos devem ser contados em dias corridos.

### Conceitos
- **Prazo processual**: Prazo estabelecido para o cumprimento de uma obrigação ou para a realização de um ato processual
- **Dias corridos**: Unidade de tempo utilizado para contar prazos, que inclui todos os dias do mês, incluindo fins de semana e feriados
- **Stay period**: Prazo durante o qual as ações processuais são suspensas, geralmente concedido em casos de falências ou recuperação

### Referências legais
- Art. 6º, § 4º, da Lei nº 11.101/05
- Art. 189, §1º, I, da Lei nº 11.101/05
- Lei nº 14.112/20

### Jurisprudência
- REsp 1.698.283-GO
- Súmula do STJ sobre o cabimento de Agravo de Instrumento

### Dicas de prova
- Entenda a diferença entre prazos processuais e dias corridos
- Conheça a natureza do stay period e como ele é contado em dias úteis
- Aprenda a aplicar a Lei de Falências e o novo CPC para resolver problemas de prazos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direito Empresarial", "legal_refs": ["Art. 6º, § 4º, da Lei nº 11.101/05", "Art. 189, §1º, I, da Lei nº 11.101/05", "Lei nº 14.112/20"], "jurisprudence": ["REsp 1.698.283-GO", "Súmula do STJ sobre o cabimento de Agravo de Instrumento"], "confidence": 0.8, "extracted_at": "2026-05-27T04:54:06.261302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=190", "doc_key": "483dce9323e09f26e4f792cb313108d2"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '829da4e50e0aa624c4466cfb1b1c2d855c3e9dfbeb0ed1fc1b6a46f814a348d9'),
  ('cpiuris2025::a6fd6203d7c560f12a99954f43f42d61', 'doutrina', 'cp_iuris', 'Direito Empresarial — Agravo de Instrumento em Processos Falimentares e Recuperacionais', '## Agravo de Instrumento em Processos Falimentares e Recuperacionais

O agravo de instrumento é admitido nos processos falimentares e recuperacionais com base na teleologia do art. 1.015, que prevê o recurso contra decisões proferidas em processos executivos.

### Conceitos
- **Agravo de Instrumento**: Recurso que pode ser apresentado contra decisões proferidas em processos executivos
- **Processo Falimentar**: Processo que visa a falência de uma empresa ou indivíduo
- **Recuperação**: Processo que visa a recuperação financeira de uma empresa ou indivíduo
- **Execução**: Processo que visa a execução de um crédito
- **CPC**: Código de Processo Civil

### Referências legais
- Art. 1.015, parágrafo único do CPC
- Art. 189, §1º, II da Lei nº 11.101/05

### Jurisprudência
- RE 123456
- Enunciado 69 das Jornadas de Direito Processual Civil do CJF

### Dicas de prova
- Entenda a teleologia do art. 1.015 e como ela se aplica aos processos falimentares e recuperacionais
- Conheça as hipóteses em que o agravo de instrumento não é permitido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.015, parágrafo único do CPC", "Art. 189, §1º, II da Lei nº 11.101/05"], "jurisprudence": ["RE 123456", "Enunciado 69 das Jornadas de Direito Processual Civil do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T04:54:49.644366+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=190", "doc_key": "a6fd6203d7c560f12a99954f43f42d61"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c046c54890d4bb65448d2e07ca1560bd5520273da58474a88079020e40a0d2e6'),
  ('cpiuris2025::cc3a8e2bc527163926f583a7b0558433', 'doutrina', 'cp_iuris', 'Direito Empresarial — Administrador Judicial e Remuneração', '## Administrador Judicial e Remuneração

O art. 21 da LFRE estabelece que o administrador judicial deve ser um profissional idôneo, preferencialmente advogado, economista, administrador de empresas ou contador. A remuneração do administrador judicial é fixada pelo juiz, considerando a capacidade de pagamento do devedor e os valores praticados no mercado.

### Conceitos
- **Administrador Judicial**: Pessoa responsável pela gestão das massas falidas ou em recuperação judicial
- **Remuneração**: Valor pago ao administrador judicial por seu trabalho
- **LFRE**: Lei de Falências e Recuperações Judiciais
- **Súmula do STJ**: Referência a decisão do Superior Tribunal de Justiça

### Referências legais
- Art. 21 da LFRE
- Art. 24 da LFRE
- Art. 70-A da Lei n.º 14.112/2020

### Jurisprudência
- STJ. REsp 1.487.042-PR
- Súmula do STJ

### Dicas de prova
- Entenda a definição de administrador judicial e sua remuneração
- Conheça as exceções para a redução da remuneração do administrador judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.191 (1)", "page_number": 191, "discipline": "Direito Empresarial", "legal_refs": ["Art. 21 da LFRE", "Art. 24 da LFRE", "Art. 70-A da Lei n.º 14.112/2020"], "jurisprudence": ["STJ. REsp 1.487.042-PR", "Súmula do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T04:55:22.353048+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=191", "doc_key": "cc3a8e2bc527163926f583a7b0558433"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '87a3f3b598da31c545f75ba2653e790e87bda33bd23fd0dddc360d29f5d09e93'),
  ('cpiuris2025::a2d1168ed86be2bfb05495a1012b77e8', 'doutrina', 'cp_iuris', 'Direito Empresarial — Administração Judicial na Falência e Recuperação Judicial', '## Administração Judicial na Falência e Recuperação Judicial

O administrador judicial tem o dever de estimular a conciliação, mediação e outros métodos alternativos de solução de conflitos relacionados à recuperação judicial e à falência.

### Conceitos
- **Conciliação**: Método de resolução de conflitos fora do processo judicial
- **Mediação**: Método de resolução de conflitos com a ajuda de um terceiro neutro
- **Administração Judicial**: Função exercida pelo juiz ou administrador judicial em um processo

### Referências legais
- Art. 22 da Lei nº 14.112/2020
- Súmula 1.700.700-SP do REsp

### Jurisprudência
- REsp 1.700.700-SP

### Dicas de prova
- Entenda a importância da conciliação e mediação na administração judicial
- Conheça os deveres do administrador judicial em relação à recuperação judicial e falência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.191 (2)", "page_number": 191, "discipline": "Direito Empresarial", "legal_refs": ["Art. 22 da Lei nº 14.112/2020", "Súmula 1.700.700-SP do REsp"], "jurisprudence": ["REsp 1.700.700-SP"], "confidence": 0.8, "extracted_at": "2026-05-27T04:55:49.048067+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=191", "doc_key": "a2d1168ed86be2bfb05495a1012b77e8"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a2dbd21c8f7cbe1c22888114d887356ffeffaa3247f360e21f3b328be3b44e70'),
  ('cpiuris2025::c61e086b423730059307d2c787d05d39', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Judicial e Destituição do Administrador Judicial', '## Recuperação Judicial e Destituição do Administrador Judicial

A recuperação judicial é um instrumento que visa superar a situação de crise do devedor, preservando a atividade empresarial e empregos. O administrador judicial pode deixar suas funções por substituição ou destituição, com caráter sancionatório na última.

### Conceitos
- **Recuperação Judicial**: Instrumento que visa superar a situação de crise do devedor
- **Destituição do Administrador Judicial**: Caráter sancionatório da saída do administrador judicial
- **Substituição do Administrador Judicial**: Não há caráter sancionatório na saída do administrador judicial

### Referências legais
- Art. 22, III, j; Art. 23, parágrafo único; Art. 24, § 3º; Art. 31

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre substituição e destituição do administrador judicial
- Conheça as hipóteses de destituição do administrador judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.192 (1)", "page_number": 192, "discipline": "Direito Empresarial", "legal_refs": ["Art. 22, III, j; Art. 23, parágrafo único; Art. 24, § 3º; Art. 31"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T04:56:31.017097+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=192", "doc_key": "c61e086b423730059307d2c787d05d39"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '987d714bbc103335ba7ffae37b7b2d49c183a78c34deb6eada6d43bc2bd26e91'),
  ('cpiuris2025::a45d180b55902ca884355281d204237f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Concordata e Recuperação Judicial', '## Concordata e Recuperação Judicial

Resumo objetivo: A concordata permite ao devedor pedir parcelamento ou abatimento da dívida, enquanto a recuperação judicial envolve um plano apresentado pelo devedor para aprovação dos credores.

### Conceitos
- **Concordata**: Processo que permite ao devedor pedir parcelamento ou abatimento da dívida
- **Recuperação Judicial**: Processo em que o devedor apresenta um plano para aprovação dos credores
- **Prazos e condições especiais**: Meio de recuperação judicial que inclui concessão de prazos e condições especiais para pagamento das obrigações vencidas ou vincendas

### Referências legais
- Art. 50 da Lei n.º 11.101/2005

### Dicas de prova
- Entenda a diferença entre concordata e recuperação judicial
- Conheça os meios de recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.192 (2)", "page_number": 192, "discipline": "Direito Empresarial", "legal_refs": ["Art. 50 da Lei n.º 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:56:56.129265+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=192", "doc_key": "a45d180b55902ca884355281d204237f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f092ffa46f62eec53112771db4d6abce2e88067166b2e26fbd3e1487018dfda6'),
  ('cpiuris2025::fd83162d3d492fba1d41564ac15c0a43', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Judicial e Falência', '## Recuperação Judicial e Falência

Resumo do rol de ações que podem ser realizadas em recuperação judicial ou falência, incluindo novidades introduzidas pela Lei n.º 14.112/2020.

### Conceitos
- **Recuperação Judicial**: Processo pelo qual o devedor apresenta um plano de recuperação para pagar suas dívidas
- **Falência**: Condição em que o devedor não tem mais recursos para pagar suas dívidas
- **Cisão, incorporação, fusão ou transformação de sociedade**: Ações que podem ser realizadas para alterar a estrutura da empresa
- **Substituição total ou parcial dos administradores do devedor**: Mudança nos órgãos administrativos da empresa
- **Concessão de direito de eleição em separado de administradores**: Direito dos credores de escolher os administradores da empresa
- **Aumento de capital social**: Ação que aumenta o valor total da empresa
- **Trespasse ou arrendamento de estabelecimento**: Venda parcial dos bens da empresa
- **Redução salarial, compensação de horários e redução da jornada**: Ações que podem ser realizadas para reduzir os custos da empresa

### Referências legais
- Art. 50, § 3º do Código de Processo Civil
- Lei n.º 14.112/2020

### Dicas de prova
- Entenda a diferença entre conversão de dívida em capital e aporte de novos recursos na devedora
- Conheça as novidades introduzidas pela Lei n.º 14.112/2020', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.193 (1)", "page_number": 193, "discipline": "Direito Empresarial", "legal_refs": ["Art. 50, § 3º do Código de Processo Civil", "Lei n.º 14.112/2020"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:58:05.075407+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=193", "doc_key": "fd83162d3d492fba1d41564ac15c0a43"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '63c3d1cacd80dc26fec22bc819fa50438bf9553e9cf84f469dfae99a621ee7a1'),
  ('cpiuris2025::bcf4d6daab52b7528bbc402c33290030', 'doutrina', 'cp_iuris', 'Direito Empresarial — Participação de sociedades em recuperação judicial em procedimentos licitatórios', '## Participação de sociedades em recuperação judicial em procedimentos licitatórios

A sociedade empresária em recuperação judicial pode participar de procedimentos licitatórios sem apresentar certidão negativa de recuperação judicial, de acordo com o art. 47 da LFRE.

### Conceitos
- **Sociedade Empresária**: Entidade jurídica que exerce atividades empresariais
- **Recuperação Judicial**: Procedimento processual destinado a evitar a falência de uma empresa
- **Certidão Negativa de Recuperação Judicial**: Documento que confirma a não existência de procedimento de recuperação judicial
- **Procedimento Licitatório**: Processo em que as empresas concorrem para obter um contrato ou licença

### Referências legais
- Art. 47 da Lei Federal de Regulação Empresarial (LFRE)

### Jurisprudência
- AgRg na MC 23.499/RS
- Súmula do STJ

### Dicas de prova
- Entenda a diferença entre certidão negativa e procedimento de recuperação judicial
- Conheça as fases do processo de recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.193 (2)", "page_number": 193, "discipline": "Direito Empresarial", "legal_refs": ["Art. 47 da Lei Federal de Regulação Empresarial (LFRE)"], "jurisprudence": ["AgRg na MC 23.499/RS", "Súmula do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T04:58:43.803317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=193", "doc_key": "bcf4d6daab52b7528bbc402c33290030"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5f568cfdce65e1df43f8d9cc4d136a21c8bfd9a66cc16ab1718a38544ddd281d'),
  ('cpiuris2025::832c1d09b8fb2842bce2e0498015de51', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos para recuperação judicial', '## Requisitos para recuperação judicial

O devedor deve estar em atividade regular há mais de dois anos, não ser falido e não ter obtido recuperação judicial nos últimos cinco anos. Além disso, deve atender a outros requisitos cumulativos.

### Conceitos
- **atividade regular**: estar devidamente registrado na Junta Comercial, ter todos os livros corretamente escriturados e estar em dia com suas obrigações registrais e escriturais
- **requisitos para recuperação judicial**: estar no exercício regular de suas atividades há mais de dois anos, não ser falido e não ter obtido recuperação judicial nos últimos cinco anos

### Referências legais
- Art. 48 da LFRE

### Jurisprudência
- Súmula 456 do STJ

### Dicas de prova
- Pergunte se o devedor está em atividade regular e se atende aos requisitos para recuperação judicial
- Lembre-se de que a recuperação judicial também pode ser requerida pelo cônjuge sobrevivente, herdeiros do devedor, inventariante ou sócio remanescente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.194 (1)", "page_number": 194, "discipline": "Direito Empresarial", "legal_refs": ["Art. 48 da LFRE"], "jurisprudence": ["Súmula 456 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T04:59:14.065746+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=194", "doc_key": "832c1d09b8fb2842bce2e0498015de51"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '560b55f0a6a718eb32309a681f33c1b0c98ac0093aa68598fa0344854e801ce6'),
  ('cpiuris2025::03782cefe438607feda78aa7b43fa130', 'doutrina', 'cp_iuris', 'Direito Empresarial — Exigências contábeis para comprovação do prazo de exercício rural', '## Exigências contábeis para comprovação do prazo de exercício rural

O artigo estabelece as regras para a comprovação do prazo de exercício de atividade rural por pessoa jurídica e física, permitindo o uso da Escrituração Contábil Fiscal (ECF) ou obrigação legal de registros contábeis substituta, bem como a utilização do Livro Caixa Digital do Produtor Rural (LCDPR), Declaração do Imposto sobre a Renda da Pessoa Física (DIRPF) e balanço patrimonial.

### Conceitos
- **Escrituração Contábil Fiscal**: Documentação contábil utilizada para comprovar o prazo de exercício rural
- **Livro Caixa Digital do Produtor Rural**: Sistema digital utilizado para registrar receitas e despesas da atividade rural
- **Declaração do Imposto sobre a Renda da Pessoa Física**: Declaração anual que relata as rendas e impostos pagos pela pessoa física
- **Balanço Patrimonial**: Relatório financeiro que apresenta o patrimônio líquido de uma empresa ou pessoa física

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da Escrituração Contábil Fiscal (ECF) e do Livro Caixa Digital do Produtor Rural (LCDPR) para comprovar o prazo de exercício rural.
- Conheça as regras para a elaboração do balanço patrimonial e sua importância para a comprovação do prazo de exercício rural.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.194 (2)", "page_number": 194, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T04:59:50.059813+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=194", "doc_key": "03782cefe438607feda78aa7b43fa130"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '78d26a230edeca525b101054f25c73d95ff71190f952bd00f125445554f97290'),
  ('cpiuris2025::1529d3371e2d6c244ea3ae26f1d625f6', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos para recuperação judicial', '## Requisitos para recuperação judicial

O artigo discute os requisitos necessários para o ingresso do pedido de recuperação judicial, distinguindo-se a decisão que concede a Recuperação Judicial da decisão que defere o processamento do pedido.

### Conceitos
- **Recuperação Judicial**: Processo em que uma empresa pode ser salva da falência com a apresentação de um plano de recuperação
- **Petição inicial**: Documento que apresenta os motivos da situação de dificuldade financeira e as demonstrações contábeis
- **Constatação prévia**: Procedimento que visa verificar a regularidade das condições de funcionamento da empresa e da documentação apresentada
- **Requisitos da inicial**: Motivos da situação de dificuldade financeira, demonstrações contábeis, relação dos credores, entre outros

### Referências legais
- Art. 48 da LFRE
- Art. 51 da LFRE

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre a decisão que concede a Recuperação Judicial e a decisão que defere o processamento do pedido
- Conheça os requisitos necessários para o ingresso do pedido de recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.195 (1)", "page_number": 195, "discipline": "Direito Empresarial", "legal_refs": ["Art. 48 da LFRE", "Art. 51 da LFRE"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T05:00:33.771290+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=195", "doc_key": "1529d3371e2d6c244ea3ae26f1d625f6"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '4524898400339dbd1e6efa11dc3149971951ce69395e458e1a47658e3bf02c4d'),
  ('cpiuris2025::0c95583ee662416f15c8b70aebcef1dc', 'doutrina', 'cp_iuris', 'Direito Empresarial — Constatação Prévia na Recuperação Judicial', '## Constatação Prévia na Recuperação Judicial

A constatação prévia é um procedimento previsto na Lei n.º 14.112/2020, que visa verificar as condições de funcionamento da empresa e regularidade documental antes do início da recuperação judicial.

### Conceitos
- **Constatação Prévia**: Procedimento previsto na Lei n.º 14.112/2020
- **Recuperação Judicial**: Processo que visa reestruturar a dívida do devedor
- **Lei n.º 14.112/2020**: Lei que instituiu o procedimento de constatação prévia

### Referências legais
- Art. 51-A da Lei n.º 14.112/2020

### Jurisprudência
- 5 REsp 1.665.042-RS
- Tema repetitivo: Constatação Prévia na Recuperação Judicial

### Dicas de prova
- Entenda a importância da constatação prévia na recuperação judicial
- Conheça as regras e prazos estabelecidos pela lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.195 (2)", "page_number": 195, "discipline": "Direito Empresarial", "legal_refs": ["Art. 51-A da Lei n.º 14.112/2020"], "jurisprudence": ["5 REsp 1.665.042-RS", "Tema repetitivo: Constatação Prévia na Recuperação Judicial"], "confidence": 0.8, "extracted_at": "2026-05-27T05:01:01.515206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=195", "doc_key": "0c95583ee662416f15c8b70aebcef1dc"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '55a5483fdec1893866579a4d357697d6cae141049ba66ab8a8b406dd26cdc86b'),
  ('cpiuris2025::15c401e333a29aa16ed273f8c492b29e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Deferimento do processamento da recuperação judicial e stay period', '## Deferimento do processamento da recuperação judicial e stay period

O juiz pode indeferir a petição inicial se houver indícios de utilização fraudulenta da ação de recuperação judicial. Além disso, o juiz deve determinar a remessa dos autos ao juízo competente se o principal estabelecimento do devedor não se situa na área de competência do juízo.

### Conceitos
- **Recuperação Judicial**: Procedimento jurídico que visa reorganizar a situação financeira de uma empresa em recuperação
- **Ação de Recuperação Judicial**: Petição inicial apresentada pela empresa para iniciar o processo de recuperação judicial
- **Stay Period**: Périodo durante o qual as ações e execuções contra o devedor são suspensas
- **Suspensão da Prescrição**: Mudança na regra de prescrição para permitir que o devedor continue com suas obrigações

### Referências legais
- Art. 6º, § 6º da Lei n.º 11.1017/2005
- Súmula 373 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo: Recuperação Judicial

### Dicas de prova
- Diferenciar entre a utilização fraudulenta da ação de recuperação judicial e a falta de competência do juízo
- Entender o conceito de stay period e sua importância na recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.196 (1)", "page_number": 196, "discipline": "Direito Empresarial", "legal_refs": ["Art. 6º, § 6º da Lei n.º 11.1017/2005", "Súmula 373 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Recuperação Judicial"], "confidence": 0.8, "extracted_at": "2026-05-27T05:01:40.259426+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=196", "doc_key": "15c401e333a29aa16ed273f8c492b29e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e5f26646c4c25042e18ad3f1657f77afd076a8b247aa27915933d4828804ff67'),
  ('cpiuris2025::a0825c9e3b48a769eec29ea81f28cb7b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Suspensão de Atos Constrictivos em Recuperação Judicial', '## Suspensão de Atos Constrictivos em Recuperação Judicial

A competência do juiz da recuperação judicial pode determinar a suspensão de atos de constrição sobre bens essenciais à manutenção da atividade empresarial, com cooperação jurisdicional e observação do Código de Processo Civil.

### Conceitos
- **Recuperação Judicial**: Procedimento judicial que visa reestruturar a dívida do devedor
- **Suspensão de Atos Constrictivos**: Mudança da situação jurídica de um ato constritivo para uma suspensa ou temporária
- **Cooperação Jurisdicional**: Colaboração entre o juiz e as partes para alcançar a solução do caso
- **Código de Processo Civil**: Lei que regula os procedimentos judiciais no Brasil
- **Princípio da Preservação da Empresa**: Princípio que visa proteger a empresa e seus bens em caso de recuperação judicial

### Referências legais
- Art. 49 da LFRE
- Art. 69 da Lei n.º 13.105/2015
- Art. 6º, § 7º, da Lei n.º 11.101/05
- Art. 187 do CTN
- Art. 29 da Lei n.º 6.830/80

### Jurisprudência
- Súmula N STJ

### Dicas de prova
- Entenda a importância da cooperação jurisdicional na Recuperação Judicial
- Conheça o Código de Processo Civil e sua aplicação em casos de Recuperação Judicial
- Aprenda a distinguir entre atos constritivos e suspensos em casos de Recuperação Judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.196 (2)", "page_number": 196, "discipline": "Direito Empresarial", "legal_refs": ["Art. 49 da LFRE", "Art. 69 da Lei n.º 13.105/2015", "Art. 6º, § 7º, da Lei n.º 11.101/05", "Art. 187 do CTN", "Art. 29 da Lei n.º 6.830/80"], "jurisprudence": ["Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T05:02:29.668100+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=196", "doc_key": "a0825c9e3b48a769eec29ea81f28cb7b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '813df48c01774589133a6786ff28c1ee7e1f507fb6e342769885c6cb3b7f6a5e'),
  ('cpiuris2025::552d39ac0f32b1e7337a04e7c9cfdc39', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cooperação Jurisdicional e Competência no Recuperacional', '## Cooperação Jurisdicional e Competência no Recuperacional

A lei determina cooperação jurisdicional para promover a substituição de atos de constrição sobre bens essenciais à manutenção da atividade empresarial.

### Conceitos
- **Recuperação Judicial**: Processo que visa reestruturar as obrigações do devedor
- **Falência**: Declaração judicial do não pagamento de dívidas
- **Competência Jurisdicional**: Atribuição do poder de julgamento a um juiz ou tribunal
- **Cooperação Jurisdicional**: Colaboração entre juízes e tribunais para resolver conflitos

### Referências legais
- Art. 6º da LFRE

### Dicas de prova
- Entenda a importância da cooperação jurisdicional no contexto do recuperacional
- Conheça as suspensões e proibições impostas pela lei em relação às execuções judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.197 (1)", "page_number": 197, "discipline": "Direito Empresarial", "legal_refs": ["Art. 6º da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:02:57.718761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=197", "doc_key": "552d39ac0f32b1e7337a04e7c9cfdc39"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fd76153c7b2ff83a77042aa21908460581586f6ea18314c0bbac30985be70fac'),
  ('cpiuris2025::83ed096c5df27262f9e75e3c1d75edb0', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Judicial', '## Recuperação Judicial

O devedor pode solicitar o deferimento do processamento da recuperação judicial por um período igual ao prazo previsto no § 4º, desde que não concorde com a superação do lapso temporal. Em caso de não apresentação de plano alternativo pelos credores dentro do prazo, é facultada a propositura de plano alternativo.

### Conceitos
- **Recuperação Judicial**: Processo em que o devedor solicita a proteção da massa para evitar a falência
- **Prazo de Recuperação**: Período durante o qual o devedor tem a oportunidade de recuperar suas atividades e pagar as dívidas
- **Plano Alternativo**: Proposta dos credores para substituir o plano de recuperação judicial proposto pelo devedor
- **Suspensão de Pagamento**: Prazo concedido ao devedor para pagar as dívidas sem penalidades
- **Proibição de Quebra de Quotação**: Restrição à quebra de quitação das dívidas do devedor

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre o plano de recuperação judicial e o plano alternativo.
- Conheça as consequências de não apresentar o plano alternativo pelos credores dentro do prazo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.197 (2)", "page_number": 197, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:03:31.562624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=197", "doc_key": "83ed096c5df27262f9e75e3c1d75edb0"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '87d378e9389dc1e84fdb364d0d58e8161376c34028b7b8af96ec7662572dbcfd'),
  ('cpiuris2025::e815f3b47ac527b4b96e506e080cd7ee', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falência e Recuperação Judicial', '## Falência e Recuperação Judicial

Regulamentação da competência do juízo da recuperação judicial em relação aos créditos e execuções fiscais.

### Conceitos
- **Competência do juiz da recuperação judicial**: A competência do juiz para processar e julgar ações relacionadas à recuperação judicial.
- **Execuções fiscais**: Execuções realizadas pelo Estado para cobrar dívidas fiscais.
- **Bens de capital essenciais**: Bens necessários à manutenção da atividade empresarial.
- **Suspensão dos atos de constrição**: A suspensão do processo de constrição sobre bens de capital essenciais.
- **Cooperação jurisdicional**: A colaboração entre os juízes e as autoridades para implementar a recuperação judicial.
- **Código de Processo Civil**: Lei que regula o processo civil no Brasil.
- **Art. 69 da Lei n.º 13.105**: Regra específica sobre a cooperação jurisdicional para a recuperação judicial.
- **Art. 805 do Código de Processo Civil**: Regra que regula a cooperação entre os juízes e as autoridades.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência do juiz da recuperação judicial e como ela se aplica às execuções fiscais.
- Conheça as regras sobre a cooperação jurisdicional e sua importância na recuperação judicial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.198 (1)", "page_number": 198, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T05:04:23.976302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=198", "doc_key": "e815f3b47ac527b4b96e506e080cd7ee"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ac818e6925738cfbfd1940cad71a87ff50341e090bf838bb2843ea71f4685493'),
  ('cpiuris2025::b591bd04b66c93a85a4f5be708005f4a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Judicial e Avalistas', '## Recuperação Judicial e Avalistas

O artigo 5º, I, da LFRE afasta a recuperação judicial de obrigações gratuitas, mas permite que o avalista possa figurar em um título onerosamente ou gratuitamente. A verificação da natureza do aval é imprescindível antes do pedido de recuperação judicial.

### Conceitos
- **Avalista**: Pessoa que fornece aval para uma empresa
- **Recuperação Judicial**: Procedimento jurídico que visa reestruturar a dívida de uma empresa em falência
- **Título Gratuito**: Obrigação que não é paga ou pode ser ignorada pelo credor
- **Título Oneroso**: Obrigação que é paga ou deve ser ressarcida ao credor
- **Aval Prestado**: Garantia oferecida pelo avalista para uma empresa

### Referências legais
- Art. 5º, I, da LFRE

### Jurisprudência
- STJ - REsp 1.829.790-RS
- STJ - Tema repetitivo

### Dicas de prova
- Entenda a diferença entre aval oneroso e gratuito
- Verifique se o aval está sujeito ao processo de soerguimento
- Conheça o prazo de suspensão das ações e execuções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.198 (2)", "page_number": 198, "discipline": "Direito Empresarial", "legal_refs": ["Art. 5º, I, da LFRE"], "jurisprudence": ["STJ - REsp 1.829.790-RS", "STJ - Tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-27T05:04:59.594360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=198", "doc_key": "b591bd04b66c93a85a4f5be708005f4a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8217989be00f585f55e2658ac968094528ab2e55de7207fb73c4833de70ae800'),
  ('cpiuris2025::6cdeaea9d73a11359a38c0247daf79c1', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Judicial e Plano Alternativo', '## Recuperação Judicial e Plano Alternativo

A Lei n.º 14.112/2020 introduziu novas regras para a recuperação judicial, incluindo a possibilidade de plano alternativo em caso de decurso do prazo de 180 dias sem deliberação. A decisão que defere o processamento da recuperação é recorrível, mas somente após a homologação do plano e a novação dos créditos.

### Conceitos
- **Recuperação Judicial**: Processo em que o devedor apresenta um plano para reestruturar seus dívidas
- **Plano Alternativo**: Plano apresentado pelos credores em caso de decurso do prazo de 180 dias sem deliberação
- **Decisão Recorrível**: Decisão que pode ser recorrida ao Tribunal Superior Eleitoral (TSE)

### Referências legais
- Art. 14.112/2020

### Jurisprudência
- Enunciado 52 das Jornadas de Direito Comercial do CJF
- Súmula antiga do STJ referente à concordata

### Dicas de prova
- Entenda a diferença entre o plano de recuperação e o plano alternativo
- Conheça as regras para a decisão que defere o processamento da recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.199 (1)", "page_number": 199, "discipline": "Direito Empresarial", "legal_refs": ["Art. 14.112/2020"], "jurisprudence": ["Enunciado 52 das Jornadas de Direito Comercial do CJF", "Súmula antiga do STJ referente à concordata"], "confidence": 0.8, "extracted_at": "2026-05-27T05:05:33.838485+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=199", "doc_key": "6cdeaea9d73a11359a38c0247daf79c1"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '4cf2f65c0244d863d1f3d0967ead241bba16d577cee3caa156acb47c084882e0'),
  ('cpiuris2025::c5c4af70b3e4ef46ab5ebc106d899286', 'doutrina', 'cp_iuris', 'Direito Empresarial — Plano de Recuperação Judicial', '## Plano de Recuperação Judicial

O devedor deve apresentar um plano de recuperação judicial dentro de 60 dias, sob pena de conversão do processo em falência. O plano deve conter discriminação dos meios de recuperação, demonstração de viabilidade econômica e laudo econômico-financeiro.

### Conceitos
- **Plano de Recuperação Judicial**: projeto apresentado pelo devedor para superar dificuldades financeiras
- **Devedor**: parte que deve cumprir com obrigações contratuais ou legais
- **Falência**: processo judicial que determina a liquidação de bens e ativos de um devedor

### Referências legais
- Art. 50 da LFRE
- Súmula 168.000/AL do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre o conteúdo do plano de recuperação judicial
- Distinção entre falência e recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.199 (2)", "page_number": 199, "discipline": "Direito Empresarial", "legal_refs": ["Art. 50 da LFRE", "Súmula 168.000/AL do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T05:06:10.448882+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=199", "doc_key": "c5c4af70b3e4ef46ab5ebc106d899286"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '40154138838684aef09bfa00879bbdff371be27ac3703f6a7604adc658edc132'),
  ('cpiuris2025::728ff5a625bd47de4ee61f4ae2e80d98', 'doutrina', 'cp_iuris', 'Direito Empresarial — Plano de Recuperação Judicial e Diretrizes Gerais', '## Plano de Recuperação Judicial e Diretrizes Gerais

O plano de recuperação judicial não pode prever prazos superior a um ano para pagamento de créditos trabalhistas vencidos até a data do pedido, além de outras diretrizes gerais.

### Conceitos
- **Plano de Recuperação Judicial**: Instrumento jurídico que permite ao devedor apresentar um plano para pagar suas obrigações vencidas ou vincendas
- **Alienação de Bens Onerados**: Processo pelo qual o devedor aliena bens que servem como garantia para as dívidas
- **Sucessão do Adquirente**: Ocorre quando o adquirente da garantia assume as obrigações do devedor
- **Parcelamento do Crédito Fiscal**: Divisão do crédito fiscal em parcelas menores para facilitar o pagamento

### Referências legais
- Art. 60 da Lei n.º 11.101/2005
- Súmula 47 das Jornadas de Direito Comercial

### Jurisprudência
- Enunciado 47 das Jornadas de Direito Comercial

### Dicas de prova
- Entenda a importância do plano de recuperação judicial e suas limitações
- Conheça as diretrizes gerais para a alienação de bens onerados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.200 (1)", "page_number": 200, "discipline": "Direito Empresarial", "legal_refs": ["Art. 60 da Lei n.º 11.101/2005", "Súmula 47 das Jornadas de Direito Comercial"], "jurisprudence": ["Enunciado 47 das Jornadas de Direito Comercial"], "confidence": 0.8, "extracted_at": "2026-05-27T05:06:46.670699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=200", "doc_key": "728ff5a625bd47de4ee61f4ae2e80d98"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '739508d72a50379334a0898d60d49b93c2dd03146e52161183db2ba61843ffd7'),
  ('cpiuris2025::41a6a446e93d8b87f60834df6bae3c53', 'doutrina', 'cp_iuris', 'Direito Empresarial — Plano de Recuperação Judicial', '## Plano de Recuperação Judicial

O plano de recuperação judicial é apresentado pelo devedor e depende da concordância dos credores. Se nenhum credor se opõe, o plano é tacitamente aprovado. Em caso de objeção, a assembleia-geral de credores decide sobre as alterações.

### Conceitos
- **Plano de Recuperação Judicial**: projeto apresentado pelo devedor para recuperação financeira
- **Credores**: partes que têm direito ao pagamento do débito
- **Assembleia-Geral de Credores**: reunião dos credores para deliberar sobre o plano
- **Objeção**: ação do credor que se opõe ao plano
- **Concordância**: acordo entre o devedor e os credores
- **Convocação**: chamada para a assembleia-geral de credores
- **Cram Down**: aplicação de lei que obriga o devedor a cumprir com as condições do plano

### Referências legais
- Art. 55 da LFRE

### Dicas de prova
- Entenda a concordância e objeção nos planos de recuperação judicial
- Conheça o papel da assembleia-geral de credores na decisão sobre o plano', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.200 (2)", "page_number": 200, "discipline": "Direito Empresarial", "legal_refs": ["Art. 55 da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:07:18.788396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=200", "doc_key": "41a6a446e93d8b87f60834df6bae3c53"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5b846ea62c59f633cda1946ebbaf6baf08cfd0aee960a39310ba83d9b410d321'),
  ('cpiuris2025::bd41c3f6c684b24afa65b1f89c5ac3f0', 'doutrina', 'cp_iuris', 'Direito Empresarial — Plano de Recuperação Judicial e Cram Down', '## Plano de Recuperação Judicial e Cram Down

A Lei n.º 14.112/2020 estabelece regras para a apresentação de plano de recuperação judicial, incluindo o cram down e a capitalização dos créditos.

### Conceitos
- **Cram Down**: Hipótese em que o juiz homologa o plano apresentado pelo devedor apesar de ter sido rejeitado pela Assembleia-Geral de Credores
- **Plano Alternativo**: Plano apresentado pelos credores após a concessão de prazo para apresentação de plano de recuperação judicial
- **Capitalização dos Créditos**: Alteração do controle da sociedade devedora resultante da capitalização dos créditos

### Referências legais
- Art. 58 § 1º LFRE
- Art. 53 LFRE
- Lei n.º 14.112/2020

### Dicas de prova
- Entenda a diferença entre plano de recuperação judicial e plano alternativo
- Conheça os requisitos para o cram down e como ele afeta a apresentação do plano
- Avalie a importância da capitalização dos créditos na sociedade devedora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.201 (1)", "page_number": 201, "discipline": "Direito Empresarial", "legal_refs": ["Art. 58 § 1º LFRE", "Art. 53 LFRE", "Lei n.º 14.112/2020"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:08:02.476709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=201", "doc_key": "bd41c3f6c684b24afa65b1f89c5ac3f0"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5dff8e2ecbc15b5286dd12246fcb19a615ed775686c15f50f2030119883f1ae5'),
  ('cpiuris2025::38aac07345bd9c18293f568376a884c9', 'doutrina', 'cp_iuris', 'Direito Empresarial — Aprovação do Plano de Recuperação', '## Aprovação do Plano de Recuperação

Para a aprovação do plano, a assembleia-geral de credores é dividida em classes, cada uma com regras específicas.

### Conceitos
- **Assembleia-Geral de Credores**: órgão responsável pela aprovação ou rejeição do plano de recuperação
- **Classes de Credores**: divisão das partes interessadas em categorias específicas, como trabalhistas, titulares de garantia real, etc.
- **Regras do Art. 45 da LFRE**: normas que regem a aprovação do plano dentro de cada classe

### Referências legais
- Art. 41 da LFRE
- Art. 45 da LFRE

### Dicas de prova
- Entenda a importância das classes de credores na aprovação do plano.
- Conheça as regras específicas para cada classe de credores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.201 (2)", "page_number": 201, "discipline": "Direito Empresarial", "legal_refs": ["Art. 41 da LFRE", "Art. 45 da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:08:25.873325+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=201", "doc_key": "38aac07345bd9c18293f568376a884c9"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1b4d7d4df9af81beef1d9b88819f6fa8f7d51c2a669ace91fd74781e7d6182f4'),
  ('cpiuris2025::087f3e3b63d34c17a19fc8ce869c0dc7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Aprovação do Plano de Recuperação Judicial', '## Aprovação do Plano de Recuperação Judicial

A aprovação do plano de recuperação judicial depende da aprovação dos credores por cabeça e da maioria dos créditos presentes, exceto para os credores trabalhistas e microempresários individuais e empresários de pequeno porte, que são votados por cabeça.

### Conceitos
- **Cabeça**: Voto individualizado dos credores
- **Maioria**: Número superior à metade dos créditos presentes
- **Crédito**: Unidade de valor do débito
- **Credor**: Parte que tem direito ao pagamento do débito

### Referências legais
- Art. 56-A da Lei n.º 14.112/2020

### Jurisprudência
- {''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}
- {''term'': ''REsp 1.634.844-SP'', ''definition'': ''Resolução Especial do Superior Tribunal de Justiça''}

### Dicas de prova
- Entenda a diferença entre aprovação por cabeça e aprovação por maioria dos créditos.
- Conheça as exceções para os credores trabalhistas e microempresários individuais e empresários de pequeno porte.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.202 (1)", "page_number": 202, "discipline": "Direito Empresarial", "legal_refs": ["Art. 56-A da Lei n.º 14.112/2020"], "jurisprudence": ["{''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}", "{''term'': ''REsp 1.634.844-SP'', ''definition'': ''Resolução Especial do Superior Tribunal de Justiça''}"], "confidence": 0.8, "extracted_at": "2026-05-27T05:09:01.614786+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=202", "doc_key": "087f3e3b63d34c17a19fc8ce869c0dc7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5a63566aa74f818bc7def61e0595da3c5aaa95274621fb4d92b66fa76188d067'),
  ('cpiuris2025::b29c5214a2693c5912981ed938ec81dd', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos para homologação do plano de recuperação', '## Requisitos para homologação do plano de recuperação

O juiz pode homologar o plano de recuperação mesmo em caso de rejeição, desde que presentes os requisitos do art. 58, §§ 1º e 2º, da LFRE.

### Conceitos
- **Cram down**: Hipótese em que o juiz homologa o plano de recuperação apesar de rejeição
- **Objeção de credor**: Reclamação apresentada por um credor sobre o plano de recuperação
- **Plano de recuperação**: Proposta do devedor para recuperar sua situação financeira

### Referências legais
- Art. 55 da LFRE
- Art. 58, §§ 1º e 2º da LFRE

### Dicas de prova
- Entenda a diferença entre objeção de credor e rejeição do plano.
- Conheça os requisitos do art. 58, §§ 1º e 2º da LFRE para o cram down.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.202 (2)", "page_number": 202, "discipline": "Direito Empresarial", "legal_refs": ["Art. 55 da LFRE", "Art. 58, §§ 1º e 2º da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:09:39.556950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=202", "doc_key": "b29c5214a2693c5912981ed938ec81dd"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '948d2409b18a79fed44bddf24008a255a155788963bdc67de2e46d3fefa87941'),
  ('cpiuris2025::6b21d3bc2ce274b70bd369c848b7b7ef', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recepção da Recuperação Judicial e Controle Jurisdicional', '## Recepção da Recuperação Judicial e Controle Jurisdicional

O juiz pode conceder a recuperação judicial sem aprovação do plano, desde que atendam requisitos específicos, como voto favorável de credores que representem mais da metade do valor dos créditos presentes à assembléia.

### Conceitos
- **Recepção da Recuperação Judicial**: Concessão da recuperação judicial pelo juiz, sem necessidade de aprovação do plano
- **Controle Jurisdicional**: O poder do juiz em controlar a assembleia-geral de credores e garantir que os requisitos sejam cumpridos
- **Assembleia-Geral de Credores**: Órgão soberano que representa os credores da empresa
- **Voto Favorável**: A decisão dos credores em favor do plano de recuperação
- **Abuso de Direito**: Situação em que o devedor ou os credores tentam manipular o processo para obter vantagens injustas

### Referências legais
- Art. 45 da Lei nº 11.101/2005
- Art. 58 da Lei nº 11.101/2005
- Enunciado 44 das Jornadas de Direito Comercial do CJF
- Enunciado 45 das Jornadas de Direito Comercial do CJF

### Jurisprudência
- REsp 1.359.311
- RE nº 123456

### Dicas de prova
- Entenda a importância da assembleia-geral de credores e o papel do juiz no controle jurisdicional
- Identifique os requisitos específicos para a concessão da recuperação judicial
- Aprenda a distinguir entre abuso de direito e legítima defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.203 (1)", "page_number": 203, "discipline": "Direito Empresarial", "legal_refs": ["Art. 45 da Lei nº 11.101/2005", "Art. 58 da Lei nº 11.101/2005", "Enunciado 44 das Jornadas de Direito Comercial do CJF", "Enunciado 45 das Jornadas de Direito Comercial do CJF"], "jurisprudence": ["REsp 1.359.311", "RE nº 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T05:10:24.319957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=203", "doc_key": "6b21d3bc2ce274b70bd369c848b7b7ef"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'edc46137486be8c0e19e2291f170f1b5e1e3ee40c67e3da1d9d488fc2088b7e0'),
  ('cpiuris2025::fcab46d7a22a7de9e5d66cd654adfd84', 'doutrina', 'cp_iuris', 'Direito Empresarial — Controle Judicial sobre Planos de Recuperação Judicial', '## Controle Judicial sobre Planos de Recuperação Judicial

A assembleia de credores é soberana em suas decisões quanto aos planos de recuperação judicial, mas as deliberações desse plano estão sujeitas a controle judicial para garantir a legalidade. O Poder Judiciário pode promover o controle de legalidade do plano sem analisar a viabilidade econômica da empresa.

### Conceitos
- **Assembleia de Credores**: órgão responsável por tomar decisões sobre planos de recuperação judicial
- **Controle Judicial**: mecanismo que garante a legalidade das deliberações da assembleia de credores
- **Viabilidade Econômica**: aspecto que a assembleia de credores analisa ao aprovar um plano de recuperação judicial
- **Poder Judiciário**: órgão responsável por garantir a legalidade dos planos de recuperação judicial
- **Legalidade**: requisito que as deliberações da assembleia de credores devem atender para serem homologadas
- **Abuso de Direitos**: situação em que um credor vota contra o plano de recuperação judicial com o objetivo de prejudicar a empresa

### Referências legais
- Art. 182 da Lei 11.101/2005
- Súmula 434 do STJ

### Jurisprudência
- REsp 1314209/SP
- ...

### Dicas de prova
- Entenda a soberania da assembleia de credores e o papel do controle judicial
- Conheça as limitações do controle judicial sobre os planos de recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.203 (2)", "page_number": 203, "discipline": "Direito Empresarial", "legal_refs": ["Art. 182 da Lei 11.101/2005", "Súmula 434 do STJ"], "jurisprudence": ["REsp 1314209/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T05:11:00.794538+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=203", "doc_key": "fcab46d7a22a7de9e5d66cd654adfd84"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '95c2d63a1ba03faaff7961cb12135cac739f64f1af444dd79192415ba7d0ff73'),
  ('cpiuris2025::40c95ccb7c83a04edf00e98f5b634439', 'doutrina', 'cp_iuris', 'Direito Empresarial — Controle de Legalidade do Plano de Recuperação Judicial', '## Controle de Legalidade do Plano de Recuperação Judicial

O controle de legalidade do plano de recuperação judicial preserva os efeitos legais das normas cogentes, mas não implica na desconsideração da assembleia-geral de credores.

### Conceitos
- **Noverção**: extinção dos acessórios e garantias da dívida
- **Garantias reais**: garantias que são mantidas na novação sui generis
- **Execução de título extrajudicial**: execuções ajuizadas contra o próprio devedor ou terceiros garantidores

### Referências legais
- Art. 59 da LFRE
- Súmula 581 do STJ
- Art. 364 do Código Civil

### Jurisprudência
- Informativo 591 do STJ

### Dicas de prova
- Entenda a diferença entre novação sui generis e extinção dos acessórios e garantias da dívida
- Conheça as garantias reais e fidejussórias preservadas na novação sui generis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.204 (1)", "page_number": 204, "discipline": "Direito Empresarial", "legal_refs": ["Art. 59 da LFRE", "Súmula 581 do STJ", "Art. 364 do Código Civil"], "jurisprudence": ["Informativo 591 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T05:11:43.521845+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=204", "doc_key": "40c95ccb7c83a04edf00e98f5b634439"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a06981f2e73b97316fe3e21c108783c457e0742eb2bb522d4d8e61ca8886a24d'),
  ('cpiuris2025::2e3ca165b0815f5466c35805772ca1bf', 'doutrina', 'cp_iuris', 'Direito Empresarial — Prosseguimento de execuções contra terceiros após recuperação judicial do devedor principal', '## Prosseguimento de execuções contra terceiros após recuperação judicial do devedor principal

A recuperação judicial do devedor principal não impede o prosseguimento das execuções contra terceiros, devedores solidários ou coobrigados em geral.

### Conceitos
- **Garantia cambial**: Garantia oferecida por um devedor para garantir o pagamento de uma dívida
- **Fidejussório**: Garantia oferecida por meio de compromisso ou promessa de pagar uma dívida
- **Devedores solidários**: Devedores que se obrigam a cumprir uma obrigação conjunta
- **Coobrigados**: Pessoas que estão obrigadas a pagar uma dívida conjuntamente com outro devedor

### Referências legais
- Art. 49, § 1º, da Lei n.º 11.101/2005

### Jurisprudência
- Súmula 581

### Dicas de prova
- Entenda a diferença entre garantia cambial e fidejussório
- Conheça o conceito de devedores solidários e coobrigados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.204 (2)", "page_number": 204, "discipline": "Direito Empresarial", "legal_refs": ["Art. 49, § 1º, da Lei n.º 11.101/2005"], "jurisprudence": ["Súmula 581"], "confidence": 0.8, "extracted_at": "2026-05-27T05:12:11.724459+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=204", "doc_key": "2e3ca165b0815f5466c35805772ca1bf"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '636b593a7f1f9843050cdbab204c09abef15a2bc36ddf6b7d153d657a65d7b4a'),
  ('cpiuris2025::9c54233c1ded051af558636026f95d0a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Plano de Recuperação Judicial e Garantias', '## Plano de Recuperação Judicial e Garantias

O plano de recuperação judicial pode dispensar garantias reais e fidejussórias, atingindo todos os credores, independentemente da participação na assembleia. Se a sociedade não cumprir as obrigações decorrentes do plano dentro dos dois anos seguintes à aprovação, haverá convoluto para falência.

### Conceitos
- **Garantias**: seguros reais ou fidejussórios oferecidos pelos credores
- **Plano de Recuperação Judicial**: projeto apresentado pelos credores para a recuperação da empresa
- **Assembleia-Geral de Credores**: reunião dos credores para decidir sobre o plano de recuperação judicial

### Referências legais
- Art. 61 da LFRE
- Lei n.º 14.112/2020

### Jurisprudência
- Informativo 591
- Súmula do STJ

### Dicas de prova
- Entenda a noção de garantias e como elas são tratadas no plano de recuperação judicial
- Conheça as regras para a aprovação do plano de recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.205 (1)", "page_number": 205, "discipline": "Direito Empresarial", "legal_refs": ["Art. 61 da LFRE", "Lei n.º 14.112/2020"], "jurisprudence": ["Informativo 591", "Súmula do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T05:12:43.758120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=205", "doc_key": "9c54233c1ded051af558636026f95d0a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b96d6255ebe8d7a38aac23240ad7924c7c1acdf5f87bd942ccb0eff68f6f39e1'),
  ('cpiuris2025::687101a6d1fc1f737e0d37e984095345', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Judicial de Empresas', '## Recuperação Judicial de Empresas

A fase de execução da recuperação judicial pode ocorrer de duas formas: cumprimento das obrigações até dois anos após a concessão da recuperação ou pedido de desistência do devedor, aprovado pela assembleia de credores.

### Conceitos
- **Recuperação Judicial**: Processo que visa reestruturar as obrigações de uma empresa em falência
- **Consolidação Processual**: Pedido simultâneo de recuperação judicial por empresas do mesmo grupo econômico
- **Desistência do Devedor**: Aprovamento da assembleia de credores para encerrar a recuperação judicial

### Referências legais
- Art. 63 da LFRE
- Art. 69-G da Lei n.º 11.101/2005

### Dicas de prova
- Entenda a diferença entre recuperação judicial e consolidação processual
- Conheça os requisitos para a desistência do devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.205 (2)", "page_number": 205, "discipline": "Direito Empresarial", "legal_refs": ["Art. 63 da LFRE", "Art. 69-G da Lei n.º 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:13:20.538379+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=205", "doc_key": "687101a6d1fc1f737e0d37e984095345"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a8bf41333b05961de177db9e5dfb49cad179a926e7d48d26172634b043cac8d1'),
  ('cpiuris2025::26face3a67d350d248a8b066a3be8ceb', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Judicial e Consolidação Processual', '## Recuperação Judicial e Consolidação Processual

A recuperação judicial será apresentada individualmente por cada devedor, com um administrador judicial nomeado se a documentação for considerada adequada. A consolidação processual garante a coordenação dos atos processuais, com independência dos devedores e dos seus ativos e passivos.

### Conceitos
- **Recuperação Judicial**: Procedimento jurídico que visa reestruturar os débitos de uma empresa em falência
- **Consolidação Processual**: Coordenação dos atos processuais para garantir a independência dos devedores e dos seus ativos e passivos
- **Administrador Judicial**: Pessoa nomeada para gerenciar os ativos e os passivos de uma empresa em recuperação judicial

### Referências legais
- Art. 51 da Lei Y
- Art. 69-G da Lei Y
- Art. 69-H da Lei Y
- Art. 3º da Lei Y

### Dicas de prova
- Entenda a diferença entre recuperação judicial e consolidação processual
- Conheça o papel do administrador judicial em uma recuperação judicial
- Aprenda a aplicar as regras de consolidação processual para garantir a independência dos devedores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.206 (1)", "page_number": 206, "discipline": "Direito Empresarial", "legal_refs": ["Art. 51 da Lei Y", "Art. 69-G da Lei Y", "Art. 69-H da Lei Y", "Art. 3º da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:13:55.476503+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=206", "doc_key": "26face3a67d350d248a8b066a3be8ceb"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '6f5cd214d0173f390da7ab2dc842c3374fea254b823abddb0fdbb53766a278b6'),
  ('cpiuris2025::47a5e6fc300e6908bc50d18715889a89', 'doutrina', 'cp_iuris', 'Direito Empresarial — Consolidação Substancial de Ativos e Passivos', '## Consolidação Substancial de Ativos e Passivos

Hipótese excepcional em que as empresas terão seus ativos e passivos consolidados em um único devedor, com requisitos legais específicos.

### Conceitos
- **Consolidação Substancial**: Tratamento dos ativos e passivos como se pertencessem a um único devedor
- **Grupos Econômicos**: Empresas que estão em recuperação judicial sob consolidação processual
- **Interconexão e Confusão**: Relação entre ativos ou passivos dos devedores, tornando impossível identificar a titularidade sem excesso de tempo ou recursos

### Referências legais
- Art. 69-J
- Art. 69-K

### Dicas de prova
- Reconhecer a interconexão e confusão entre ativos e passivos dos devedores
- Identificar as hipóteses específicas que justificam a consolidação substancial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.206 (2)", "page_number": 206, "discipline": "Direito Empresarial", "legal_refs": ["Art. 69-J", "Art. 69-K"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:14:21.981414+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=206", "doc_key": "47a5e6fc300e6908bc50d18715889a89"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '64abd5445fb98153ec937115cb2258444ead6b36a0fd147b624aa3157da07885'),
  ('cpiuris2025::87840827775cf2e7b426710475a5172a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Consolidação Substancial e Recuperação Judicial', '## Consolidação Substancial e Recuperação Judicial

A consolidação substancial mantém autonomia patrimonial e individualidade das sociedades devedoras, enquanto a recuperação judicial as trata como um devedor único.

### Conceitos
- **Consolidação Substancial**: Tratamento jurídico que combina várias dívidas em uma única dívida
- **Recuperação Judicial**: Procedimento que visa reestruturar as dívidas de uma empresa em falência ou recuperação judicial
- **Autonomia Patrimonial**: Direito das sociedades devedoras de dispor livremente de seus bens e ativos
- **Individualidade**: Característica que distingue uma empresa de outra, permitindo a sua existência jurídica própria

### Referências legais
- Art. 69-L da Lei 11.1017/2005
- Art. 49 da Lei 11.1017/2005

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre consolidação substancial e recuperação judicial
- Conheça as exceções ao regime de recuperação judicial, como os créditos de proprietário fiduciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.207 (1)", "page_number": 207, "discipline": "Direito Empresarial", "legal_refs": ["Art. 69-L da Lei 11.1017/2005", "Art. 49 da Lei 11.1017/2005"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T05:15:05.080454+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=207", "doc_key": "87840827775cf2e7b426710475a5172a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '93cc799ff543aa09477ab9bb774af64310aa6fb26a05e59ee0ff4d26143e8f6f'),
  ('cpiuris2025::1f294c130f5ef7c05ef2cc76cef8d7b2', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Judicial e Proteção de Bens Essenciais à Atividade Empresarial', '## Recuperação Judicial e Proteção de Bens Essenciais à Atividade Empresarial

A recuperação judicial não afeta a importância dos bens essenciais à atividade empresarial, nem suspende as ações e execuções contra os ''credores proprietários''. A venda ou retirada desses bens é vedada. O juízo da recuperação judicial analisa se o bem é essencial à atividade.

### Conceitos
- **Bem essencial à atividade empresarial**: Bem fundamental para a continuidade da atividade empresarial
- **Recuperação judicial**: Processo que visa reestruturar as dívidas de uma empresa
- **Credores proprietários**: Pessoas físicas ou jurídicas que detêm a propriedade dos bens da empresa

### Referências legais
- Art. 6º, § 7º-A9 da LFRE
- Art. 49, §§ 3º e 4º da LFRE
- Art. 69 da Lei n.º 13.105/2015

### Jurisprudência
- REsp 1.725.609-RS
- Tema repetitivo: Competência do juízo da recuperação judicial para analisar a importância dos bens essenciais à atividade empresarial

### Dicas de prova
- Entenda a competência do juízo da recuperação judicial e a importância dos bens essenciais à atividade empresarial
- Diferencie entre os créditos que estão sujeitos à recuperação judicial e aqueles que não o estão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.207 (2)", "page_number": 207, "discipline": "Direito Empresarial", "legal_refs": ["Art. 6º, § 7º-A9 da LFRE", "Art. 49, §§ 3º e 4º da LFRE", "Art. 69 da Lei n.º 13.105/2015"], "jurisprudence": ["REsp 1.725.609-RS", "Tema repetitivo: Competência do juízo da recuperação judicial para analisar a importância dos bens essenciais à atividade empresarial"], "confidence": 0.8, "extracted_at": "2026-05-27T05:15:42.804721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=207", "doc_key": "1f294c130f5ef7c05ef2cc76cef8d7b2"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '6735e9bb3dccd6857ac6528a5a108ec2ffa5bd3215fad4f2c254d55db71457f3'),
  ('cpiuris2025::48abf71f25b4fc65b87c7db5a14f8167', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sujeição dos encargos ao procedimento recuperacional', '## Sujeição dos encargos ao procedimento recuperacional

A questão discute a sujeição dos encargos incidentes sobre o adiantamento de câmbio às efeitos do procedimento recuperacional. A jurisprudência do STJ entende que os encargos se submetem aos efeitos da recuperação judicial, mas não há regra expressa sobre a destinação dos encargos incidentes.

### Conceitos
- **Extraconcursalidade**: A situação em que os créditos referentes a adiantamento de contratos de câmbio são tratados como se fossem concursais, mesmo que não estejam sujeitos à recuperação judicial.
- **Encargos incidentes**: Os juros de mora e outros encargos que incidem sobre o adiantamento de câmbio.
- **Recuperação judicial**: O procedimento processual pelo qual a empresa pode ser declarada em recuperação judicial, com a ajuda do juiz.

### Referências legais
- Art. 49, § 4º, da Lei n.º 11.101/2005
- Art. 86, II, da Lei n.º 11.101/2005

### Jurisprudência
- Informativo 661 do STJ

### Dicas de prova
- Entenda a diferença entre o valor do principal e os encargos incidentes sobre o adiantamento de câmbio.
- Conheça a jurisprudência do STJ sobre a sujeição dos encargos ao procedimento recuperacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.208 (1)", "page_number": 208, "discipline": "Direito Empresarial", "legal_refs": ["Art. 49, § 4º, da Lei n.º 11.101/2005", "Art. 86, II, da Lei n.º 11.101/2005"], "jurisprudence": ["Informativo 661 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T05:16:21.044873+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=208", "doc_key": "48abf71f25b4fc65b87c7db5a14f8167"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a89d4237d4a9e523c13fd88965c5db3b8dd9cb41fa7ea0eafa400cf71912675c'),
  ('cpiuris2025::0737e53bc3e4ce986909c87e58bdd01b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Plano de Recuperação Judicial e Relação de Credores', '## Plano de Recuperação Judicial e Relação de Credores

O prazo para apresentar objeções ao plano de recuperação judicial começa a correr após a publicação do edital. A habilitação/divergência retardatária pode ser apresentada antes ou depois da homologação do quadro-geral de credores, com regras específicas.

### Conceitos
- **Plano de Recuperação Judicial**: Instrumento jurídico que visa a recuperação da empresa em falência
- **Relação de Credores**: Lista dos credores da empresa, ordenada pela prioridade de seus créditos
- **Habilitação/Divergência**: Ação do credor para apresentar objeções ou divergências ao plano de recuperação judicial
- **Retardatária**: Habilidade do credor para apresentar habilitação/divergência após o prazo legal

### Referências legais
- Art. 7º, § 2º da LRE
- Art. 10 da LFRE
- Art. 10, § 5º da LFRE
- Art. 10, § 6º da LFRE

### Jurisprudência
- STJ. 3ª Turma. REsp 1.840.166-RJ, julgado em 10/12/2019
- REsp 1.810.447-SP, julgado em 05/11/2019

### Dicas de prova
- Entenda a importância do prazo para apresentar objeções ao plano de recuperação judicial
- Conheça as regras específicas para habilitação/divergência retardatária
- Avalie a prioridade dos créditos nos termos da relação de credores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.208 (2)", "page_number": 208, "discipline": "Direito Empresarial", "legal_refs": ["Art. 7º, § 2º da LRE", "Art. 10 da LFRE", "Art. 10, § 5º da LFRE", "Art. 10, § 6º da LFRE"], "jurisprudence": ["STJ. 3ª Turma. REsp 1.840.166-RJ, julgado em 10/12/2019", "REsp 1.810.447-SP, julgado em 05/11/2019"], "confidence": 0.8, "extracted_at": "2026-05-27T05:17:13.663608+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=208", "doc_key": "0737e53bc3e4ce986909c87e58bdd01b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a47cde5fd3e4c5aa7d2a33449e7ef62da9cf8b9ad82da6479068829c5e53018f'),
  ('cpiuris2025::0e49c5e50523b4e99e3fb89eb77a4cde', 'doutrina', 'cp_iuris', 'Direito Empresarial — Quadro-geral de Credores e Recuperação Judicial', '## Quadro-geral de Credores e Recuperação Judicial

O quadro-geral de credores é formado após a autuação das impugnações, com intimação dos credores impugnados. Se não houver impugnação, o quadro se consolidará como quadro-geral. A recuperação judicial pode ser encerrada sem consolidação definitiva do quadro-geral.

### Conceitos
- **Quadro-geral de Credores**: lista de credores com direito à satisfação do crédito discutido
- **Recuperação Judicial**: processo que visa reestruturar a dívida do devedor e evitar a falência
- **Impugnação**: ação apresentada por um credor para desafiar a inclusão no quadro-geral de credores
- **Habilitação**: ação apresentada por um credor para ter direito à satisfação do crédito discutido
- **Dilação probatória**: procedimento que visa coletar mais informações sobre o crédito discutido

### Referências legais
- Art. 8º da LFRE
- Art. 14 da LFRE
- Art. 19 da LFRE
- Lei n.º 14.112/2020, art. 9º, §7º

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Entenda a importância do quadro-geral de credores e como ele é formado
- Conheça as diferenças entre impugnação, habilitação e dilação probatória
- Aprenda a aplicar a Lei Federal de Recuperação Empresarial (LFRE) nos procedimentos de recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.209 (1)", "page_number": 209, "discipline": "Direito Empresarial", "legal_refs": ["Art. 8º da LFRE", "Art. 14 da LFRE", "Art. 19 da LFRE", "Lei n.º 14.112/2020, art. 9º, §7º"], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T05:17:59.094018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=209", "doc_key": "0e49c5e50523b4e99e3fb89eb77a4cde"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '4f69f02401d11c875e5ec69af10f51f3cf748705b05000279902584b01512200'),
  ('cpiuris2025::9c725d312f8d1f60fb524d7a841199a7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Procedimento de impugnação de crédito', '## Procedimento de impugnação de crédito

O procedimento de impugnação de crédito é uma ação incidental com possibilidade de produção de provas e audiência, e deve seguir a técnica de ampliação do colegiado prevista no artigo 942, § 3º, II, do Código de Processo Civil.

### Conceitos
- **Ação incidental**: ação processual que não faz parte da principal demanda
- **Ampliação do colegiado**: técnica que permite a inclusão de novos membros no colegiado para julgar um caso específico
- **Honorários advocatícios**: compensação por serviços jurídicos prestados em casos específicos

### Referências legais
- Art. 942, § 3º, II, do Código de Processo Civil

### Jurisprudência
- REsp 992.846/PR
- REsp 1.797.866-SP
- REsp 1197177/RJ

### Dicas de prova
- Entenda a diferença entre mero incidente processual e ação incidental
- Conheça a técnica de ampliação do colegiado e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.209 (2)", "page_number": 209, "discipline": "Direito Empresarial", "legal_refs": ["Art. 942, § 3º, II, do Código de Processo Civil"], "jurisprudence": ["REsp 992.846/PR", "REsp 1.797.866-SP", "REsp 1197177/RJ"], "confidence": 0.8, "extracted_at": "2026-05-27T05:18:26.345607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=209", "doc_key": "9c725d312f8d1f60fb524d7a841199a7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2cefaccfaaf5695964f3aae921fb78bb36a18e89d036233157ac68aefa2ff214'),
  ('cpiuris2025::abe0efd510a01b8ff9cc2eb6ecb61895', 'doutrina', 'cp_iuris', 'Direito Empresarial — Alienação Fiduciária de Créditos e Recuperação Judicial', '## Alienação Fiduciária de Créditos e Recuperação Judicial

A alienação fiduciária de créditos não se sujeita à recuperação judicial, pois possui natureza jurídica de propriedade fiduciária. A recuperação judicial pode ser comprometida se os créditos não forem incluídos no plano.

### Conceitos
- **Alienação Fiduciária**: Transferência de direitos sobre uma coisa, com a reserva do poder de disposição pelo titular
- **Propriedade Fiduciária**: Direito de gozo e uso de uma coisa, com a reserva do poder de disposição pelo titular
- **Recuperação Judicial**: Procedimento que visa liquidar as dívidas de uma empresa em falência
- **Travas Bancárias**: Restrições impostas por um credor a outro, impedindo o acesso ao dinheiro do devedor

### Referências legais
- Art. 49, § 3º da Lei n.º 11.101/2005

### Jurisprudência
- REsp 1202918/SP
- REsp 1263500/ES
- AgRg no REsp 1.181.533/MT
- AgRg no REsp 1.326.851/MT

### Dicas de prova
- Entenda a natureza jurídica da alienação fiduciária de créditos e sua relação com a recuperação judicial
- Conheça o conceito de travas bancárias e como elas afetam a recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.210 (1)", "page_number": 210, "discipline": "Direito Empresarial", "legal_refs": ["Art. 49, § 3º da Lei n.º 11.101/2005"], "jurisprudence": ["REsp 1202918/SP", "REsp 1263500/ES", "AgRg no REsp 1.181.533/MT", "AgRg no REsp 1.326.851/MT"], "confidence": 0.8, "extracted_at": "2026-05-27T05:19:16.620750+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=210", "doc_key": "abe0efd510a01b8ff9cc2eb6ecb61895"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1787371e71f409066d67b9f5dedfae0ea4348bb7dc838d734f82be4d8e255d04'),
  ('cpiuris2025::215e9bd7d12562c30e2fdb24ec2b1362', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recepção da Recuperação Judicial', '## Recepção da Recuperação Judicial

A expressão não abrange sócios de responsabilidade limitada que são avalistas em certas operações, suspendendo a execução contra o devedor, mas não contra os sócios avalistas.

### Conceitos
- **Recuperação Judicial**: Procedimento jurídico que visa reestruturar a dívida de uma empresa em falência.
- **Sociedade Empresária**: Firma que opera com responsabilidade limitada, sujeita à recuperação judicial.
- **Cobrigado**: Devedor que é cobrado pela dívida da empresa em falência.
- **Fiador**: Pessoa que se responsabiliza pelo pagamento de uma dívida.
- **Obrigado de Regresso**: Cobrigado que tem direito a receber parte do crédito do devedor.

### Referências legais
- Art. 49, § 1º, da LFRE

### Jurisprudência
- AgRg no REsp 1.342.833/SP
- Enunciado 43 das Jornadas de Direito Comercial do CJF

### Dicas de prova
- Entenda a diferença entre o devedor e os sócios avalistas na recuperação judicial.
- Conheça as três partes que compõem a assembleia-geral de credores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.210 (2)", "page_number": 210, "discipline": "Direito Empresarial", "legal_refs": ["Art. 49, § 1º, da LFRE"], "jurisprudence": ["AgRg no REsp 1.342.833/SP", "Enunciado 43 das Jornadas de Direito Comercial do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T05:19:47.348553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=210", "doc_key": "215e9bd7d12562c30e2fdb24ec2b1362"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c3c2f6bf390d191f8b667f25c156eb1828a9c9ead360cf2a0700fd2c5e7be16f'),
  ('cpiuris2025::d80e4d3704556d12105b4ccd49bb6468', 'doutrina', 'cp_iuris', 'Direito Empresarial — Assembleia-Geral de Credores', '## Assembleia-Geral de Credores

A assembleia geral de credores pode ser convocada pelos juízes ou pelos próprios credores, desde que representem pelo menos um quarto do passivo do recuperando. A competência da assembleia inclui aprovar ou rejeitar o plano de recuperação judicial, eleger os membros do comitê dos credores e deliberar sobre matérias de interesse dos credores.

### Conceitos
- **Assembleia-Geral de Credores**: órgão que decide sobre o plano de recuperação judicial
- **Convocação**: chamada para a assembleia geral de credores
- **Credores trabalhistas**: credores que têm prioridade na deliberação sobre o plano de recuperação judicial
- **Comitê dos Credores**: órgão facultativo que representa os credores no processo de recuperação judicial

### Referências legais
- Art. 41 da LFRE
- Art. 26, II, da LFRE

### Dicas de prova
- Entenda a importância da assembleia geral de credores no processo de recuperação judicial
- Conheça as classes de credores e suas prioridades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.211 (1)", "page_number": 211, "discipline": "Direito Empresarial", "legal_refs": ["Art. 41 da LFRE", "Art. 26, II, da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:20:20.448258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=211", "doc_key": "d80e4d3704556d12105b4ccd49bb6468"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '69e44085da1136b9817abe843223dc48105e8ed37d6cc2c48fb91ddea29cbc9c'),
  ('cpiuris2025::7874c2b5d2693ef3f749fc6f8a96b314', 'doutrina', 'cp_iuris', 'Direito Empresarial — Aprovação do Plano de Recuperação Judicial', '## Aprovação do Plano de Recuperação Judicial

A aprovação do plano de recuperação judicial depende da aprovação dos credores em cada classe por cabeça e considerando o valor do crédito que cada um tem perante o devedor.

### Conceitos
- **Credores**: partes que têm direito sobre a massa do devedor
- **Classe de credores**: grupo de credores com características semelhantes
- **Plano de recuperação judicial**: projeto apresentado pelos credores para resolver a situação do devedor
- **Aprovação dos credores**: acordo dos credores em favor ou contra o plano de recuperação
- **Maioria dos credores**: quantidade mínima de credores que devem aprovar o plano de recuperação
- **Credito considerado**: valor do crédito que cada credor tem perante o devedor

### Referências legais
- Art. 99 da Lei nº 11.101/2005

### Dicas de prova
- Entenda a importância da aprovação dos credores em cada classe por cabeça
- Conheça o requisito de maioria dos credores e créditos para aprovação do plano de recuperação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.211 (2)", "page_number": 211, "discipline": "Direito Empresarial", "legal_refs": ["Art. 99 da Lei nº 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:21:01.199615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=211", "doc_key": "7874c2b5d2693ef3f749fc6f8a96b314"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'abe76a990132a2d98c2971e4e3f894c40e0f08a2f928cfda7e067712f3c74f05'),
  ('cpiuris2025::b0f38cf8300e1cba2bee8e2b183f689b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Competência do Comitê no Recuperação Judicial e Falência', '## Competência do Comitê no Recuperação Judicial e Falência

O comitê tem competência fiscal supervisionando a atuação do administrador judicial, administração dos bens e realização do ativo para pagar o passativo.

### Conceitos
- **Administrador Judicial**: Auxiliar do juiz, nomeado pelo despacho do juiz que determinar a recuperação judicial.
- **Competência Fiscal**: Supervisão da atuação do administrador judicial e administração dos bens.
- **Recuperação Judicial**: Procedimento jurídico que visa liquidar a empresa em falência.
- **Falência**: Situação jurídica em que a empresa não pode mais atender às suas obrigações.
- **Comitê**: Entidade responsável por supervisionar a recuperação judicial e falência.
- **Atribuições do Comitê**: Fiscalizar as atividades do administrador judicial, examinar as contas, comunicar ao juiz violações dos direitos dos credores, etc.

### Referências legais
- Art. 27 da Lei n.º 11.101/05

### Dicas de prova
- Entenda a competência do comitê no âmbito da recuperação judicial e falência.
- Conheça as atribuições do administrador judicial e como ele é supervisionado pelo comitê.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.212 (1)", "page_number": 212, "discipline": "Direito Empresarial", "legal_refs": ["Art. 27 da Lei n.º 11.101/05"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:21:38.136527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=212", "doc_key": "b0f38cf8300e1cba2bee8e2b183f689b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8564c8fc6ed2c97c79315ec2e703e8c4821f8d403d9f8846a2e645f63529be15'),
  ('cpiuris2025::164b527030bc643ccf1486bb9a6289a1', 'doutrina', 'cp_iuris', 'Direito Empresarial — Função e Poderes do Administrador Judicial', '## Função e Poderes do Administrador Judicial

O administrador judicial assume funções de fiscalização e análise de créditos em recuperação judicial, com poderes ampliados desde a inovação legislativa de 2020.

### Conceitos
- **Administrador Judicial**: Entidade responsável pela fiscalização e análise de créditos em recuperação judicial
- **Função de Fiscal**: Análise de créditos e presidência da assembleia-geral de credores
- **Poderes do Administrador Judicial**: Fiscalização da atuação dos administradores da sociedade

### Referências legais
- Art. 64 da Lei X

### Dicas de prova
- Distinção entre o papel do administrador judicial e os administradores da sociedade
- Importância da fiscalização no processo de recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.212 (2)", "page_number": 212, "discipline": "Direito Empresarial", "legal_refs": ["Art. 64 da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:21:59.550823+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=212", "doc_key": "164b527030bc643ccf1486bb9a6289a1"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '31dfae0160c4d8fedb5ef88bcb995b10f8ece2adcf5c50908f23b59cd3fb60ac'),
  ('cpiuris2025::6857b1a5c2ff37da70e90092fc514126', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Judicial e Fiscalização do Administrador Judicial', '## Recuperação Judicial e Fiscalização do Administrador Judicial

O administrador judicial tem competência para fiscalizar o decurso das tratativas e a regularidade das negociações entre devedor e credores, garantindo que os expedientes adotados sejam benéficos ao andamento das negociações.

### Conceitos
- **Administrador Judicial**: Ente responsável pela fiscalização do decurso das tratativas e a regularidade das negociações entre devedor e credores em recuperação judicial.
- **Recuperação Judicial**: Procedimento jurídico que visa reestruturar as dívidas do devedor com os credores, garantindo a continuidade das atividades econômicas.
- **Fiscalização**: Ação de controlar e monitorar o cumprimento das normas e regulamentos estabelecidos.

### Referências legais
- Art. 22 da Lei n.º 11.1017/2005

### Dicas de prova
- Distinção entre a aprovação do plano e a objeção de credores
- Importância da fiscalização do administrador judicial para garantir a regularidade das negociações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.213 (1)", "page_number": 213, "discipline": "Direito Empresarial", "legal_refs": ["Art. 22 da Lei n.º 11.1017/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:22:43.279365+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=213", "doc_key": "6857b1a5c2ff37da70e90092fc514126"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'df4bb377567fd92c7d781b54d966d6b448d0d02ec75ed3e3aed10b1b9c765859'),
  ('cpiuris2025::00a5be4108d710a71b235f90ae1557fe', 'doutrina', 'cp_iuris', 'Direito Empresarial — Parcelamento Tributário na Recuperação Judicial', '## Parcelamento Tributário na Recuperação Judicial

O parcelamento tributário é direito do contribuinte em recuperação judicial que conduz à regularidade fiscal. A ausência de legislação específica não pode ser atribuída ao contribuinte, mas sim ao legislador inerte.

### Conceitos
- **Parcelamento Tributário**: Prática de dividir o valor do crédito tributário em parcelas menores
- **Recuperação Judicial**: Procedimento processual que visa reestruturar a dívida de uma empresa em falência ou recuperação judicial
- **Direito do Contribuinte**: O direito conferido ao contribuinte para praticar o parcelamento tributário sem necessidade de legislação específica
- **Faculdade da Fazenda Pública**: A opção da Fazenda Pública em oferecer parcelamento tributário aos devedores em recuperação judicial
- **Certidão Negativa de Débitos**: Documento que confirma a ausência de débitos tributários
- **Certidão Positiva com Efeitos Negativos**: Documento que confirma o parcelamento do crédito tributário, mas com efeitos negativos para a empresa
- **Exigibilidade do Crédito Tributário**: O direito do Estado de exigir o pagamento do crédito tributário

### Referências legais
- Art. 57 da Lei n.º 11.101/2005
- Art. 191-A do CTN

### Jurisprudência
- RE 123456
- Enunciado 55 das Jornadas de Direito Comercial

### Dicas de prova
- Entenda o conceito de parcelamento tributário e sua relação com a recuperação judicial
- Conheça as diferenças entre certidão negativa e positiva em relação ao parcelamento tributário
- Aprenda a distinguir entre direito do contribuinte e faculdade da Fazenda Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.213 (2)", "page_number": 213, "discipline": "Direito Empresarial", "legal_refs": ["Art. 57 da Lei n.º 11.101/2005", "Art. 191-A do CTN"], "jurisprudence": ["RE 123456", "Enunciado 55 das Jornadas de Direito Comercial"], "confidence": 0.8, "extracted_at": "2026-05-27T05:23:25.628727+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=213", "doc_key": "00a5be4108d710a71b235f90ae1557fe"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b8610f90a902efc26a15c5883803c26244a664d0bcf36a24df759aeeb7c031b8'),
  ('cpiuris2025::45ee383713039e240e637b43cebab9cc', 'doutrina', 'cp_iuris', 'Direito Empresarial — Parcelamento Tributário na Recuperação Judicial', '## Parcelamento Tributário na Recuperação Judicial

A Lei n. 13.043/2014 estabeleceu o parcelamento tributário para devedores em recuperação judicial, permitindo a divisão de dívidas em até 120 parcelas mensais e consecutivas. A CND pode ser exigida após a regulamentação do parcelamento.

### Conceitos
- **CND**: Certidão Negativa de Débito
- **Parcelamento Tributário**: Divisão de dívidas em parcelas mensais e consecutivas para devedores em recuperação judicial
- **Recuperação Judicial**: Procedimento jurídico que permite a reorganização das dívidas de uma empresa em falência

### Referências legais
- Art. 43 da Lei n.º 13.043/2014
- Lei n.º 10.522/2002
- Lei n.º 14.112/2020

### Jurisprudência
- REsp 1187404/MT

### Dicas de prova
- Interpretar a decisão da corte especial do STJ sobre o tema
- Entender as circunstâncias que permitem ou não exigir a CND', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.214 (1)", "page_number": 214, "discipline": "Direito Empresarial", "legal_refs": ["Art. 43 da Lei n.º 13.043/2014", "Lei n.º 10.522/2002", "Lei n.º 14.112/2020"], "jurisprudence": ["REsp 1187404/MT"], "confidence": 0.8, "extracted_at": "2026-05-27T05:23:58.942473+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=214", "doc_key": "45ee383713039e240e637b43cebab9cc"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '64285cd1ee135227d2f50941176ba10f86f53727366f6521f242fb9de4946af1'),
  ('cpiuris2025::daee96b188a40b35bdaff7a7be336483', 'doutrina', 'cp_iuris', 'Direito Empresarial — Plano Especial de Recuperação Judicial', '## Plano Especial de Recuperação Judicial

O produtor rural pode apresentar plano especial de recuperação judicial desde que o valor da causa não exceda R$ 4.800.000,00 e cumpra com as condições estabelecidas no artigo 71.

### Conceitos
- **Plano Especial de Recuperação Judicial**: projeto para a recuperação da empresa
- **Credores não atingidos**: creditores que não são afetados pelo plano especial
- **Parcelamento**: divisão do valor das dívidas em parcelas mensais
- **Taxa SELIC**: taxa de juros aplicada ao parcelamento
- **Autorização judicial**: necessidade de autorização para aumentar despesas ou contratar empregados

### Referências legais
- Art. 51 da Lei
- Art. 53 da Lei
- Art. 49 §3º e 4º
- Art. 70-A

### Dicas de prova
- Entenda a diferença entre plano especial de recuperação judicial e plano geral.
- Conheça as condições estabelecidas no artigo 71 para o plano especial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.214 (2)", "page_number": 214, "discipline": "Direito Empresarial", "legal_refs": ["Art. 51 da Lei", "Art. 53 da Lei", "Art. 49 §3º e 4º", "Art. 70-A"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:24:38.789282+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=214", "doc_key": "daee96b188a40b35bdaff7a7be336483"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ed7ee13a53b603c50ff5516e4fbba510c2f6180975ae801b0caaed84078edb81'),
  ('cpiuris2025::31a087493aca763e65e30c406097adea', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Judicial e Falência', '## Recuperação Judicial e Falência

O pedido de recuperação judicial com base em plano especial não suspende a prescrição nem as ações e execuções por créditos não abrangidos pelo plano.

### Conceitos
- **Recuperação Judicial**: Processo em que o devedor apresenta um plano para reestruturar suas dívidas
- **Falência**: Condição em que o devedor não tem mais recursos para pagar suas dívidas
- **Plano Especial**: Projeto apresentado pelo devedor para reestruturar suas dívidas
- **Prescrição**: Período após o qual uma ação não pode ser iniciada

### Referências legais
- Art. 72 da Lei nº 11.101/2005
- Súmula 373 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Recuperação Judicial e Falência

### Dicas de prova
- Distinção entre a recuperação judicial e a falência
- Importância do plano especial na recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.215 (1)", "page_number": 215, "discipline": "Direito Empresarial", "legal_refs": ["Art. 72 da Lei nº 11.101/2005", "Súmula 373 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Recuperação Judicial e Falência"], "confidence": 0.8, "extracted_at": "2026-05-27T05:25:10.402003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=215", "doc_key": "31a087493aca763e65e30c406097adea"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '6f36344ebbcdb03371836fa4d195c4e660739d1d247bc4558b61a5970b6961f4'),
  ('cpiuris2025::16de7acf1fc093f119cc58a9cc96ab1e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Judicial e Extraconcursualidade', '## Recuperação Judicial e Extraconcursualidade

A recuperação judicial concede benefícios a credores que continuam contratando com a sociedade em recuperação, incluindo a consideração de créditos extraconcursais.

### Conceitos
- **Recuperação Judicial**: Processo falimentar que visa reestruturar as dívidas da empresa
- **Extraconcursualidade**: Créditos considerados fora do processo concursal de falência

### Referências legais
- Art. 15, § 3º, da Lei n.º 11.101/2005

### Dicas de prova
- Entenda a diferença entre concursais e extraconcursais
- Conheça o conceito de ''bemesse'' concedida em prol de credores que continuam contratando com a sociedade em recuperação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.215 (2)", "page_number": 215, "discipline": "Direito Empresarial", "legal_refs": ["Art. 15, § 3º, da Lei n.º 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:25:33.589681+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=215", "doc_key": "16de7acf1fc093f119cc58a9cc96ab1e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8c7bc49793bb50ac35cb8f1051e63ca45170aa3ede33b5f6c003e30e553f83e7'),
  ('cpiuris2025::8128c95dae2ae0385b4869cdfce1015c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Benefícios aos Créditos em Recuperação Judicial', '## Benefícios aos Créditos em Recuperação Judicial

O benefício de privilégio geral para os créditos integralmente quirografários foi revogado, e passou a ser equiparado aos quirografários. Além disso, o plano de recuperação judicial pode prever tratamento diferenciado para os créditos sujeitos à recuperação judicial pertencentes a fornecedores de bens ou serviços.

### Conceitos
- **quirografia**: relação jurídica que não é garantida por uma hipoteca ou outro tipo de garantia
- **privilégio geral**: direito especial que concede prioridade ao pagamento de um crédito em relação a outros
- **recuperação judicial**: procedimento jurídico que visa reestruturar as dívidas de uma empresa em dificuldade
- **plano de recuperação judicial**: projeto apresentado pela empresa para reestruturar suas dívidas e sair da recuperação judicial

### Referências legais
- Art. 67, parágrafo único, da LFRE

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre privilégio geral e quirografia
- Conheça as novas regras de conciliação e mediação em procedimentos de recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.216 (1)", "page_number": 216, "discipline": "Direito Empresarial", "legal_refs": ["Art. 67, parágrafo único, da LFRE"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T05:26:18.517539+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=216", "doc_key": "8128c95dae2ae0385b4869cdfce1015c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '611fc559355ba7d871551a1c9e35691ba12d7a998a5350675cf206d51f997f57'),
  ('cpiuris2025::de196655fcffdb9727b630ebabd39f8b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recepção e Aplicação da Recuperação Judicial em Empresas em Dificuldade', '## Recepção e Aplicação da Recuperação Judicial em Empresas em Dificuldade

Regulamenta a aplicação da recuperação judicial em empresas em dificuldade, incluindo a conciliação e mediação com credores.

### Conceitos
- **Recuperação Judicial**: Procedimento jurídico que visa reestruturar as dívidas de uma empresa em dificuldade
- **Conflitos entre concessionárias e permissionárias**: Situações em que empresas concessionárias ou permissionárias de serviços públicos entram em conflito
- **Créditos extraconcursais**: Dívidas não incluídas no processo de recuperação judicial
- **Negociação de dívidas**: Procedimento para resolver dívidas entre empresa e credores antes do ajuizamento de pedido de recuperação judicial
- **Tutela de urgência cautelar**: Medida provisória que suspende as execuções contra a empresa em dificuldade
- **Código de Processo Civil**: Lei que regula o processo civil no Brasil
- **Câmara especializada**: Órgão do tribunal competente que processa e julga casos específicos

### Referências legais
- Art. 305 da Lei n.º 13.105/2015
- Súmula 416 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Recuperação Judicial em Empresas em Dificuldade

### Dicas de prova
- Entenda a diferença entre recuperação judicial e negociação de dívidas
- Conheça os critérios para a conciliação e mediação com credores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.216 (2)", "page_number": 216, "discipline": "Direito Empresarial", "legal_refs": ["Art. 305 da Lei n.º 13.105/2015", "Súmula 416 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Recuperação Judicial em Empresas em Dificuldade"], "confidence": 0.8, "extracted_at": "2026-05-27T05:26:57.689794+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=216", "doc_key": "de196655fcffdb9727b630ebabd39f8b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '350e844bf4d2fb7491670917567eedb9e77e9454f1761b45ee1c4b74aec5bb51'),
  ('cpiuris2025::ba9edb149ae78cda09dc0a6f9a29c1de', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falência e Recuperação Judicial', '## Falência e Recuperação Judicial

A falência é um processo de execução concursal voltado contra um devedor empresário insolvente, com o objetivo de apurar passivo e ativo. A lei n.º 11.101/05 preservou a empresa permitindo a recuperação.

### Conceitos
- **Falência**: Processo de execução concursal voltado contra um devedor empresário insolvente
- **Recuperação Judicial**: Procedimento que visa preservar a empresa e permitir a recuperação do devedor
- **Devedor Empresário**: Pessoa jurídica ou física que está insolvente e precisa ser executada concursally
- **Credor**: Pessoa que tem direito a receber uma parte do passivo do devedor

### Referências legais
- Art. 20-C da Lei n.º 11.101/05
- Súmula 345 STF

### Jurisprudência
- RE 123456
- Tema Falência e Recuperação Judicial

### Dicas de prova
- Entenda a diferença entre execução individual e concursal
- Conheça os pressupostos da falência (devedor, estado de insolvência e sentença)
- Avalie a importância da recuperação judicial na preservação da empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.217 (1)", "page_number": 217, "discipline": "Direito Empresarial", "legal_refs": ["Art. 20-C da Lei n.º 11.101/05", "Súmula 345 STF"], "jurisprudence": ["RE 123456", "Tema Falência e Recuperação Judicial"], "confidence": 0.8, "extracted_at": "2026-05-27T05:27:38.662310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=217", "doc_key": "ba9edb149ae78cda09dc0a6f9a29c1de"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '11353f54f94d2cac09a55866272b808973287471c0677ac3a37b9494401fd60e'),
  ('cpiuris2025::f0f8aec46737b0a3794ce9df0f82ddff', 'doutrina', 'cp_iuris', 'Direito Empresarial — Processo Falimentar', '## Processo Falimentar

Resumo do processo falimentar, incluindo as etapas pré-falencial e falencial.

### Conceitos
- **Falência**: Situação jurídica em que o devedor empresário é considerado insolvente.
- **Decretação da Falência**: Ato pelo qual a sentença declaratória de falência é proferida.
- **Etapa Pré-falencial**: Fase do processo em que o pedido de falência é apresentado.
- **Etapa Falencial**: Fase do processo em que a decretação da falência ocorre.
- **Devedor Empresário**: Pessoa jurídica que pode ser declarada falente.
- **Devedor Não Empresário**: Pessoa jurídica que não pode ser declarada falente.

### Referências legais
- Art. 11.101/2005
- Art. 748/CPC/73

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre devedor empresário e não empresário.
- Conheça as etapas do processo falimentar: pré-falencial, falencial e encerramento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.217 (2)", "page_number": 217, "discipline": "Direito Empresarial", "legal_refs": ["Art. 11.101/2005", "Art. 748/CPC/73"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T05:28:19.099763+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=217", "doc_key": "f0f8aec46737b0a3794ce9df0f82ddff"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '77cf025ca937b36bc1022205cead8d898afffe6602c1d3e3468f850cf1b2ec96'),
  ('cpiuris2025::584e421cc4476e8e8a8f23286e853748', 'doutrina', 'cp_iuris', 'Direito Empresarial — Competência e Legitimados a Pedir Falência', '## Competência e Legitimados a Pedir Falência

A competência para o processo de falência é do juízo do local do principal estabelecimento da empresa, mas pode ser alterada pelo critério econômico. Existem exceções, como ações não reguladas pela lei falimentar e execuções tributárias.

### Conceitos
- **Competência**: A competência é o órgão judiciário responsável por julgar um processo.
- **Legitimados a Pedir Falência**: São as partes que podem requerer a falência do devedor, incluindo o próprio devedor, cônjuge sobrevivente, herdeiro, inventariante e credores.
- **Juízo da Falência**: O órgão judiciário responsável por julgar o processo de falência.
- **Exceções à Competência**: Ações não reguladas pela lei falimentar, reclamação trabalhista, execuções tributárias e ações que envolvem a União ou quantia ilíquida.

### Referências legais
- Art. 97 da LFRE
- Art. 105 a 107 da LFRE

### Dicas de prova
- Entenda a competência e as exceções à competência.
- Conheça os legitimados a pedir falência.
- Avalie a importância do juízo da falência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.218 (1)", "page_number": 218, "discipline": "Direito Empresarial", "legal_refs": ["Art. 97 da LFRE", "Art. 105 a 107 da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:28:55.976211+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=218", "doc_key": "584e421cc4476e8e8a8f23286e853748"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3eeafd0cb701d63c3810a051fe7b26371b11872f0d43f279aa4f2973a480f038'),
  ('cpiuris2025::71f306b6afc51a54545059a68f846b75', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falências e Recuperação Judicial', '## Falências e Recuperação Judicial

O credor deve prestar caução relativa às custas e ao pagamento da indenização em caso de não regularidade das atividades. A falência pode ser solicitada por sócios ou outros credores, com exceção da Fazenda Pública.

### Conceitos
- **Caução**: segurança oferecida pelo devedor para garantir o cumprimento de obrigações
- **Falência**: processo judicial que visa dissolver a sociedade e distribuir seus ativos entre os credores
- **Indenização**: sombra financeira que se forma sobre o valor real do débito devido ao credor
- **Legitimidade**: qualidade jurídica que permite agir em um processo ou negócio jurídico
- **Interesse de Agir**: motivo pelo qual alguém tem direito a agir em um processo ou negócio jurídico
- **Credor**: parte que tem direito a ser indenizada por uma obrigação de alguém
- **Sociedade**: entidade jurídica que pode ser responsável por dívidas e obrigações

### Referências legais
- Art. 101 da Lei nº X
- Súmula N do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre falências

### Dicas de prova
- Entenda a diferença entre autofalência e falência de sócios
- Conheça as exigências para a Fazenda Pública agir em um processo de falência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.218 (2)", "page_number": 218, "discipline": "Direito Empresarial", "legal_refs": ["Art. 101 da Lei nº X", "Súmula N do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre falências"], "confidence": 0.8, "extracted_at": "2026-05-27T05:29:30.938041+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=218", "doc_key": "71f306b6afc51a54545059a68f846b75"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '235d0ea7ed3f0ea8143d904971653292e4d5f5f8245456eae83b7c23164ab9cc'),
  ('cpiuris2025::0c72dd4930f48fa5ce3912520c9b1c76', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falência e Recuperacional', '## Falência e Recuperacional

A Fazenda Pública não possui legitimidade para requerer a falência do devedor empresário, exceto se o credor for estrangeiro ou não é empresário. A insolvência jurídica é presunvida se caracterizam situações específicas.

### Conceitos
- **Legitidade para requerer a falência**: O direito de agir para requerer a falência do devedor empresário
- **Insolvência jurídica**: Presunção de insolvência do devedor, não necessariamente correspondendo à real ou econômica
- **Credores estrangeiros**: Deverão prestar caução relativa às custas e eventual indenização se houver agido com dolo
- **Autofalência**: O devedor pode requerer a autofalência, mas não pode pedir a falência do seu próprio devedor

### Referências legais
- Art. 748 do CPC/73
- Lei n.º 6.380/1980 (Lei de Execuções Fiscais)

### Jurisprudência
- Enunciado 56 das Jornadas de Direito Comercial do CJF

### Dicas de prova
- Diferenciar entre legitimidade e interesse de agir para requerer a falência
- Entender a diferença entre insolvência jurídica e real ou econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.219 (1)", "page_number": 219, "discipline": "Direito Empresarial", "legal_refs": ["Art. 748 do CPC/73", "Lei n.º 6.380/1980 (Lei de Execuções Fiscais)"], "jurisprudence": ["Enunciado 56 das Jornadas de Direito Comercial do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T05:30:18.968770+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=219", "doc_key": "0c72dd4930f48fa5ce3912520c9b1c76"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '84f888133f7609ca13775dccc04620409d5e3b814e0f9b5ab41ab778ef6bd7ae'),
  ('cpiuris2025::baab133031749357f508de70f712f4a3', 'doutrina', 'cp_iuris', 'Direito Empresarial — Hipóteses de Insolvência Jurídica para fins falimentares', '## Hipóteses de Insolvência Jurídica para fins falimentares

As hipóteses de insolvência jurídica para fins falimentares são previstas no art. 94 da LFRE e incluem não pagamento de obrigações líquidas, falta de nomeação de bens à penhora e prática de atos que impedem a recuperação judicial.

### Conceitos
- **Insolvência Jurídica**: Condição em que o devedor não tem recursos suficientes para pagar suas obrigações
- **Falência**: Processo em que é declarada a insolvência do devedor
- **Obrigação Líquida**: Obrigatoriedade de pagamento de uma obrigação com valor certo e determinado
- **Título Executivo**: Documento que certifica o valor de uma obrigação líquida

### Referências legais
- Art. 94 da LFRE

### Jurisprudência
- 13 REsp 164.389/MG
- 14 REsp 733.060

### Dicas de prova
- Entenda a definição de insolvência jurídica e como ela afeta o processo falimentar.
- Conheça as hipóteses previstas no art. 94 da LFRE para fins falimentares.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.219 (2)", "page_number": 219, "discipline": "Direito Empresarial", "legal_refs": ["Art. 94 da LFRE"], "jurisprudence": ["13 REsp 164.389/MG", "14 REsp 733.060"], "confidence": 0.8, "extracted_at": "2026-05-27T05:30:47.293626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=219", "doc_key": "baab133031749357f508de70f712f4a3"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b22e3a2c7a7bfca349c7b5ade8e05ef5eecc96fbca417dc978b45002d0c59b91'),
  ('cpiuris2025::740005786fe2b5abdd96b755581a22c6', 'doutrina', 'cp_iuris', 'Direito Empresarial — Impontualidade injustificada em falências', '## Impontualidade injustificada em falências

A impontualidade injustificada é a hipótese do inciso I do art. 94, caracterizada pela falta de razão relevante para não pagar dívida no vencimento. A jurisprudência criou um requisito de insuficiência do devedor com base na dívida.

### Conceitos
- **Impontualidade**: Falta de pagamento de dívida sem razão relevante
- **Injustificada**: Sem fundamento legal ou jurídico para não pagar dívida no vencimento
- **Insolvência**: Situação em que o devedor não tem recursos suficientes para pagar suas dívidas
- **Patamar mínimo da dívida**: Valor mínimo da dívida para caracterizar a insolvência do devedor (40 salários mínimos)

### Referências legais
- Art. 94, inciso I, Lei n.º 11.101/2005

### Jurisprudência
- REsp 1433652/RJ
- Súmula 346 STJ

### Dicas de prova
- Entenda a diferença entre impontualidade e injustificada
- Conheça o patamar mínimo da dívida para caracterizar a insolvência do devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.220 (1)", "page_number": 220, "discipline": "Direito Empresarial", "legal_refs": ["Art. 94, inciso I, Lei n.º 11.101/2005"], "jurisprudence": ["REsp 1433652/RJ", "Súmula 346 STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T05:31:21.817758+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=220", "doc_key": "740005786fe2b5abdd96b755581a22c6"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b556290fdb3a0f0bea7cdc6c7740472e4e33abd7efad18bcccdf2ffe82f1c255'),
  ('cpiuris2025::5bef2f34a625f31396a907951bbdf1f7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos para a declaração da falência', '## Requisitos para a declaração da falência

Para a declaração da falência, é necessário que haja impontualidade injustificada, com obrigações líquidas e valor superior a 40 salários-mínimos na data da falência.

### Conceitos
- **Impontualidade**: Falta de pagamento ou não cumprimento de obrigação
- **Obrigação líquida**: Obrigação que pode ser liquidada em dinheiro
- **Protesto especial**: Protesto realizado para fins falimentares, com valor superior a 40 salários-mínimos
- **Litisconsórcio**: Reunião de credores para alcançar o valor mínimo exigido para a declaração da falência
- **Execução frustrada**: Frustramento da execução, caracterizado pela não pagamento, não depósito ou não nomeação de bens suficientes

### Referências legais
- Art. 94, §3º e §1º, da LFRE
- Art. 5º, I e II, da LFRE

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre impontualidade injustificada e outras formas de atraso
- Entender o conceito de obrigação líquida e seu valor mínimo para a declaração da falência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.220 (2)", "page_number": 220, "discipline": "Direito Empresarial", "legal_refs": ["Art. 94, §3º e §1º, da LFRE", "Art. 5º, I e II, da LFRE"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T05:32:04.961947+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=220", "doc_key": "5bef2f34a625f31396a907951bbdf1f7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '089d6058bace86eddd360dafbda98eb9835332f3c66b17a24fc43f76088459e9'),
  ('cpiuris2025::d56ef2cc4e61f646ea50f6553a33ffd7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Prática de atos de falência', '## Prática de atos de falência

O credor pode ingressar com pedido de falência sem necessidade de título protestado ou valor superior a 40 salários-mínimos, desde que apresente certidão judicial trazendo tríplice omissão. São comportamentos que denotam insolvência do devedor e estão previstos no inciso III do art. 94 da LFRE.

### Conceitos
- **Autofalência**: O próprio devedor pede a sua falência, instruindo-a com balanço patrimonial, relação de credores e o seu contrato social.
- **Tríplice omissão**: Certidão judicial que apresenta as três omissões: dívida vencida, insolvência do devedor e falta de bens suficientes para saldar o passivo.
- **Citação do empresário devedor**: O rito prevê a citação do empresário devedor para que ele se manifeste no prazo de 10 dias.
- **Contestação**: O devedor pode apresentar contestação no prazo da citação, depositando o valor correspondente ao total do passivo.
- **Liquidação precipitada**: Procedimento que envolve a liquidação rápida dos ativos do devedor para realizar pagamentos.
- **Negócio simulado**: Ações realizadas pelo devedor com o objetivo de fraudar credores ou retardar pagamentos.
- **Alienação de parte ou da totalidade de seu ativo a terceiro**: Venda ou transferência de bens do devedor para um terceiro, sem consentimento de todos os credores.
- **Transferência de estabelecimento**: Mudança do local de atuação da empresa sem consentimento de todos os credores e sem bens suficientes para saldar o passivo.

### Referências legais
- Art. 94 da LFRE
- Art. 98 da Lei

### Dicas de prova
- Entenda a diferença entre autofalência e falência requerida por terceiros.
- Conheça as três omissões necessárias para o pedido de falência.
- Aprenda a importância da citação do empresário devedor e do prazo para contestação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.221 (1)", "page_number": 221, "discipline": "Direito Empresarial", "legal_refs": ["Art. 94 da LFRE", "Art. 98 da Lei"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:33:00.988342+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=221", "doc_key": "d56ef2cc4e61f646ea50f6553a33ffd7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '421b7f7f7edbb9f9845797690b3f4c00658e9baad5e1fa02012530963fa9d45f'),
  ('cpiuris2025::755e8da46a3f0ed013676a4e77d9caae', 'doutrina', 'cp_iuris', 'Direito Empresarial — Depósito Elisivo e Falência', '## Depósito Elisivo e Falência

O depósito elisivo é uma estratégia defensiva que pode evitar a decretação da falência, pois comprova a não insolvência do devedor.

### Conceitos
- **Depósito Elisivo**: Depósito realizado pelo devedor em favor do credor para comprovar a não insolvência e evitar a decretação da falência.
- **Insolvência**: Condição em que o devedor não tem recursos suficientes para pagar as dívidas
- **Falência**: Processo judicial que visa liquidar os ativos do devedor e pagar as dívidas

### Referências legais
- Art. 183 da Lei nº 11.101/2005

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Distinção entre depósito elisivo e depósito em favor do credor
- Importância da comprovação de não insolvência para evitar a decretação da falência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.221 (2)", "page_number": 221, "discipline": "Direito Empresarial", "legal_refs": ["Art. 183 da Lei nº 11.101/2005"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T05:33:28.849173+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=221", "doc_key": "755e8da46a3f0ed013676a4e77d9caae"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '992e8ed25aee43b4bcf489b73da23de7ec1c150ce603394c4cfe9046b6afb5e4'),
  ('cpiuris2025::7f7a373adfcd5c3d1c7ae610436f1dfe', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sentença declaratória de falência e seus requisitos', '## Sentença declaratória de falência e seus requisitos

A sentença declaratória de falência é a segunda etapa do processo de falência, com requisitos como fixação do termo legal da falência, suspensão de execuções e habilitações de crédito.

### Conceitos
- **Sentença declaratória**: Decisão do juiz que declara a falência do devedor
- **Termo legal da falência**: Prazo dentro do qual o devedor pode ser considerado falido
- **Suspensão de execuções**: Mudança no prazo prescricional contra o devedor da falência
- **Habilitações de crédito**: Período durante o qual o devedor pode receber créditos

### Referências legais
- Art. 99 da Lei n.º 11.101/2005

### Jurisprudência
- Informativo 653 do STJ

### Dicas de prova
- Diferenciar entre suspensão de execuções e prazo prescricional
- Entender a importância da fixação do termo legal da falência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.222 (1)", "page_number": 222, "discipline": "Direito Empresarial", "legal_refs": ["Art. 99 da Lei n.º 11.101/2005"], "jurisprudence": ["Informativo 653 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T05:34:12.207887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=222", "doc_key": "7f7a373adfcd5c3d1c7ae610436f1dfe"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'dd532d21598f88f39dfe89e46f31df6580499617dac62aaf50f7df3b4c826bd9'),
  ('cpiuris2025::b5e1c10715256b00863c92de6fdfe0e3', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falência e Processo Falimentar', '## Falência e Processo Falimentar

A decretação da falência não implica a extinção da personalidade jurídica da sociedade, permitindo que ela atue como assistente nas ações em que a massa falida seja parte ou interessada.

### Conceitos
- **Falência**: Processo judicial que visa liquidar as dívidas de uma empresa
- **Personalidade jurídica**: Estado de direito em que uma pessoa jurídica é considerada como um ente jurídico autônomo
- **Assistente**: Parte que representa os interesses de outra parte em um processo
- **Prescrição**: Período durante o qual uma ação não pode ser iniciada por falta de tempo

### Referências legais
- Art. 6º da Lei Federal de Regulação Fiscal Empresarial (LFRE)

### Dicas de prova
- Entenda a diferença entre sentença declaratória e constitutiva em processo falimentar
- Conheça as consequências da decretação da falência para a empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.222 (2)", "page_number": 222, "discipline": "Direito Empresarial", "legal_refs": ["Art. 6º da Lei Federal de Regulação Fiscal Empresarial (LFRE)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:34:38.292697+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=222", "doc_key": "b5e1c10715256b00863c92de6fdfe0e3"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '9f9b407d12a5cbd8db9e53ff72867433a9dba39e760bc0f5abbfbc68b0fa99d7'),
  ('cpiuris2025::18013d3259ff438bfaa65cc12c81c22e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Suspensão das execuções e proibição de retenção em recuperação judicial ou falência', '## Suspensão das execuções e proibição de retenção em recuperação judicial ou falência

Regra que suspende as execuções ajuizadas contra o devedor, inclusive dos credores solidários, e proíbe qualquer forma de retenção sobre os bens do devedor em demandas judiciais ou extrajudiciais relacionadas à recuperação judicial ou falência.

### Conceitos
- **Recuperação Judicial**: Processo que visa liquidar as dívidas de uma empresa em falência.
- **Falência**: Estado jurídico da insolvência de uma empresa.
- **Suspensão das execuções**: Prazo durante o qual não se pode executar a sentença.
- **Proibição de retenção**: Restrição à possibilidade de reter bens do devedor em demandas judiciais ou extrajudiciais.

### Referências legais
- Art. 6º da LFRE
- Súmula 456/STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre suspensão das execuções e proibição de retenção em recuperação judicial ou falência.
- Conheça o entendimento do STJ sobre a remessa do produto arrecadado ao juízo universal da falência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.223 (1)", "page_number": 223, "discipline": "Direito Empresarial", "legal_refs": ["Art. 6º da LFRE", "Súmula 456/STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T05:35:13.385263+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=223", "doc_key": "18013d3259ff438bfaa65cc12c81c22e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2d5a7d1088e9e2dcba84d404eddc7bdeec92becd6f7c2d897c5ddc6d9490739d'),
  ('cpiuris2025::f501a9003596fb295048d22a61b7df3d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falência Superveniente e Execução Fiscal', '## Falência Superveniente e Execução Fiscal

A falência superveniente não pode paralisar a execução fiscal ou desconstituir penhora anterior. O produto da alienação judicial dos bens penhorados deve ser repassado ao juiz universal da falência.

### Conceitos
- **Falência Superveniente**: Ocorre após a decretação da falência
- **Execução Fiscal**: Processo pelo qual o Estado busca cobrar dívidas
- **Penhora**: Medida processual que impede a alienação de bens do devedor
- **Massa Falida**: Entidade jurídica formada pela massa dos ativos do devedor falente

### Referências legais
- Art. 99, II, da LFRE

### Jurisprudência
- AgRg no REsp 1232440/SP
- AgRg no CC 129.400/SP

### Dicas de prova
- Entenda a diferença entre falência superveniente e execução fiscal
- Conheça o papel do juiz universal da falência na repassação de valores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.223 (2)", "page_number": 223, "discipline": "Direito Empresarial", "legal_refs": ["Art. 99, II, da LFRE"], "jurisprudence": ["AgRg no REsp 1232440/SP", "AgRg no CC 129.400/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T05:35:54.059772+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=223", "doc_key": "f501a9003596fb295048d22a61b7df3d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'bed3ed9cc7f8d782a18606f84ddd32accf96b6b4cc1df7d4fa2ab5465166b275'),
  ('cpiuris2025::aca0fea83571eca5ab6ad6aa03aa0b70', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falência e Recuperação Judicial', '## Falência e Recuperação Judicial

Discute-se a petição inicial do requerimento de falência, o requerimento de recuperação judicial e as consequências da sentença que decreta a falência.

### Conceitos
- **Dolo**: Ação dolosa é aquela realizada com intenção de enganar ou prejudicar alguém.
- **Indenização**: Sob a forma de indenização, o devedor deve pagar ao credor as perdas e danos causados pela falência.
- **Administrador Judicial**: É o responsável por supervisionar a atuação do administrador judicial e realizar os atos necessários para a falência.
- **Assembleia de Credores**: É um órgão da falência que se reúne para decidir sobre as questões relacionadas à falência.
- **Comitê de Credores**: É outro órgão da falência que se reúne para discutir e decidir sobre as questões relacionadas à falência.

### Referências legais
- Art. 101 da Lei nº 11.1016/2005

### Dicas de prova
- Entenda a diferença entre petição inicial e requerimento de falência.
- Conheça as consequências do dolo na sentença que decreta a falência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.224", "page_number": 224, "discipline": "Direito Empresarial", "legal_refs": ["Art. 101 da Lei nº 11.1016/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:36:30.566879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=224", "doc_key": "aca0fea83571eca5ab6ad6aa03aa0b70"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '02db8d84627d190eaee9ddc2027cfaac63c1c4950a81831a342e5ff46ec7b1d4'),
  ('cpiuris2025::8e32e9be2a73e88a3c18922f87316017', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falência e Recuperação Judicial', '## Falência e Recuperação Judicial

O administrador judicial representa a massa falida subjetiva, composta pelos interesses dos credores, e pratica atos como verificação de créditos, elaboração do relatório inicial e prestação de contas mensais. A assembleia-geral de credores possui competências importantes na falência, incluindo aprovação da constituição do comitê de credores.

### Conceitos
- **Administrador Judicial**: Representante da massa falida subjetiva
- **Assembleia-Geral de Credores**: Órgão composto por todos os credores do falido
- **Comitê de Credores**: Órgão responsável pela gestão da massa falida
- **Quadro-Geral de Credores**: Elenco dos credores com seus respectivos créditos
- **Relatório Inicial**: Documento que descreve as causas e circunstâncias da falência
- **Prestação de Contas Mensais**: Obrigação do administrador judicial de apresentar contas ao juiz
- **Relatório Final**: Documento que descreve o levantamento do valor do ativo e do passivo

### Referências legais
- Art. 22 da Lei Federal de Falências e Recuperações Judiciais (LFRE)

### Dicas de prova
- Entenda a importância do administrador judicial na falência
- Conheça as competências da assembleia-geral de credores
- Aprenda sobre o comitê de credores e sua composição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.225", "page_number": 225, "discipline": "Direito Empresarial", "legal_refs": ["Art. 22 da Lei Federal de Falências e Recuperações Judiciais (LFRE)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:37:12.778240+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=225", "doc_key": "8e32e9be2a73e88a3c18922f87316017"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7422c84a57d9f6318894e881014d9f8f1da19d53283adf0eb28c5b1e857980b7'),
  ('cpiuris2025::f0591ce72e0879fee85f1165b0eb4ef7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Restrições pessoais ao falido', '## Restrições pessoais ao falido

A pessoa falida está sujeita a restrições pessoais, como não se ausentar sem motivo justo e comunicar o juiz, além de não poder se restabelecer como empresário até que as obrigações forem declaradas extintas.

### Conceitos
- **Capacidade jurídica**: A capacidade de uma pessoa para exercer direitos e contrair obrigações
- **Falência**: O estado jurídico em que um devedor não tem mais meios para pagar suas dívidas
- **Restrição pessoal**: Limitação das liberdades de uma pessoa, especialmente no que tange à sua atividade profissional

### Referências legais
- Art. 104, III do Código de Processo Civil
- Art. 22, III, "d" do Código de Processo Civil
- Art. 102 do Código de Processo Civil
- Art. 158 do Código de Processo Civil
- Art. 181, § 1º do Código de Processo Civil

### Jurisprudência
- Súmula 346/STJ

### Dicas de prova
- Entenda a capacidade jurídica do falido e as restrições pessoais impostas pela lei
- Conheça as hipóteses de continuação provisória da empresa do falido
- Avalie a importância da declaração da extinção das obrigações para a reabilitação do falido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.226 (1)", "page_number": 226, "discipline": "Direito Empresarial", "legal_refs": ["Art. 104, III do Código de Processo Civil", "Art. 22, III, \"d\" do Código de Processo Civil", "Art. 102 do Código de Processo Civil", "Art. 158 do Código de Processo Civil", "Art. 181, § 1º do Código de Processo Civil"], "jurisprudence": ["Súmula 346/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T05:38:01.106845+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=226", "doc_key": "f0591ce72e0879fee85f1165b0eb4ef7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e574a4820d2e8f70941120159a82bd2fed502c2bc72d9e452fa8d278f590b015'),
  ('cpiuris2025::55d03484ece8e4846c347be6f552d328', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falências e Recuperação de Ativos', '## Falências e Recuperação de Ativos

A continuação provisória da atividade após a falência pode ser excepcional e justificada pela relevância social e econômica. A arrecadação dos bens do devedor falido não se limita ao ativo existente no momento da decretação da falência.

### Conceitos
- **Falência**: Processo judicial que visa liquidar os bens e pagar as dívidas de um devedor
- **Atos ineficazes**: Ações realizadas pelo devedor antes da falência com o objetivo de evitar a arrecadação dos bens em processo falimentar
- **Massa falida**: Bens que são considerados parte do patrimônio do devedor falido e devem ser arrecadados no processo falimentar

### Referências legais
- Art. 183 da Lei nº 11.101/2005

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Entenda a diferença entre atos eficazes e ineficazes em relação à falência
- Conheça as regras para a arrecadação dos bens do devedor falido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.226 (2)", "page_number": 226, "discipline": "Direito Empresarial", "legal_refs": ["Art. 183 da Lei nº 11.101/2005"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T05:38:29.653193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=226", "doc_key": "55d03484ece8e4846c347be6f552d328"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3f87e6ddf285adeaf0ddcaf9df746934afcad092ade9b320b9705b88b2206f41'),
  ('cpiuris2025::845bcabb9567e1ffe2dcbb165324be2f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Atos ineficazes em sentido estrito', '## Atos ineficazes em sentido estrito

A lei define atos ineficazes em sentido estrito como aqueles que não produzem efeitos perante a massa falida, mesmo que sejam válidos para terceiros.

### Conceitos
- **Atos ineficazes**: Ações ou decisões que não produzem efeitos perante a massa falida
- **Massa falida**: O patrimônio do devedor que foi declarado falido
- **Termo legal**: O prazo dentro do qual o devedor pode realizar certos atos sem afetar a massa falida

### Referências legais
- Art. 129 da LFRE

### Dicas de prova
- Entenda a diferença entre atos ineficazes em sentido estrito e revogáveis
- Conheça as condições exigidas para que um ato seja considerado ineficaz em sentido estrito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.227 (1)", "page_number": 227, "discipline": "Direito Empresarial", "legal_refs": ["Art. 129 da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:38:57.624309+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=227", "doc_key": "845bcabb9567e1ffe2dcbb165324be2f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b0fd6f95fa7939c611cc7b74487ddaf311e3ce8fa016f71c8ce8b7c01f16a33f'),
  ('cpiuris2025::7c10204d303a90131ce406f624a5cd28', 'doutrina', 'cp_iuris', 'Direito Empresarial — Ineficácia de Atos na Falência', '## Ineficácia de Atos na Falência

A ineficácia de atos em falência é declarada pelo juiz, alegada em defesa ou pleiteada mediante ação própria ou incidentalmente no curso do processo. É objetiva e independe da demonstração de conluio ou de intuito de fraudar credores.

### Conceitos
- **Ineficácia objetiva**: independe da demonstração de conluio ou de intuito de fraudar credores
- **Taxatividade do artigo 129**: as hipóteses de ineficácia são listadas no artigo 129 e não há outras exceções

### Referências legais
- Art. 129 da LFRE
- Art. 131 da LFRE

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre ineficácia objetiva e subjetiva
- Conheça o rol do artigo 129 e as hipóteses de ineficácia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.227 (2)", "page_number": 227, "discipline": "Direito Empresarial", "legal_refs": ["Art. 129 da LFRE", "Art. 131 da LFRE"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T05:39:33.336166+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=227", "doc_key": "7c10204d303a90131ce406f624a5cd28"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e21f6ec1af74a6c9442b1bcac26ce5a0a016620d869a45db0cb0cbc74ff5220a'),
  ('cpiuris2025::55cf7f00ab8c36a5d87e8e201e8fd452', 'doutrina', 'cp_iuris', 'Direito Empresarial — Ação Revocatória e Ineficácia em Falências', '## Ação Revocatória e Ineficácia em Falências

A ação revocatória pode ser proposta pelo administrador judicial, por credores ou pelo Ministério Público dentro de 3 anos da decretação da falência. A ineficácia pode ser declarada de ofício, em defesa ou pleiteada mediante ação própria.

### Conceitos
- **Ação Revocatória**: Procedimento que visa anular atos prejudiciais à massa falida
- **Ineficácia**: Declaração judicial que anula a eficácia de um ato ou contrato
- **Falência**: Estado jurídico em que o devedor perde a capacidade de pagar suas dívidas
- **Massa Falida**: Bens e direitos do devedor que são submetidos à administração judicial

### Referências legais
- Art. 117 da LFRE
- Art. 118 da LFRE
- Art. 129 da LFRE
- Art. 130 da LFRE
- Art. 132 da LFRE

### Dicas de prova
- Entenda a diferença entre ineficácia objetiva e subjetiva
- Conheça os atos revogáveis em falências
- Ação revocatória: quem pode propô-la e como', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.228", "page_number": 228, "discipline": "Direito Empresarial", "legal_refs": ["Art. 117 da LFRE", "Art. 118 da LFRE", "Art. 129 da LFRE", "Art. 130 da LFRE", "Art. 132 da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:40:12.274821+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=228", "doc_key": "55cf7f00ab8c36a5d87e8e201e8fd452"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e953a4d06ab580d457de118eb3af7c7b747db69145f55a6db6766a2a52ff0325'),
  ('cpiuris2025::fd401b6ae40ea841f655c62d67458422', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falência e Recuperação', '## Falência e Recuperação

A falência pode afetar contratos, incluindo a continuidade ou não do contrato, resolução por falência, créditos de moeda estrangeira e mandato cesado.

### Conceitos
- **Declaração negativa**: A declaração negativa do administrador judicial sobre a continuidade ou não do contrato
- **Silêncio do administrador**: O silêncio do administrador judicial no prazo de 10 dias após a interpelação confere resolução do contrato
- **Crédito quirografário**: O valor da indenização, apurado em processo ordinário, constituirá crédito quirografário
- **Falência e contratos**: A falência pode afetar a continuidade ou não do contrato, resolução por falência e outros efeitos

### Referências legais
- Art. 119, I
- Art. 119, III
- Art. 119, IV
- Art. 119, VII
- Art. 120
- Art. 77

### Dicas de prova
- Pegar a declaração negativa e o silêncio do administrador como evidências de resolução do contrato
- Entender que o crédito quirografário é o valor da indenização apurado em processo ordinário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.229 (1)", "page_number": 229, "discipline": "Direito Empresarial", "legal_refs": ["Art. 119, I", "Art. 119, III", "Art. 119, IV", "Art. 119, VII", "Art. 120", "Art. 77"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:40:48.457016+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=229", "doc_key": "fd401b6ae40ea841f655c62d67458422"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '34061df0952f2731b003a73ffd04696ba0f13c19b9de6792603b9dddcf04515e'),
  ('cpiuris2025::146d692212cc3c709d830f3c41138958', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falência e Prescrição', '## Falência e Prescrição

O mandato de representação judicial do devedor continua vigente até que seja revogado pelo administrador judicial. A prescrição das obrigações do falido é suspensa, mas só volta a correr com o trânsito em julgado da decisão que encerra a falência.

### Conceitos
- **Prescrição**: O processo pelo qual uma obrigação se torna inexigível
- **Falência**: O estado jurídico de um devedor que não tem mais recursos para atender às suas obrigações
- **Mandato**: A autorização de alguém para agir em nome de outro
- **Credor**: Pessoa que tem direito a receber uma obrigação de alguém

### Referências legais
- Art. 120, § 1º do Código de Processo Civil

### Dicas de prova
- Distinguir entre prescrição suspensa e prescrição intransponível
- Entender a diferença entre mandato e autorização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.229 (2)", "page_number": 229, "discipline": "Direito Empresarial", "legal_refs": ["Art. 120, § 1º do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:41:24.544446+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=229", "doc_key": "146d692212cc3c709d830f3c41138958"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '776d24476cbf97ee89486529f3a6b6dac7d9afcf229dae25e91cea0d18a8424b'),
  ('cpiuris2025::b90c8b04f0a7efd9e6142d6fb0a5465e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Efeitos da falência quanto aos credores', '## Efeitos da falência quanto aos credores

A falência tem quatro principais efeitos: formação da massa falida subjetiva, suspensão das ações individuais contra o falido, vencimento antecipado das dívidas e suspensão da fluência dos juros.

### Conceitos
- **Massa falida subjetiva**: Sujeito de direito despersonalizado que atua no interesse dos credores gerais
- **Suspensão das ações individuais contra o falido**: Medida que impede que sigam em curso ações individuais contra o devedor após a decretação da falência
- **Vencimento antecipado das dívidas**: Paga integralidade dos créditos do devedor
- **Suspensão da fluência dos juros**: Não há mais juros sobre as dívidas do devedor após a decretação da falência

### Referências legais
- Art. 6º da Lei n.º 11.101/05

### Jurisprudência
- REsp 1564021/MG
- Súmula 345 do STF

### Dicas de prova
- Diferenciar entre suspensão e extinção das ações individuais contra o falido
- Entender que a suspensão é definitiva após a decretação da falência
- Conhecer as hipóteses em que a suspensão não é aplicável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.230", "page_number": 230, "discipline": "Direito Empresarial", "legal_refs": ["Art. 6º da Lei n.º 11.101/05"], "jurisprudence": ["REsp 1564021/MG", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T05:42:04.170746+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=230", "doc_key": "b90c8b04f0a7efd9e6142d6fb0a5465e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'de1e8b485f85b9e74e98afaa39e92e54d8762ab042910213bfaaf2c22f0eebf9'),
  ('cpiuris2025::f0a9eaebbfb2e966ffe4b0612699142c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Vencimento antecipado das dívidas e Suspensão da fluência dos juros', '## Vencimento antecipado das dívidas e Suspensão da fluência dos juros

O art. 77 da LFRE determina o vencimento antecipado das dívidas do devedor e dos sócios ilimitada e solidariamente responsáveis, com abatimento proporcional dos juros. Além disso, a quebra implica suspensão da fluência dos juros, com exceções como as obrigações com garantia real.

### Conceitos
- **Vencimento antecipado**: O vencimento das dívidas do devedor e dos sócios ilimitada e solidariamente responsáveis
- **Suspensão da fluência dos juros**: A suspensão da fluência dos juros, com exceções como as obrigações com garantia real
- **Devedor**: A pessoa física ou jurídica que se comprometeu a pagar uma dívida
- **Sócios ilimitada e solidariamente responsáveis**: Os sócios da empresa que são responsáveis pela dívida em igualdade de condições
- **Garantia real**: Um bem que serve como garantia para a pagamento de uma dívida

### Referências legais
- Art. 77 da LFRE

### Dicas de prova
- Entenda a diferença entre vencimento antecipado e suspensão da fluência dos juros
- Conheça as exceções para a suspensão da fluência dos juros, como as obrigações com garantia real', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.231 (1)", "page_number": 231, "discipline": "Direito Empresarial", "legal_refs": ["Art. 77 da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:42:41.886068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=231", "doc_key": "f0a9eaebbfb2e966ffe4b0612699142c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a22e57e79507af5247c16edf729f183a34e558f0cbf52ac9e38de02a3c5332ce'),
  ('cpiuris2025::ef10f06190024a0bdd45855f49bd0552', 'doutrina', 'cp_iuris', 'Direito Empresarial — Procedimento para apresentação de créditos contra falido', '## Procedimento para apresentação de créditos contra falido

O procedimento para apresentação de créditos contra falido envolve o prazo de 15 dias para alegação de possibilidade de crédito, com objeções específicas ao cálculo e classificação dos créditos.

### Conceitos
- **Crédito contra falido**: Direito do credor de receber uma indenização em caso de falência do devedor
- **Procedimento para apresentação de créditos**: Série de atos necessários para a apresentação de um crédito contra falido
- **Objeções ao cálculo e classificação dos créditos**: Reclamação feita pelo credor sobre a forma como os seus créditos foram calculados e classificados
- **Fazenda Pública**: Entidade pública que apresenta crédito contra falido

### Referências legais
- Art. 99, XIII da LFRE

### Dicas de prova
- Pergunte sobre o procedimento para apresentação de créditos contra falido
- Entenda a diferença entre objeções ao cálculo e classificação dos créditos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.231 (2)", "page_number": 231, "discipline": "Direito Empresarial", "legal_refs": ["Art. 99, XIII da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:43:19.823005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=231", "doc_key": "ef10f06190024a0bdd45855f49bd0552"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b3591efba1c85edb27796d3fb47e0d3456c13b1c82cfcdc9a961f029da8fdec7'),
  ('cpiuris2025::f3ed815b5570af4162e3b5d70d7dac86', 'doutrina', 'cp_iuris', 'Direito Empresarial — Reserva integral de créditos em falência', '## Reserva integral de créditos em falência

O novo dispositivo legal estabelece regras para a reserva integral de créditos em falência, incluindo a classificação e a inclusão nos quadros-gerais de credores.

### Conceitos
- **Reserva integral de créditos**: Princípio que estabelece que os créditos devem ser reservados integralmente até o julgamento definitivo.
- **Classificação dos créditos**: A classificação dos créditos é fundamental para a reserva integral de créditos em falência.
- **Quadro-geral de credores**: O quadro-geral de credores é o registro oficial dos credores da falência.

### Referências legais
- Art. 7º-A, § 3º

### Dicas de prova
- Entenda a classificação dos créditos e a importância do quadro-geral de credores.
- Conheça as regras para a reserva integral de créditos em falência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.232 (1)", "page_number": 232, "discipline": "Direito Empresarial", "legal_refs": ["Art. 7º-A, § 3º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:43:49.559009+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=232", "doc_key": "f3ed815b5570af4162e3b5d70d7dac86"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2fffe572fc995835d34d4492da45308a334e53e2dbedae2d7a75657c95aed010'),
  ('cpiuris2025::4980aa27925547bef9d16f6842713588', 'doutrina', 'cp_iuris', 'Direito Empresarial — Arrecadação dos bens em falência', '## Arrecadação dos bens em falência

Regra sobre a arrecadação dos bens do falido após a decretação da falência.

### Conceitos
- **Falência**: Processo que determina a dissolução de uma empresa
- **Administrador Judicial**: Pessoa responsável pela administração dos bens do falido
- **Arrecadação**: Ato de coletar e reunir os bens do falido

### Referências legais
- Art. 114 da Constituição Federal
- Código de Processo Civil

### Dicas de prova
- Entenda a noção de falência e seu impacto na administração dos bens do falido
- Conheça o papel do administrador judicial nesse processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.232 (2)", "page_number": 232, "discipline": "Direito Empresarial", "legal_refs": ["Art. 114 da Constituição Federal", "Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:44:10.879433+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=232", "doc_key": "4980aa27925547bef9d16f6842713588"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '71f5dca3583ed9bd6e63027f1ab85e7b22072ac4293250d818784c224e152726'),
  ('cpiuris2025::2b00a884e0a7e7dca0d4a74e53f084af', 'doutrina', 'cp_iuris', 'Direito Empresarial — Avaliação dos bens em falência e recuperacional', '## Avaliação dos bens em falência e recuperacional

O artigo 108 da LFRE estabelece que a avaliação dos bens é necessária para determinar a massa falida objetiva. A arrecadação de todos os bens do devedor é efeito específico da falência, com exceção de bens absolutamente impenhoráveis.

### Conceitos
- **Massa Falida Objetiva**: Ativo do devedor submetido à execução concursal falimentar
- **Responsabilidade dos Sócios**: Ilimitada ou limitada, dependendo do tipo de sociedade
- **Desconsideração da Personalidade Jurídica**: Processo que visa responsabilizar os sócios por atos da sociedade

### Referências legais
- Art. 108 da LFRE
- Art. 114-A da LFRE

### Jurisprudência
- Enunciado 48 das Jornadas de Direito Comercial do CJF

### Dicas de prova
- Entenda a diferença entre responsabilidade ilimitada e limitada dos sócios
- Conheça o conceito de massa falida objetiva e sua importância na falência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.233 (1)", "page_number": 233, "discipline": "Direito Empresarial", "legal_refs": ["Art. 108 da LFRE", "Art. 114-A da LFRE"], "jurisprudence": ["Enunciado 48 das Jornadas de Direito Comercial do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T05:44:52.515758+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=233", "doc_key": "2b00a884e0a7e7dca0d4a74e53f084af"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3b06484f1aad198fea2045cbc3219f71d0f48869310c92e4b870eac9b38e7be7'),
  ('cpiuris2025::810ea68fb2322bfca4fb35cde0dbd059', 'doutrina', 'cp_iuris', 'Direito Empresarial — Venda dos bens arrecadados em falência', '## Venda dos bens arrecadados em falência

O administrador judicial deve iniciar a venda dos bens arrecadados antes de formar o quadro-geral de credores, dentro de prazos específicos para bens móveis e imóveis.

### Conceitos
- **Administrador Judicial**: O responsável pela gestão dos bens da falência.
- **Venda de Bens**: A realização do ativo, com o objetivo de juntar dinheiro para pagamento dos credores habilitados.
- **Prazos para Venda**: 30 dias para bens móveis e 60 dias para bens imóveis.
- **Relatório**: O documento apresentado pelo administrador judicial após a venda dos bens arrecadados.
- **Avaliação de Bens**: A determinação do valor dos bens arrecadados, que pode ser feita pelo administrador judicial ou por avaliadores contratados.
- **Lei n.º 14.112/2020**: A lei que alterou o prazo para a venda de bens em falência.
- **Quadro-Geral de Credores**: O registro dos credores habilitados na falência, que deve ser formado antes da venda dos bens.

### Referências legais
- Art. 22, III, “g” e “h” da LFRE
- Art. 139 da LFRE
- Art. 140, § 2º da LFRE

### Dicas de prova
- Pergunte sobre o prazo para a venda de bens em falência.
- Entenda a diferença entre a avaliação e a venda dos bens arrecadados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.233 (2)", "page_number": 233, "discipline": "Direito Empresarial", "legal_refs": ["Art. 22, III, “g” e “h” da LFRE", "Art. 139 da LFRE", "Art. 140, § 2º da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:45:30.897086+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=233", "doc_key": "810ea68fb2322bfca4fb35cde0dbd059"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '4edf296d11958c9d87c9992ccea80804d713cdb9d00c42dcba2a31ae8af6b338'),
  ('cpiuris2025::86cd1da79122455a16cd3d69809d65b3', 'doutrina', 'cp_iuris', 'Direito Empresarial — Venda de Ativos em Falência e Recuperação Judicial', '## Venda de Ativos em Falência e Recuperação Judicial

A Lei Federal de Recuperação e Reorganização Econômica (LFRE) estabelece as formas de venda de ativos em falência e recuperação judicial, com preferência para alienação da empresa em bloco, seguida pela alienação das filiais ou unidades produtivas isoladamente.

### Conceitos
- **Alienação conjunta**: Venda de ativos juntos, inclusive a empresa ou suas filiais
- **Ordem de preferência**: Definição da ordem em que os credores serão sub-rogados no produto da realização do ativo
- **Sucessão empresarial**: Sucessão das obrigações do devedor após a alienação dos ativos
- **Sucessão tributária**: Sucessão das obrigações tributárias do devedor após a alienação dos ativos
- **Sucessão trabalhista**: Sucessão das obrigações trabalhistas do devedor após a alienação dos ativos

### Referências legais
- Art. 140 da LFRE
- Art. 141 da LFRE
- Art. 142 da LFRE
- Art. 83 da LFRE

### Dicas de prova
- Entenda a ordem de preferência estabelecida pela LFRE
- Conheça as exceções à regra de sucessão empresarial, tributária e trabalhista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.234 (1)", "page_number": 234, "discipline": "Direito Empresarial", "legal_refs": ["Art. 140 da LFRE", "Art. 141 da LFRE", "Art. 142 da LFRE", "Art. 83 da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:46:09.830930+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=234", "doc_key": "86cd1da79122455a16cd3d69809d65b3"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '417b99abb1d0f88447929241a65c5363a5bc3c350ccd37280c4596d69a87c987'),
  ('cpiuris2025::6f811fcf70c86c872ca9a3346032a640', 'doutrina', 'cp_iuris', 'Direito Empresarial — Leilão de Bens em Falência', '## Leilão de Bens em Falência

Regras para leilão de bens em falência, incluindo prazo máximo de 180 dias e aplicação do Código de Processo Civil.

### Conceitos
- **Lei n.º 13.105**: Código de Processo Civil
- **Avaliação do bem**: Valor estimado do bem a ser alienado
- **Chamada em primeira, segunda e terceira instância**: Ordem em que os leiloeiros apresentarão ofertas
- **Prazo máximo de 180 dias**: Tempo limite para a realização do leilão

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a ordem das chamadas e o prazo máximo de 180 dias
- Conheça as regras específicas do Código de Processo Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.234 (2)", "page_number": 234, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:46:44.338295+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=234", "doc_key": "6f811fcf70c86c872ca9a3346032a640"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '906dff8696616e54c00dea1dcd8c2ec5615b93a2caffc4152de7bbd12d6e59c4'),
  ('cpiuris2025::5f51ead0436517eecc99a84f634cbf0e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Alienação de Bens em Falência', '## Alienação de Bens em Falência

Regulamenta a alienação de bens em falência, incluindo as formas de alienação e os prazos para impugnações.

### Conceitos
- **Impugnação**: Reclamação apresentada por credor ou Ministério Público sobre a alienação do bem
- **Alienação Judicial**: Alienação de bens realizada em processo judicial, considerada para todos os fins e efeitos
- **Prazo de Impugnação**: Período de 48 horas após a arrematação para apresentar impugnações
- **Oferta Firme**: Oferta feita por terceiro para adquirir o bem, vinculante para o impugnante e o terceiro ofertante

### Referências legais
- Art. 143 da LFRE
- Lei n.º 14.112/2020

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre alienação ordinária e extraordinária
- Conheça o prazo de impugnação e as condições para apresentar uma
- Aprenda a distinguir entre oferta firme e terceiro ofertante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.235 (1)", "page_number": 235, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143 da LFRE", "Lei n.º 14.112/2020"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T05:47:17.151080+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=235", "doc_key": "5f51ead0436517eecc99a84f634cbf0e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3bb585c78cb595e2f845f739497e3b218dd349f60520a04fb4c4f7dacb0284e6'),
  ('cpiuris2025::30b174bcc3c525266a668612d48c42bf', 'doutrina', 'cp_iuris', 'Direito Empresarial — Alienação Judicial e Falências', '## Alienação Judicial e Falências

Rege a alienação judicial de bens da massa falida, incluindo modalidades não previstas no art. 142, e disposições sobre doações e transferência para sociedades ou fundos.

### Conceitos
- **Alienação Judicial**: Processo pelo qual os bens de um devedor são vendidos para atender às dívidas
- **Falências**: Situação jurídica em que o devedor não pode pagar suas dívidas
- **Doação**: Transferência gratuita de bens para terceiros sem remuneração
- **Transferência para sociedades ou fundos**: Mudança de propriedade dos bens da massa falida para uma empresa ou fundo

### Referências legais
- Art. 144-A
- Art. 145
- Art. 141

### Dicas de prova
- Entenda a diferença entre alienação judicial e doação.
- Conheça as modalidades de transferência para sociedades ou fundos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.235 (2)", "page_number": 235, "discipline": "Direito Empresarial", "legal_refs": ["Art. 144-A", "Art. 145", "Art. 141"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:47:42.590177+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=235", "doc_key": "30b174bcc3c525266a668612d48c42bf"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b7b56ed3dfc9019d2cdd43fe65495ea19150724450e9f56518748fef77b454d3'),
  ('cpiuris2025::881158a4a30293bd88fbfbae4c0278a6', 'doutrina', 'cp_iuris', 'Direito Empresarial — Processo de Falência e Recuperação', '## Processo de Falência e Recuperação

O processo de falência envolve a venda dos bens do devedor para pagar os créditos, com a realização do ativo sendo feita pelo administrador judicial. Após a venda, o administrador apresenta as contas e o juiz proferirá uma sentença declarando encerrado o processo.

### Conceitos
- **Assembleia Geral de Credores**: Reunião dos credores para decidir sobre a falência do devedor
- **Administrador Judicial**: Pessoal designado pelo juiz para administrar o processo de falência
- **Venda de Bens**: Procedimento pelo qual os bens do devedor são vendidos para pagar os créditos
- **Restituição**: Restauração da posse ou controle sobre um bem que foi arrebatado no processo de falência

### Referências legais
- Art. 46 da LFRE
- Art. 85 da LFRE
- Decreto-Lei n.º 911/69

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância do administrador judicial na realização do ativo
- Conheça as regras para a restituição de bens arrebatados no processo de falência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.236 (1)", "page_number": 236, "discipline": "Direito Empresarial", "legal_refs": ["Art. 46 da LFRE", "Art. 85 da LFRE", "Decreto-Lei n.º 911/69"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T05:48:27.875292+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=236", "doc_key": "881158a4a30293bd88fbfbae4c0278a6"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '231d89cadd6241dc763107ffa89cdf6ced0d91b8e90c2dc2e74c8268c0fc638c'),
  ('cpiuris2025::88cd18900af17d324b5176b284840cf8', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falência e Restituição em Dinheiro', '## Falência e Restituição em Dinheiro

Regra para a restituição em dinheiro em caso de falência, incluindo hipóteses de venda ou não existência do bem.

### Conceitos
- **Certificado de Depósito Bancário (CDB)**: Documento que confirma o depósito de dinheiro em uma instituição financeira.
- **Transferência da propriedade**: Ocorre quando o depositante assume a posição de credor dos valores depositados.
- **Avaliação do bem**: Valor estimado do bem que não existe mais, utilizado para calcular a restituição em dinheiro.
- **Preço de venda**: Valor obtido pela venda do bem, utilizado para calcular a restituição em dinheiro.

### Referências legais
- Art. 86 da Lei n.º 14.112/2020

### Jurisprudência
- REsp 1.801.031-SP
- Súmula 416 do STJ

### Dicas de prova
- Entenda a transferência de propriedade nos contratos de depósito bancário.
- Conheça as hipóteses de restituição em dinheiro e suas condições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.236 (2)", "page_number": 236, "discipline": "Direito Empresarial", "legal_refs": ["Art. 86 da Lei n.º 14.112/2020"], "jurisprudence": ["REsp 1.801.031-SP", "Súmula 416 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T05:48:55.737742+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=236", "doc_key": "88cd18900af17d324b5176b284840cf8"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2daa8f925f482137ec6e5403b7a019294b9e9154c110768bcd3d3c061addbcb3'),
  ('cpiuris2025::dbe99dca55ad164ab684fb28646339fe', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falências e Recuperação de Créditos', '## Falências e Recuperação de Créditos

Regras para a falência e recuperação de créditos, incluindo o prazo total da operação e os valores entregues ao devedor.

### Conceitos
- **Prazo total da operação**: O prazo total da operação, inclusive eventuais prorrogações, não deve exceder as normas específicas da autoridade competente.
- **Valores entregues ao devedor**: Os valores entregues ao devedor pelo contratante de boa-fé na hipótese de revogação ou ineficácia do contrato, conforme disposto no art. 136 desta Lei.
- **Fazendas Públicas**: As Fazendas Públicas são relativamente a tributos passíveis de retenção na fonte, de descontos de terceiros ou de sub-rogação e a valores recebidos pelos agentes arrecadadores e não recolhidos aos cofres públicos.
- **Patrimônio separado**: O patrimônio separado é o que não integra a massa falida e pode ser afetado ou segregado, permitindo-se que terceiros firmem promessa de compra e venda desses imóveis sem que esses bens respondam por eventuais dívidas da sociedade.

### Referências legais
- Art. 136 da Lei n.º 11.101/2005
- Art. 84 da Lei n.º 11.101/2005

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de prazo total da operação e como ele se relaciona com as normas específicas da autoridade competente.
- Conheça os valores entregues ao devedor e como eles são calculados.
- Aprenda sobre as Fazendas Públicas e como elas se relacionam com a retenção na fonte e descontos de terceiros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.237 (1)", "page_number": 237, "discipline": "Direito Empresarial", "legal_refs": ["Art. 136 da Lei n.º 11.101/2005", "Art. 84 da Lei n.º 11.101/2005"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T05:49:42.524366+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=237", "doc_key": "dbe99dca55ad164ab684fb28646339fe"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '436391cacef29d69984ef2f241705bedd98b3a793c49db8e1405d38a77ddac32'),
  ('cpiuris2025::5b84871b0025921012abe2bc05db6daf', 'doutrina', 'cp_iuris', 'Direito Empresarial — Procedimento Falimentar e Classificação de Créditos', '## Procedimento Falimentar e Classificação de Créditos

O procedimento falimentar é regido pelo princípio par conditio creditorium, que determina um tratamento igualitário aos credores, independentemente das prioridades dos créditos. A Lei n.º 14.112/2020 introduziu alterações significativas nos créditos extraconcursais e sujeitos ao concurso de credores.

### Conceitos
- **Par conditio creditorium**: Princípio que determina um tratamento igualitário aos credores, independentemente das prioridades dos créditos.
- **Créditos extraconcursais**: Créditos que não estão sujeitos ao concurso de credores
- **Créditos sujeitos ao concurso de credores**: Créditos que estão sujeitos à administração judicial e podem ser pagos após a habilitação dos credores concursais

### Referências legais
- Art. 150 da LFRE
- Art. 151 da LFRE
- Lei n.º 14.112/2020

### Dicas de prova
- Entenda o princípio par conditio creditorium e sua aplicação prática.
- Conheça as alterações introduzidas pela Lei n.º 14.112/2020 nos créditos extraconcursais e sujeitos ao concurso de credores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.237 (2)", "page_number": 237, "discipline": "Direito Empresarial", "legal_refs": ["Art. 150 da LFRE", "Art. 151 da LFRE", "Lei n.º 14.112/2020"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:50:24.607134+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=237", "doc_key": "5b84871b0025921012abe2bc05db6daf"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '93f8cc892eb5693ffcf9276b519da3978cc3eed32d872c1b12b1af5fd7cc0527'),
  ('cpiuris2025::2db0108be595b536c9e9f6e0bc1e5e14', 'doutrina', 'cp_iuris', 'Direito Empresarial — Pagamento de créditos trabalhistas em falências', '## Pagamento de créditos trabalhistas em falências

O administrador judicial deve pagar os créditos trabalhistas vencidos nos últimos três meses da falência, até o limite de cinco salários-mínimos por trabalhador, assim que houver disponibilidade em caixa.

### Conceitos
- **Crédito trabalhista**: direito do trabalhador à remuneração vencida
- **Falência**: processo judicial que visa liquidar a massa de um devedor insolvente
- **Administrador judicial**: pessoa responsável pela gestão da massa falida
- **Disponibilidade em caixa**: quantidade de dinheiro disponível para pagamento de dívidas
- **Créditos extraconcursais**: créditos que têm prioridade sobre os créditos concursais

### Referências legais
- Art. 99 da Lei n.º 11.1017/2005
- Art. 151 da Lei n.º 11.1017/2005
- Art. 84 da Lei n.º 11.1017/2005

### Dicas de prova
- Entenda a ordem de prioridade dos créditos extraconcursais
- Conheça as exceções ao pagamento de créditos trabalhistas em falências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.238 (1)", "page_number": 238, "discipline": "Direito Empresarial", "legal_refs": ["Art. 99 da Lei n.º 11.1017/2005", "Art. 151 da Lei n.º 11.1017/2005", "Art. 84 da Lei n.º 11.1017/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:51:33.084987+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=238", "doc_key": "2db0108be595b536c9e9f6e0bc1e5e14"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e68ca046e2d5e0df4e5a4398cacaa82422b4a351b3e874628ad2f9506dcb507f'),
  ('cpiuris2025::711b1ba31487f8cc3d4219337588b57e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Classificação dos créditos na falência', '## Classificação dos créditos na falência

A classificação dos créditos na falência é determinada pela Lei da Falência e Rescisão de Prazos (LFRE), com prioridade para os créditos trabalhistas e decorrentes de acidentes de trabalho.

### Conceitos
- **Crédito trabalhista**: Crédito derivado da legislação trabalhista
- **Acidente de trabalho**: Crédito decorrente de acidente de trabalho
- **Legislação trabalhista**: Lei que regula os direitos dos trabalhadores

### Referências legais
- Art. 83 da LFRE

### Dicas de prova
- Prioridade para os créditos trabalhistas e decorrentes de acidentes de trabalho
- Ordem estabelecida no art. 83 da LFRE', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.238 (2)", "page_number": 238, "discipline": "Direito Empresarial", "legal_refs": ["Art. 83 da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:51:54.782956+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=238", "doc_key": "711b1ba31487f8cc3d4219337588b57e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5e232bd44efc587a6964430e056079046197905d2c835addc15c6a420c2dc503'),
  ('cpiuris2025::bde89c545d35fda54b80ae3b08f77fd9', 'doutrina', 'cp_iuris', 'Direito Empresarial — Créditos em Falência', '## Créditos em Falência

Listagem dos diferentes tipos de créditos que podem ser priorizados na falência, de acordo com a Lei n.º 14.112/2020.

### Conceitos
- **Crédito gravado**: Crédito com direito real de garantia até o limite do valor do bem gravado
- **Crédito tributário**: Crédito tributário, independentemente da sua natureza e do tempo de constituição, exceto os créditos extraconcursais e as multas tributárias
- **Crédito quirográfico**: Crédito não previsto nos demais incisos deste artigo, incluindo saldos dos créditos não cobertos pelo produto da alienação dos bens vinculados ao seu pagamento e saldos dos créditos derivados da legislação trabalhista
- **Crédito subordinado**: Crédito previsto em lei ou em contrato, incluindo créditos dos sócios e dos administradores sem vínculo empregatício cuja contratação não tenha observado as condições estritamente comutativas e as práticas de mercado
- **Juros vencidos**: Juros que venceram após a decretação da falência, conforme previsto no art. 124 desta Lei

### Referências legais
- Art. 14.112 da Lei

### Dicas de prova
- Entenda a ordem de prioridade dos créditos em falência
- Conheça as diferentes categorias de créditos que podem ser priorizados na falência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.239 (1)", "page_number": 239, "discipline": "Direito Empresarial", "legal_refs": ["Art. 14.112 da Lei"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:52:44.381311+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=239", "doc_key": "bde89c545d35fda54b80ae3b08f77fd9"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f064e1d48d3d9d8138f093b62f0c1a78da51d54d394503b07b3b130c5e69434e'),
  ('cpiuris2025::70111dedaa5e33d13f43ada827ca4975', 'doutrina', 'cp_iuris', 'Direito Empresarial — Natureza e Classificação de Créditos em Falências', '## Natureza e Classificação de Créditos em Falências

A Lei n.º 14.112/2020 introduziu mudanças significativas na classificação de créditos em falências, incluindo a exclusão de prioridade para créditos com privilégio especial e geral, que agora são considerados quirografários.

### Conceitos
- **Crédito Quirografário**: Crédito não protegido por privilégio especial ou geral
- **Privilégio Especial**: Direito que concede prioridade ao pagamento de um crédito em relação a outros
- **Privilégio Geral**: Direito que concede prioridade ao pagamento de um crédito em relação a todos os outros
- **Créditos Trabalhistas**: Créditos relacionados à contratação de trabalhadores

### Referências legais
- Art. 83 da Lei n.º 14.112/2020
- Súmula 395 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Classificação de Créditos em Falências

### Dicas de prova
- Entenda a diferença entre privilégio especial e geral
- Conheça as exceções ao limite de 150 salários-mínimos por credor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.239 (2)", "page_number": 239, "discipline": "Direito Empresarial", "legal_refs": ["Art. 83 da Lei n.º 14.112/2020", "Súmula 395 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Classificação de Créditos em Falências"], "confidence": 0.8, "extracted_at": "2026-05-27T05:53:17.154297+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=239", "doc_key": "70111dedaa5e33d13f43ada827ca4975"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '29eaa780a024bacb4b4ba08ba2fb418bbc83cb2d6b272305690acc4fb2c95530'),
  ('cpiuris2025::5e58b0e38295c79639fac9113ab643c8', 'doutrina', 'cp_iuris', 'Direito Empresarial — Créditos com garantia real e falimentar', '## Créditos com garantia real e falimentar

Discute-se a natureza dos créditos com garantia real em relação aos trabalhistas e aos credores com garantia real, destacando a diferença na quebra do crédito.

### Conceitos
- **Crédito com garantia real**: Crédito que tem como base um bem gravado
- **Crédito trabalhista**: Crédito decorrente de relações de trabalho
- **Preferência no pagamento**: Prioridade na execução do crédito em relação a outros credores
- **Isonômia**: Tratamento igualitário para situações semelhantes

### Referências legais
- Art. 83, inciso I, do Decreto-Lei n. 7.661/1945
- Art. 44 da Lei n.º 4.886/1965

### Jurisprudência
- REsp 1.152.218/RS
- REsp 1.851.770
- REsp 1.799.041-PR, Informativo 645

### Dicas de prova
- Entenda a diferença entre créditos com garantia real e trabalhistas
- Conheça a preferência no pagamento e a isonomia nos processos de falência e recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.240 (1)", "page_number": 240, "discipline": "Direito Empresarial", "legal_refs": ["Art. 83, inciso I, do Decreto-Lei n. 7.661/1945", "Art. 44 da Lei n.º 4.886/1965"], "jurisprudence": ["REsp 1.152.218/RS", "REsp 1.851.770", "REsp 1.799.041-PR, Informativo 645"], "confidence": 0.8, "extracted_at": "2026-05-27T05:53:52.341632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=240", "doc_key": "5e58b0e38295c79639fac9113ab643c8"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'eaa794c706e361c2b402e096d0737a8f737190729b75fb3a49f6dd0b253de9e8'),
  ('cpiuris2025::fd23a0ab58677b216579f8c06a2afea9', 'doutrina', 'cp_iuris', 'Direito Empresarial — Voto dos Credores em Falências', '## Voto dos Credores em Falências

Os credores trabalhistas votam apenas na classe dos credores trabalhistas pelo valor total do seu crédito, enquanto os credores com garantia real votam tanto na classe dos credores com garantia real quanto na classe quirografária pelo valor excedente.

### Conceitos
- **Voto dos Credores**: O processo pelo qual os credores escolhem a ordem de recebimento de seus créditos em falência.
- **Credores Trabalhistas**: Os titulares de créditos trabalhistas que votam apenas na classe dos credores trabalhistas.
- **Credores com Garantia Real**: Os credores que têm garantia real sobre os bens do devedor e podem votar tanto na classe dos credores com garantia real quanto na classe quirografária.
- **Voto na Classe Quirografária**: O voto dos credores com garantia real pelo valor excedente sobre a garantia real.
- **Falência**: O processo em que o juiz é nomeado para liquidar os bens do devedor e distribuir os créditos entre os credores.
- **Ordem Interna**: A ordem estabelecida pelos artigos do Código de Tratamento da Insolvente Civil (CTN) para a recebimento dos créditos em falência.

### Referências legais
- Art. 187, parágrafo único, do CTN

### Jurisprudência
- Informativo 548 do STJ

### Dicas de prova
- Entenda a ordem interna para recebimento de créditos em falência.
- Conheça as diferenças entre os credores trabalhistas e os credores com garantia real.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.240 (2)", "page_number": 240, "discipline": "Direito Empresarial", "legal_refs": ["Art. 187, parágrafo único, do CTN"], "jurisprudence": ["Informativo 548 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T05:54:39.740206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=240", "doc_key": "fd23a0ab58677b216579f8c06a2afea9"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a68b5bd93facbcee76d845307f60c1f9ed0e244af82d9c067331629881d1a42f'),
  ('cpiuris2025::797d00cc7375e80173bc736685931232', 'doutrina', 'cp_iuris', 'Direito Empresarial — Créditos no Falimento', '## Créditos no Falimento

Resumo do texto sobre créditos tributários e outros tipos de créditos no processo de falência.

### Conceitos
- **Créditos Tributários**: Créditos da União, Estados e municípios
- **Créditos Quirografários**: Créditos sem especialidades, como contratos em geral
- **Créditos Subordinados**: Créditos relacionados a sócios, administradores e debêntures subordinadas
- **Créditos com Privilégio Especial**: Créditos com privilégio especial revogado
- **Créditos com Privilégio Geral**: Créditos com privilégio geral revogado
- **Multas**: Pagamento de multas contratuais e penalidades pecuniárias

### Referências legais
- Art. 187, do CTN; Súmula nº 563, do STF; ADPF 357

### Jurisprudência
- RE 123456
- Súmula nº 563, do STF

### Dicas de prova
- Entenda a ordem de prioridade de pagamento dos créditos tributários
- Conheça as diferenças entre créditos com privilégio especial e geral
- Identifique os tipos de créditos quirografários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.241", "page_number": 241, "discipline": "Direito Empresarial", "legal_refs": ["Art. 187, do CTN; Súmula nº 563, do STF; ADPF 357"], "jurisprudence": ["RE 123456", "Súmula nº 563, do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T05:55:15.718293+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=241", "doc_key": "797d00cc7375e80173bc736685931232"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c655a869092e3759881ba0709d33269d0c9794f50b415e6fba2eaeae7105cf4e'),
  ('cpiuris2025::b1c0e8e3cae836d9f76a99dc450cf930', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos para enquadrar como subordinado o crédito dos administradores sem vínculo empregatício', '## Requisitos para enquadrar como subordinado o crédito dos administradores sem vínculo empregatício

A Lei n.º 14.112/2020 estabelece requisito adicional para enquadrar como subordinado o crédito dos administradores sem vínculo empregatício, que é a não observância das condições estritamente comutativas e as práticas de mercado.

### Conceitos
- **Subordinado**: Crédito enquadrado como tal em virtude de não atender às condições estritamente comutativas e às práticas de mercado.
- **Credores subordinados**: Credores que têm direito à prioridade sobre os demais credores na falência do administrador sem vínculo empregatício.
- **Falência**: Processo judicial que visa liquidar a massa de um falido e distribuir seus bens entre os credores.

### Referências legais
- Art. 124 da LFRE
- Art. 154 da LFRE
- Art. 155 da LFRE
- Art. 156 da LFRE

### Dicas de prova
- Entenda a noção de subordinado e seus requisitos.
- Conheça as disposições específicas da Lei n.º 14.112/2020 sobre falências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.242 (1)", "page_number": 242, "discipline": "Direito Empresarial", "legal_refs": ["Art. 124 da LFRE", "Art. 154 da LFRE", "Art. 155 da LFRE", "Art. 156 da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:55:50.644573+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=242", "doc_key": "b1c0e8e3cae836d9f76a99dc450cf930"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1e3200cff12e39443f1491687f64bf6561b3949b363217527fc5df7c66d2ef8f'),
  ('cpiuris2025::1452980281cea684717f2919543ddb12', 'doutrina', 'cp_iuris', 'Direito Empresarial — Intimação Eletrônica e Falência', '## Intimação Eletrônica e Falência

A intimação eletrônica é obrigatória para as Fazendas Públicas e determina a baixa da falida no CNPJ. A sentença de encerramento será publicada por edital e caberá apelação.

### Conceitos
- **Intimação Eletrônica**: Método de comunicação eletrônica para notificação
- **Falência**: Processo que determina a inabilitação do falido para exercer atividade empresarial
- **CNPJ**: Cadastro Nacional da Pessoa Jurídica, expedido pela Secretaria Especial da Receita Federal do Brasil
- **Lei n.º 14.112/2020**: Lei que estabelece as regras para a intimação eletrônica e a falência

### Referências legais
- Art. 102 da LFRE
- Art. 181 da LFRE

### Dicas de prova
