  ('cpiuris2025::d79b6b697d130cb61f4237a40001722e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Declaração de Extinção das Obrigações do Falido', '## Declaração de Extinção das Obrigações do Falido

O falido pode requerer ao juiz da falência que suas obrigações sejam declaradas extintas por sentença, após o período de inabilitação. A declaração é feita com base nas hipóteses do artigo 158 da LFRE, que exigem o pagamento de todos os créditos ou mais de 25% dos créditos quirografários.

### Conceitos
- **Declaração de Extinção**: Procedimento pelo qual as obrigações do falido são consideradas extintas
- **Hipóteses do Art. 158**: Pagamento de todos os créditos, pagamento de mais de 25% dos créditos quirografários ou decurso de prazo determinado
- **Prazo de Inabilitação**: Período durante o qual o falido não pode requerer a declaração de extinção das obrigações

### Referências legais
- Art. 158 da LFRE
- Art. 159 da LFRE
- Lei nº 14.112/20

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda as hipóteses do artigo 158 e como elas se aplicam à declaração de extinção das obrigações do falido
- Conheça o procedimento para a declaração de extinção das obrigações, incluindo os prazos e formalidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.243 (1)", "page_number": 243, "discipline": "Direito Empresarial", "legal_refs": ["Art. 158 da LFRE", "Art. 159 da LFRE", "Lei nº 14.112/20"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T05:57:06.044631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=243", "doc_key": "d79b6b697d130cb61f4237a40001722e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2bd840a080a3f6cc42b765931105d0449ec0c3d661c17008f8affdb2bd1a6e74'),
  ('cpiuris2025::e7e47d80a9710dbb09bff5cd541d235b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falências e Recursos', '## Falências e Recursos

Regras sobre apelação, rescisão e extinção de obrigações no processo de falência.

### Conceitos
- **Apelação**: Recurso apresentado contra a sentença
- **Rescisão**: Ação para anular ou cancelar um ato jurídico
- **Extinção de Obrigações**: Fim da obrigação de pagar uma dívida
- **Prescrição**: Período após o qual uma ação não pode ser iniciada
- **Responsabilidade Ilimitada**: Forma de responsabilidade que não tem limite

### Referências legais
- Art. 159-A da Lei n.º 11.1015
- Art. 160 da Lei n.º 11.1015

### Dicas de prova
- Entenda a diferença entre apelação e rescisão.
- Conheça as regras sobre prescrição e extinção de obrigações em falências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.243 (2)", "page_number": 243, "discipline": "Direito Empresarial", "legal_refs": ["Art. 159-A da Lei n.º 11.1015", "Art. 160 da Lei n.º 11.1015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:57:31.489656+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=243", "doc_key": "e7e47d80a9710dbb09bff5cd541d235b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd6564c357c037322192459c503deed0223f2c778f17e2cb76371f8d3cfd71967')
